/* Generated by tools/build_data.py from the three 1 Exam Prep practice tests. Do not edit by hand. */
window.QUESTIONS = [{"id":"1-1","exam":1,"num":1,"stem":"\"Hard Records\", such as payroll, employment contracts, sales & purchase records must be retained for __________ years.","options":["2","3","4","5"],"answer":1,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-30"},{"book":"FCM","eds":["2017"],"loc":"5-30"}],"exp":"\"Hard records\" (payroll, employment contracts, sales and purchase records) are kept **3 years**. \"Soft records\" such as timecards and time sheets only need **2 years**.","tip":"Hard = 3, Soft = 2. Hard records are harder to replace, so they're kept longer.","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-30  ·  Recordkeeping - Payroll","2017: 5-30  ·  Payroll - Records"],"lock":1},{"id":"1-2","exam":1,"num":2,"stem":"\"Soft Records\", such as timecards and time sheets must be retained for __________ years.","options":["2","3","4","5"],"answer":0,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-30"},{"book":"FCM","eds":["2017"],"loc":"5-30"}],"exp":"Soft records (timecards, time sheets) are kept **2 years**. Hard records (payroll, contracts, sales and purchase records) are kept 3.","tip":"Hard = 3, Soft = 2.","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-30  ·  Recordkeeping - Payroll","2017: 5-30  ·  Payroll - Records"],"lock":1},{"id":"1-3","exam":1,"num":3,"stem":"FS §489 requires complete financial and business records to be retained for __________ years.","options":["2","3","4","5"],"answer":1,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-102","stat":"489.124(1)"},{"book":"FCM","eds":["2021"],"loc":"2-78","stat":"489.124(1)"},{"book":"FCM","eds":["2017"],"loc":"2-20"},{"book":"FCM","eds":["2017"],"loc":"2-90","stat":"489.124(1)"}],"exp":"§489.124(1) requires licensed contractors to keep complete financial and business records for the immediately preceding **3 years**. Expect this one in several forms.","tip":"Chapter 489 records = 3 years. IRS employment tax = 4. OSHA logs = 5.","ref":["Florida Contractors Manual  ·  2025: 2-102  ·  Licensing - Record Keeping","§489.124(1)","2021: 2-78  ·  Licensing - Record Keeping","§489.124(1)","2017: 2-20, 2-90  ·  Recordkeeping - Licensing, Const","§489.124(1)"],"lock":1},{"id":"1-4","exam":1,"num":4,"stem":"OSHA logs 300/300A must be retained for __________ calendar years.","options":["2","3","4","5"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"7-16"},{"book":"FCM","eds":["2017"],"loc":"7-16"}],"exp":"OSHA 300 logs, the 300A summary and the 301 forms are kept **5 years** after the end of the calendar year they cover, at each establishment.","tip":"OSHA = 5 years. Picture the 5 in \"300\".","ref":["Florida Contractors Manual  ·  2025 & 2021: 7-16  ·  OSHA - Recordkeeping","2017: 7-16  ·  OSHA - Retention of Records"],"lock":1},{"id":"1-5","exam":1,"num":5,"stem":"Per the IRS, records of employment taxes must be retained for __________ years.","options":["2","3","4","5"],"answer":2,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"3-142"},{"book":"FCM","eds":["2021"],"loc":"3-160"},{"book":"FCM","eds":["2017"],"loc":"3-154"}],"exp":"The IRS requires employment tax records to be kept at least **4 years** after the tax is due or paid, whichever is later.","tip":"Records ladder: soft 2 → hard 3 → Ch. 489 3 → IRS 4 → OSHA 5.","ref":["Florida Contractors Manual  ·  2025: 3-142  ·  Recordkeeping - IRS, Taxes","2021: 3-160  ·  Recordkeeping - IRS, Taxes","2017: 3-154  ·  Record Retention - IRS"],"lock":1},{"id":"1-6","exam":1,"num":6,"stem":"The Department, for the boards under its jurisdiction, shall have the authority to close and terminate deficient license application files __________ year (s) after the board or the department notifies the applicant of the deficiency.","options":["1","2","3","4"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.203(10)(a)"}],"exp":"Under §455.203(10), DBPR may close and terminate a deficient license application file **2 years** after it notifies the applicant of the deficiency.","ref":["Florida Statute 455  ·  §455.203(10)(a)  ·  TOC: Department; Power & Duties"],"lock":1},{"id":"1-7","exam":1,"num":7,"stem":"I-9 Forms must be retained __________.","options":["3 years from date of hire","1 year from date employment ends","3 years from date employment ends","Either A or B, whichever is the latest date"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-58"},{"book":"FCM","eds":["2017"],"loc":"5-58"}],"exp":"Keep an I-9 for **3 years after the date of hire or 1 year after employment ends, whichever is later**. Both clocks apply, so the answer is \"either A or B, whichever is the latest date.\"","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-58  ·  Recordkeeping- Immigration Reform","2017: 5-58  ·  Forms - IRS - I-9"],"lock":1},{"id":"1-8","exam":1,"num":8,"stem":"Tests, inspections, and approvals of work shall be paid for by the __________; if tests are failed, additional costs shall be borne by __________.","options":["Owner, Owner","Owner, Contractor","Owner, Architect","Contractor, Contractor"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"13.4.1"},{"book":"A201","eds":null,"loc":"13.4.3"}],"exp":"A201 §13.4.1: the **Owner** pays for the tests, inspections and approvals the contract documents require. §13.4.3: if a test shows the work fails, the **Contractor** pays the extra costs.","tip":"The owner pays to look. The contractor pays when it fails.","ref":["AIA Document A201, 2017  ·  13.4.1, 13.4.3  ·  Optional TAB: Tests and Inspections"]},{"id":"1-9","exam":1,"num":9,"stem":"The maximum hours of work allowed per week for a 16-year-old while school is in session is __________ hours.","options":["12","18","20","30"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-32"}],"exp":"Florida child labor law: 16- and 17-year-olds may work up to **30 hours a week** while school is in session (and no more than 8 hours on a day before a school day).","tip":"16 and 17 both get 30 hours per school week.","ref":["Florida Contractors Manual  ·  5-32  ·  Child Labor (See) - Laws - Child labor"],"lock":1},{"id":"1-10","exam":1,"num":10,"stem":"A job has a cost to date of $34,000. The cost to complete is estimated to be $91,000. If the contractor wanted to make a 12% profit, the contract price would be __________.","options":["$125,000","$127,400","$140,000","$157,340"],"answer":2,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"87"}],"exp":"Total cost = cost to date + cost to complete = $34,000 + $91,000 = $125,000. Add the 12% profit: $125,000 × 1.12 = **$140,000**.","tip":"Total cost first, then multiply by (1 + profit %).","calc":1,"ref":["Builder's Guide to Accounting  ·  87","$34,000 + $91,000 = $125,000 (cost to date + cost to complete = total cost)","$125,000 x 1.12 (12%) = $140,000 total contract"],"lock":1},{"id":"1-11","exam":1,"num":11,"stem":"The __________ regulates the FLSA.","options":["Department of Labor","Department of Business and Professional Regulation","Construction Industry Licensing Board","Florida Department of State"],"answer":0,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-15"}],"exp":"The Fair Labor Standards Act (minimum wage, overtime, child labor) is enforced by the U.S. **Department of Labor** through its Wage and Hour Division. DBPR and the CILB regulate licensing, not wages.","ref":["Florida Contractors Manual  ·  5-15  ·  Acts - FLSA"]},{"id":"1-12","exam":1,"num":12,"stem":"An advantage of a bad debt reserve is that _________________________________.","options":["It reduces tax liability for earned profit","It increases assets","It increases profits","It simplifies accounting procedures"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"64"}],"exp":"Per the Builder's Guide, a bad debt reserve lets you write off expected uncollectible accounts against earnings, which **reduces tax liability on earned profit**. It does not increase assets or profit, and it adds an accounting step.","ref":["Builder's Guide to Accounting  ·  64  ·  Bad Debt Accounting - estimating"]},{"id":"1-13","exam":1,"num":13,"stem":"Employees __________ would probably not be subject to the overtime regulations.","options":["With fluctuating workweeks","Who are employed in the capacity of outside salesman","Who are piece workers","Who are salaried"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-17"}],"exp":"**Outside salespeople** are exempt from FLSA overtime. Being salaried alone does not make someone exempt; they must also pass the duties tests. Piece workers and employees on a fluctuating workweek still earn overtime.","tip":"Salaried ≠ exempt. Outside sales = exempt.","ref":["Florida Contractors Manual  ·  5-17  ·  Overtime Pay"]},{"id":"1-14","exam":1,"num":14,"stem":"The Buy American Act does not include __________.","options":["Mexico","Canada","Brazil","Europe"],"answer":2,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-88"}],"exp":"The manual lists Mexico, Canada and European countries as covered by trade agreements under the Buy American Act. **Brazil** is the one that is not included.","ref":["Florida Contractors Manual  ·  10-88  ·  TAB: Buy American Act"]},{"id":"1-15","exam":1,"num":15,"stem":"Per FLSA, an executive employee __________.","options":["Whose primary duty is management of the enterprise in which the employee is employed or of a customarily recognized department or subdivision","Customarily directs the work of 2 or more employees","Has the authority to hire or fire other employees","All of the above"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-19"},{"book":"FCM","eds":["2017"],"loc":"5-19"}],"exp":"The FLSA executive exemption requires **all** of these: the primary duty is managing the enterprise or a recognized department, the employee customarily directs 2 or more employees, and they can hire or fire (or their recommendations carry weight). There is also a salary test.","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-19  ·  TOC: FLSA - Test for Executive","Exemption","2017: 5-19  ·  Employee - Executive"],"lock":1},{"id":"1-16","exam":1,"num":16,"stem":"An individual who smokes in a non-smoking area is subject to a fine of __________ for a repeat offense.","options":["$100","$250","$500","$1,000"],"answer":2,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-49"}],"exp":"Under the Florida Clean Indoor Air Act, smoking in a no-smoking area carries a fine of up to $100 for a first violation and up to **$500 for each repeat violation**.","ref":["Florida Contractors Manual  ·  5-49  ·  TAB: Clean Indoor Air Act"],"lock":1},{"id":"1-17","exam":1,"num":17,"stem":"A __________ would be most likely to receive a Limited License.","options":["Retired professional","Professional from another state","Trainee immediately following a natural disaster","Person who has failed the state test 5 times"],"answer":0,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.214(2)"}],"exp":"§455.214 limited licenses go to **retired professionals** (licensed at least 10 years) who will serve indigent, underserved or critical-need populations. They are not for trainees, out-of-state professionals, or people who keep failing the exam.","ref":["Florida Statute 455  ·  §455.214(2)  ·  TOC: Limited Licenses"]},{"id":"1-18","exam":1,"num":18,"stem":"__________ is responsible to post OSHA posters on a multi-contractor project.","options":["The Owner","The General Contractor","Each Contractor","The Project Superintendent"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"7-6"},{"book":"FCM","eds":["2017"],"loc":"7-6"}],"exp":"On a multi-contractor project, **each contractor** (each employer) must post the required OSHA posters for its own employees. One GC can't post for everyone.","ref":["Florida Contractors Manual  ·  2025 & 2021: 7-6  ·  OSHA - Employer Responsibilities","2017: 7-6  ·  OSHA - Responsibilities"]},{"id":"1-19","exam":1,"num":19,"stem":"When __________, duly authorized agents and employees of DBPR may inspect premises of any establishment at all reasonable hours.","options":["There is a suspected OSHA violation","There are minors working on the premises","The services offered at the premises include authorization to prescribe controlled substances","Alcohol is served"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.243"}],"exp":"§455.243 lets DBPR agents inspect, at reasonable hours, any establishment whose **services include authority to prescribe controlled substances**. It's an odd fit for a contractor exam, but that's what the statute says.","ref":["Florida Statute 455  ·  §455.243  ·  TOC: Authority to Inspect"]},{"id":"1-20","exam":1,"num":20,"stem":"Unless an applicant notifies the department at least __________ days prior to an examination hearing of the applicant's inability to attend, the department may require an applicant to pay reasonable attorney's fees, costs, and court costs of the department for the examination hearing.","options":["3","4","5","7"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.229(3)"}],"exp":"§455.229(3): if an applicant doesn't notify DBPR at least **5 days** before an examination hearing that they can't attend, the department may charge them attorney's fees and costs.","ref":["Florida Statute 455  ·  §455.229(3)  ·  TOC: ... examination hearing"],"lock":1},{"id":"1-21","exam":1,"num":21,"stem":"If the circumstance of the violation meets the standard of a minor violation and __________ year (s) have passed since the issuance of a final order imposing discipline; the department shall reclassify that violation as inactive.","options":["1","2","3","5"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2255(1)"}],"exp":"§455.2255: a minor violation is reclassified as inactive once **2 years** have passed since the final order imposing discipline.","ref":["Florida Statute 455  ·  §455.2255(1)  ·  TOC: Classification of Disciplinary","Actions"],"lock":1},{"id":"1-22","exam":1,"num":22,"stem":"The real turnover ratio is __________.","options":["Cost of sales over inventory at cost","Cost of sales minus retail sales","Retail sales over breakeven point","Overhead plus all costs"],"answer":0,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"271"}],"exp":"Real turnover ratio = **cost of sales ÷ inventory at cost**. It shows how many times inventory turns over. Because it uses an income statement figure (cost of sales) and a balance sheet figure (inventory), it is a \"combined\" ratio.","ref":["Builder's Guide to Accounting  ·  271  ·  Real Turnover Ratio"]},{"id":"1-23","exam":1,"num":23,"stem":"In order to obtain a limited license, a person should have been licensed for at least __________ years in any jurisdiction in the United States.","options":["3","5","7","10"],"answer":3,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.214(2)"}],"exp":"A limited license (§455.214) requires a person to have been licensed for at least **10 years** in any U.S. jurisdiction.","tip":"Limited license = retired + 10 years + serving the indigent.","ref":["Florida Statute 455  ·  §455.214(2)  ·  TOC: Limited Licenses"],"lock":1},{"id":"1-24","exam":1,"num":24,"stem":"A request for additional investigative information shall be made within __________ days from the date of receipt by the probable cause panel of the investigative report of the department.","options":["5","10","15","30"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.225(4)"}],"exp":"§455.225(4): the probable cause panel must request more investigative information within **15 days** of receiving the department's investigative report.","ref":["Florida Statute 455  ·  §455.225(4)  ·  TOC: Disciplinary Proceedings"],"lock":1},{"id":"1-25","exam":1,"num":25,"stem":"The theft or reproduction of an examination constitutes a __________.","options":["Misdemeanor","Felony of the first degree","Felony of the second degree","Felony of the third degree"],"answer":3,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2175"}],"exp":"§455.2175: stealing or reproducing an examination is a **felony of the third degree**.","ref":["Florida Statute 455  ·  §455.2175  ·  TOC: Penalty for theft or reproduction"]},{"id":"1-26","exam":1,"num":26,"stem":"__________ is a foreseen condition that would not have an effect on production efficiency.","options":["Weather","Workload","Deadlines","Site Area"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-31"},{"book":"FCM","eds":null,"loc":"10-32"}],"exp":"In the manual's production-efficiency table (Fig. 12), weather, workload and site area all change productivity. **Deadlines** are the foreseen condition that does not.","ref":["Florida Contractors Manual  ·  10-31, 10-32  ·  Production Efficiency","Figure 12"]},{"id":"1-27","exam":1,"num":27,"stem":"Florida Diggers bought a tractor for $210,000. Its useful life is 12 years, and it has a salvage value of $30,000. If the tractor is sold at the end of year 6, the total depreciation would be __________.","options":["$90,000","$45,000","$60,000","$112,000"],"answer":0,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"163-164"}],"exp":"Straight line: ($210,000 − $30,000 salvage) ÷ 12 years = $15,000 a year. After 6 years: $15,000 × 6 = **$90,000** total depreciation.","tip":"Always subtract salvage first.","calc":1,"ref":["Builder's Guide to Accounting  ·  163-164  ·  Depreciation - Methods","Purchase value minus salvage value: $210,000 - $30,000 = $180,000","Note: when calculating depreciation with salvage value, always subtract salvage value from purchase price before starting calculations.","This value is used to determine annual depreciation (12) years: $180,000 ÷ 12 = $15,000 per year","Total depreciation after 6 years: $15,000 x 6 = $90,000"],"lock":1},{"id":"1-28","exam":1,"num":28,"stem":"The Bidder shall deliver the required bonds to the Owner not later than __________ following the date of execution of the Contract.","options":["24 hours","3 days","3 working days","7 days"],"answer":1,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"7.2.1"}],"exp":"A701 §7.2.1: the bidder delivers the required bonds to the **Owner** no later than **3 days** after the contract is executed.","tip":"Bonds go to the Owner in 3 days.","ref":["AIA Document A701, 2018  ·  7.2.1  ·  TOC: Performance bond and payment bond"]},{"id":"1-29","exam":1,"num":29,"stem":"\"2% - 10 days, net 30\" is __________.","options":["An extra charge for shipping","A incentive discount of 2% if the customer pays the invoice within 10 days of the billing date","An incentive discount of 2% if the customer pays the invoice within 30 days of the billing date","An incentive discount or a penalty of 2%, depending on the date the invoice is paid"],"answer":1,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"59"}],"exp":"\"2% 10, net 30\" means the customer can take a **2% discount by paying within 10 days**. Otherwise the full amount is due in 30 days. It's an incentive, not a penalty.","ref":["Builder's Guide to Accounting  ·  59  ·  Optional TAB: Discounts"]},{"id":"1-30","exam":1,"num":30,"stem":"Florida's Right to Work Laws __________.","options":["Prevent discrimination based on race, creed, or color","Allow non-resident aliens with proper documentation the right to work","Prevent employees from being forced to join a union","All of the above"],"answer":2,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-14"}],"exp":"Florida's Right to Work law (Art. I §6 of the Florida Constitution) **keeps employees from being forced to join, or pay, a union** as a condition of employment.","ref":["Florida Contractors Manual  ·  5-14  ·  Laws - Florida Right to Work"],"lock":1},{"id":"1-31","exam":1,"num":31,"stem":"Under the Florida Worker's Compensation Act, a contractor may recover __________ from a subcontractor who has elected exemption from Chapter 440 if the subcontractor's exemption is invalid and has caused liability to the contractor or an employee.","options":["Benefits paid and interest due","A minimum of $1,500 and interest","Penalties up to 100% of their contract","A maximum of $2,500 per occurrence"],"answer":0,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"6-5"},{"book":"FCM","eds":["2017"],"loc":"6-5"}],"exp":"If a subcontractor's workers' comp exemption is invalid and that creates liability for the contractor, the contractor may recover the **benefits paid plus interest** from the subcontractor.","ref":["Florida Contractors Manual  ·  2025 & 2021: 6-5  ·  Workers Compensation -","Exemptions","2017: 6-5  ·  Acts - Workers Compensation"]},{"id":"1-32","exam":1,"num":32,"stem":"Construction project schedules should have progress posted at least __________.","options":["Daily","Weekly","Biweekly","Monthly"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-63"}],"exp":"Post schedule progress at least **weekly**. Short-term schedules look 2 weeks ahead.","ref":["Florida Contractors Manual  ·  10-63  ·  Scheduling - Guidelines"]},{"id":"1-33","exam":1,"num":33,"stem":"A fine of up to ___________ can be imposed on a contractor for finishing a job without pulling a permit if it is their first offense","options":["$1,000","$3,000","$5,000","$10,000"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-206"},{"book":"FCM","eds":["2021"],"loc":"2-31"},{"book":"FCM","eds":["2021"],"loc":"2-158"},{"book":"FCM","eds":["2017"],"loc":"2-24"},{"book":"FCM","eds":["2017"],"loc":"2-184"}],"exp":"Under the CILB disciplinary guidelines (61G4-17), a first offense of completing a job without pulling a required permit can carry a fine of up to **$5,000**.","ref":["Florida Contractors Manual  ·  2025: 2-206 (o)  ·  Penalties - Licensing, Construction","2021: 2-31, 2-158 (o) Penalties - Licensing, Construction","2017: 2-24, 2-184 (o) Penalties - Licensing"],"lock":1},{"id":"1-34","exam":1,"num":34,"stem":"An OSHA 300 safety log must be maintained by employers with at least __________ employees.","options":["5","7","10","11"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"7-6"},{"book":"FCM","eds":["2017"],"loc":"7-6"}],"exp":"Employers with **more than 10 employees (11 or more)** must keep OSHA 300 logs. Employers with 10 or fewer are partially exempt.","tip":"10 or fewer = exempt. 11 or more = keep the log.","ref":["Florida Contractors Manual  ·  2025 & 2021: 7-6  ·  OSHA - Employer Responsibilities","2017: 7-6  ·  OSHA - Responsibilities"],"lock":1},{"id":"1-35","exam":1,"num":35,"stem":"Bidders and Sub-bidders requiring clarification of the Bidding Documents shall make a written request which shall reach the Architect at least __________ day(s) prior to the date for receipt of bids.","options":["10","3","5","7"],"answer":3,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"3.2.2"}],"exp":"A701 §3.2.2: written requests for clarification must reach the Architect at least **7 days** before bids are due.","tip":"Questions in 7 days before bids. Owner-financing request 14 days. Clerical error notice 2 days.","ref":["AIA Document A701, 2018  ·  3.2.2  ·  TOC: Bidding Document"],"lock":1},{"id":"1-36","exam":1,"num":36,"stem":"__________ is a correct accounting formula.","options":["Assets - Liabilities = Equity","Assets + Liabilities = Owner's Equity","Assets = Owner's Equity - Depreciation","Owner's Equity = Liabilities - Depreciation"],"answer":0,"topic":"acct","books":["FCM","BGA"],"cites":[{"book":"FCM","eds":null,"loc":"3-12"},{"book":"BGA","eds":null,"loc":"247"}],"exp":"The accounting equation is Assets = Liabilities + Owner's Equity. Rearranged: **Assets − Liabilities = Equity** (net worth).","ref":["Florida Contractors Manual  ·  3-12  ·  CM: Accounting - Equation","247  ·  BGA: Financial Statements","Assets = Liabilities + Equity - therefore, Assets - Liabilities = Equity"]},{"id":"1-37","exam":1,"num":37,"stem":"The __________ method is an estimating method that is NOT recommended for lump sum contracts.","options":["Approximate estimated","Detailed survey","Square footage","Unit price"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-12"}],"exp":"The **square footage method** is a quick conceptual estimate. It's too rough for a lump-sum contract, which needs a detailed quantity takeoff.","ref":["Florida Contractors Manual  ·  10-12  ·  Types of: Estimates"]},{"id":"1-38","exam":1,"num":38,"stem":"The three Cs of underwriting that the surety industry considers before a contractor can acquire a bond are __________.","options":["Character, cash, and contracts","Completion percentage, completed contracts and cash","Cash, completion, and contracts","Capital, character, and capacity"],"answer":3,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-15"}],"exp":"The surety's three Cs of underwriting are **Capital, Character and Capacity**: financial strength, reputation and integrity, and the ability to perform the work.","ref":["Florida Contractors Manual  ·  4-15  ·  Bonds - Three C's of underwriting"]},{"id":"1-39","exam":1,"num":39,"stem":"The Florida sales tax is reported on form __________.","options":["DR-15-CS and paid on a monthly basis","DR-15-CS and paid on a quarterly basis","941 and paid on a monthly basis","941 and paid on a quarterly basis"],"answer":0,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-27"},{"book":"FCM","eds":["2017"],"loc":"1-23"}],"exp":"Florida sales and use tax is reported on **Form DR-15** (DR-15CS in older materials) and is generally paid **monthly**. Form 941 is the federal quarterly payroll return.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-27  ·  Forms - DR-15","2017: 1-23  ·  Taxes - State Sales"]},{"id":"1-40","exam":1,"num":40,"stem":"Expanding a business usually requires a great deal of capital to purchase new equipment, buildings, or to obtain long term financing. To qualify for expansion financing, financial institutes typically require that you have been in business at least __________ years, while __________ years is preferred.","options":["2; 4","2; 5","3; 5","3; 6"],"answer":1,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"3-72"},{"book":"FCM","eds":["2017"],"loc":"3-72"}],"exp":"For expansion financing, lenders typically want at least **2 years** in business and prefer **5**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 3-72  ·  Capital - Sources of","2017: 3-72  ·  Types of Capital"],"lock":1},{"id":"1-41","exam":1,"num":41,"stem":"If an employer conducts business in more than one location in Florida, completion of the Multiple Worksite Report BLS-3020 will be required on a __________ basis.","options":["Weekly","Monthly","Quarterly","Annual"],"answer":2,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-267"},{"book":"FCM","eds":["2021"],"loc":"5-290"},{"book":"FCM","eds":["2017"],"loc":"5-292"}],"exp":"Employers operating at more than one Florida location file the Multiple Worksite Report (BLS-3020) **quarterly**, separately from the RT-6.","ref":["Florida Contractors Manual  ·  2025: 5-267  ·  Optional TAB: Multiple Worksite","2021: 5-290  ·  Forms - Multiple worksite","2017: 5-292"]},{"id":"1-42","exam":1,"num":42,"stem":"A __________ is a special combination of two or more persons or entities jointly seeking a profit in some specific venture or for a specific job or undertaking without an actual partnership or corporate designation.","options":["Special limited partnership","S-type business","Joint venture","Sole proprietorship"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-10"},{"book":"FCM","eds":["2017"],"loc":"1-12"}],"exp":"A **joint venture** is two or more people or entities teaming up for profit on one specific project, without forming a partnership or corporation.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-10  ·  Types of: Business","2017: 1-12"]},{"id":"1-43","exam":1,"num":43,"stem":"Fictitious names are valid for __________ years.","options":["2","3","4","5"],"answer":3,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-14"},{"book":"FCM","eds":["2017"],"loc":"1-15"}],"exp":"A Florida fictitious name registration is valid **5 years** and expires December 31 of the fifth year.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-14  ·  Fictitious Name","2017: 1-15"],"lock":1},{"id":"1-44","exam":1,"num":44,"stem":"Which of the following agreements are prohibited by Florida's Right to Work Laws?","options":["Union Shop","Agency Shop","Maintenance of Membership","All the above are prohibited"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-14"},{"book":"FCM","eds":null,"loc":"5-15"}],"exp":"Florida's Right to Work law prohibits union shop, agency shop and maintenance-of-membership agreements. **All of them** are prohibited.","ref":["Florida Contractors Manual  ·  5-14, 5-15  ·  Laws - Florida Right to Work"],"lock":1},{"id":"1-45","exam":1,"num":45,"stem":"When making a claim of lien, you must send a sworn statement of account within ___________.","options":["90 days after demand of statement has been made","30 days after demand of statement has been made","45 days before demand of statement has been made","15 days before demand of statement has been made"],"answer":1,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-36"},{"book":"FCM","eds":["2017"],"loc":"9-35"}],"exp":"§713.16: a lienor must send a sworn statement of account within **30 days after the demand** is made. Failing to do so can cost the lienor its lien rights.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-36  ·  TOC: Requests for Sworn Statement","2017: 9-35  ·  Liens- Sworn Statements"]},{"id":"1-46","exam":1,"num":46,"stem":"If the contractor defaults or neglects to carry out the Work and fails to do so within __________ of receipt of written notice from the Owner, the Owner may correct such deficiencies.","options":["10 days","7 business days","7 calendar days","3 days"],"answer":0,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"2.5"}],"exp":"A201 §2.5: if the Contractor defaults and doesn't begin correcting it within **10 days** of the Owner's written notice, the Owner may correct the work itself.","tip":"Owner vs. contractor = 10 days (A201). Contractor vs. sub = 5 days (A401).","ref":["AIA Document A201, 2017  ·  2.5  ·  Owners right to carry out the work"]},{"id":"1-47","exam":1,"num":47,"stem":"The best way to accurately control petty cash is through a(n) __________.","options":["Imprest system","Separate bank account","A dedicated entry group within an accounting system","Lock box"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"208"}],"exp":"An **imprest system** keeps petty cash at a fixed amount. It is replenished for exactly the amount of the receipts turned in, so cash plus receipts always equals the fund total.","ref":["Builder's Guide to Accounting  ·  208  ·  Petty cash - imprest system"]},{"id":"1-48","exam":1,"num":48,"stem":"OSHA 300/300A, the Log on Summary of Occupational Injuries and Illnesses, is used to record __________.","options":["Accident investigations","All health claims","Incidents resulting in loss of consciousness","Non-work restricting injuries"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"7-6"},{"book":"FCM","eds":["2017"],"loc":"7-6"}],"exp":"The OSHA 300 log records work-related injuries and illnesses that are serious enough to report. **Loss of consciousness** is one of the recording criteria. First-aid-only cases are not recorded.","ref":["Florida Contractors Manual  ·  2025 & 2021: 7-6  ·  OSHA - Employer Responsibilities","2017: 7-6  ·  OSHA - Responsibilities"]},{"id":"1-49","exam":1,"num":49,"stem":"ABC Construction buys a tractor for $157,000. They can depreciate the tractor over seven years. Using the straight-line method, the depreciation in the seventh year is __________.","options":["$10,575","$22,500","$16,275","$33,000"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"163"}],"exp":"Straight-line depreciation is the same every year: $157,000 ÷ 7 ≈ $22,429. The closest choice is **$22,500**. (The official key shows $157,500 ÷ 7, a typo, but the answer is the same.)","tip":"Under straight line, year 7 equals year 1.","calc":1,"ref":["Builder's Guide to Accounting  ·  163  ·  Depreciation - straight line","$157,500 ÷ 7 = $22,429"],"lock":1},{"id":"1-50","exam":1,"num":50,"stem":"When a contractor must perform extra work for a subcontractor or material vendor, the contractor may proceed to recover the cost in the form of a(n) __________.","options":["Addendum","Back charge","Change order","Lien"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-67"}],"exp":"A **back charge** recovers the cost of work the contractor had to do on behalf of a subcontractor or vendor. A change order changes the owner's contract. An addendum changes the bid documents.","ref":["Florida Contractors Manual  ·  10-67  ·  Optional TAB: Backcharge"]},{"id":"1-51","exam":1,"num":51,"stem":"According to the Contractor's Manual, under the completed contract method, a contract is recognized as complete when it is in excess of __________ complete.","options":["75% to 80%","90%","98% or 99%","none of the above"],"answer":2,"topic":"job","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-80"}],"exp":"Under the completed contract method (per the manual), a contract counts as complete when it is **98% to 99%** done.","ref":["Florida Contractors Manual  ·  3-80  ·  Completed contract"],"lock":1},{"id":"1-52","exam":1,"num":52,"stem":"A Change Order is a written instrument prepared by the Architect and signed by the __________.","options":["Owner","Architect","Owner and the Architect","Owner, Contractor, and Architect"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"7.2.1"}],"exp":"A201 §7.2.1: the Architect prepares a Change Order, and it is signed by the **Owner, Contractor and Architect**. A Construction Change Directive needs only the Owner and Architect.","tip":"CO = 3 signatures. CCD = 2 (no contractor).","ref":["AIA Document A201, 2017  ·  7.2.1  ·  Change orders - Definition of"]},{"id":"1-53","exam":1,"num":53,"stem":"What percentage of the job is complete?","options":["66.67%","60%","75.5%","less than 50%"],"answer":0,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"23"}],"exp":"Percent complete = cost to date ÷ total estimated cost = $210,000 ÷ ($210,000 + $105,000) = $210,000 ÷ $315,000 = **66.67%**.","scenario":"Your company, Perfect Plus Construction, is partway through a job. The cost of work completed is $210,000. It is estimated that completing the job will cost an additional $105,000. The total contract price of the job is $390,000. You have billed, and been paid, $220,000. Using the percentage of completion method, answer the following 3 questions.","calc":1,"ref":["Builder's Guide to Accounting  ·  23","$210,000 + $105,000 = $315,000","$210,000 ÷ $315,000 = .667 (66.67%)"]},{"id":"1-54","exam":1,"num":54,"stem":"Which of the following is the nearest to the amount of money that has been earned on this job?","options":["$129,870","$255,719","$260,013","$215,303"],"answer":2,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"23"}],"exp":"Earned revenue = % complete × contract price = 0.6667 × $390,000 ≈ **$260,013**.","scenario":"Your company, Perfect Plus Construction, is partway through a job. The cost of work completed is $210,000. It is estimated that completing the job will cost an additional $105,000. The total contract price of the job is $390,000. You have billed, and been paid, $220,000. Using the percentage of completion method, answer the following 3 questions.","calc":1,"ref":["Builder's Guide to Accounting  ·  23","Apply percentage complete to contract price - $.6667 x $390,000 = $260,013"],"lock":1},{"id":"1-55","exam":1,"num":55,"stem":"Which of the following is true?","options":["You have unearned income","You have earned more than you've been paid","You have earned exactly what you were paid","You have earned less than you have been paid"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"23"}],"exp":"Earned $260,013 but paid (billed) $220,000, so you've **earned more than you've been paid**. That's an underbilling, recorded as an asset (\"costs and earnings in excess of billings\").","scenario":"Your company, Perfect Plus Construction, is partway through a job. The cost of work completed is $210,000. It is estimated that completing the job will cost an additional $105,000. The total contract price of the job is $390,000. You have billed, and been paid, $220,000. Using the percentage of completion method, answer the following 3 questions.","calc":1,"ref":["Builder's Guide to Accounting  ·  23","Paid $220,000 Earned $260,013"]},{"id":"1-56","exam":1,"num":56,"stem":"The federal minimum wage is __________ per hour.","options":["$5.15","$7.25","$10.75","$12.35"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-15"}],"exp":"The **federal** minimum wage is **$7.25** an hour and has been since 2009. Florida's state minimum wage is higher and goes up every September 30, but if a question says \"federal,\" answer $7.25.","ref":["Florida Contractors Manual  ·  5-15  ·  Minimum wage"],"lock":1},{"id":"1-57","exam":1,"num":57,"stem":"The job responsibilities of a Superintendent include __________.","options":["Actively participate in creation of a project schedule","Maintain change order log","Prepare back charges","Both A & C"],"answer":3,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-72"}],"exp":"The manual says a superintendent **actively helps create the project schedule and prepares back charges**. Keeping the change order log is a project manager or office task.","ref":["Florida Contractors Manual  ·  10-72  ·  Job responsibilities"],"lock":1},{"id":"1-58","exam":1,"num":58,"stem":"Within 3 business days of the date the Contractor becomes aware of an impending or actual cancellation or expiration of any insurance, the Contractor shall provide notice to the __________.","options":["Subcontractor","Owner","Architect","Florida Department of Insurance Compliance"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"11.1.4"}],"exp":"A201 §11.1.4: within 3 business days of learning of an impending or actual cancellation or expiration of required insurance, the Contractor notifies the **Owner**.","ref":["AIA Document A201, 2017  ·  11.1.4  ·  Insurance - Notice of Cancellation or Expiration"]},{"id":"1-59","exam":1,"num":59,"stem":"Contractors must send a notice of all demolition projects to Florida Department of Environmental Protection __________ working days before demolition, even if there is no asbestos containing material present.","options":["10","15","5","30"],"answer":0,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"10-97"},{"book":"FCM","eds":["2017"],"loc":"10-97"}],"exp":"FDEP must be notified at least **10 working days** before any demolition, even when no asbestos is present.","ref":["Florida Contractors Manual  ·  2025 & 2021:10-97  ·  Asbestos","2017:10-97  ·  Environmental compliance"],"lock":1},{"id":"1-60","exam":1,"num":60,"stem":"The check register shows at a glance __________.","options":["What expense categories you have and where your money goes","Your income and expense items by category","Your available balance on a cash basis","The income, expenses, and equity of your company"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"101"}],"exp":"Per the Builder's Guide, the check register shows **what expense categories you have and where your money goes**.","ref":["Builder's Guide to Accounting  ·  101  ·  Check register"]},{"id":"1-61","exam":1,"num":61,"stem":"When estimating speeds of equipment for production purposes, they will usually average __________ percent of the speed limit.","options":["70 - 80","70 - 75","40 - 65","75 - 90"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-27"}],"exp":"For production estimates, equipment usually averages **40% to 65%** of the posted speed limit.","ref":["Florida Contractors Manual  ·  10-27  ·  Equipment - Productivity"],"lock":1},{"id":"1-62","exam":1,"num":62,"stem":"After the date and time designated for receipt of bids, a Bidder who discovers that it made a clerical error in its Bid shall notify the Architect of such error within __________ day (s).","options":["One","Two","Three","Four"],"answer":1,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"4.4.3"}],"exp":"A701 §4.4.3: a bidder who finds a clerical error in its bid after bids open must notify the Architect within **2 days**.","ref":["AIA Document A701, 2018  ·  4.4.3  ·  TOC: Bidding Procedures"]},{"id":"1-63","exam":1,"num":63,"stem":"A Plumbing Contractor would be required to carry Liability and Property insurance in the respective amounts of __________ and __________.","options":["300,000; 50,000","300,000; 100,000","100,000; 50,000","100,000; 25,000"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"2-16"},{"book":"FCM","eds":["2017"],"loc":"2-19"}],"exp":"61G4-15.003: specialty trades such as plumbing carry **$100,000 public liability and $25,000 property damage**. General, building and residential contractors carry $300,000 and $50,000.","tip":"GC/building/residential = 300/50. Other trades = 100/25.","ref":["Florida Contractors Manual  ·  2025 & 2021: 2-16  ·  Licensing - Public liability","2017: 2-19  ·  Public liability insurance"],"lock":1},{"id":"1-64","exam":1,"num":64,"stem":"An(a) __________ is a valid oral contract.","options":["Two-year apartment rental agreement","Agreement to buy a lawnmower for $475.00","Agreement to buy 3 pallets of bricks for $515.00","Five-year building lease agreement"],"answer":1,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"8-6"},{"book":"FCM","eds":null,"loc":"8-7"}],"exp":"Under the Statute of Frauds (UCC), a sale of goods for **$500 or more** must be in writing. The $475 lawnmower is under the limit, so an oral contract is valid. The $515 bricks and leases over 1 year need a written contract.","ref":["Florida Contractors Manual  ·  8-6, 8-7  ·  Contracts - Written or oral"]},{"id":"1-65","exam":1,"num":65,"stem":"The Current Ratio gives a good idea of a __________.","options":["Company's amount of fixed asset investments","Company's ability to meet current obligations with current assets","Company's collection processes","Debt to profit comparison"],"answer":1,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"269"}],"exp":"Current ratio = current assets ÷ current liabilities. It measures **the company's ability to pay current obligations with current assets** (liquidity).","ref":["Builder's Guide to Accounting  ·  269  ·  Current Ratio"]},{"id":"1-66","exam":1,"num":66,"stem":"___________ and ___________ are two types of manpower estimates.","options":["Comparative and historical","Graphic and detailed","Preliminary and detailed","Preliminary and historical"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"10-28"},{"book":"FCM","eds":["2017"],"loc":"10-28"}],"exp":"The two types of manpower (labor) estimates are **preliminary** and **detailed**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 10-28 Estimates - Labor Estimates","2017: 10-28  ·  Estimates - Manpower"]},{"id":"1-67","exam":1,"num":67,"stem":"According to Florida Unemployment Compensation Laws, an employer who fails to file RT-6 reports when due will be assessed a penalty of ___________ for each month (or fraction thereof) that the report is delinquent.","options":["$25","$50","$75","$100"],"answer":0,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-269"},{"book":"FCM","eds":["2021"],"loc":"5-291"},{"book":"FCM","eds":["2017"],"loc":"5-294"}],"exp":"An employer who files the RT-6 reemployment tax report late is penalized **$25 for each month, or part of a month**, that it is late.","ref":["Florida Contractors Manual  ·  2025: 5-269  ·  Unemployment - Recordkeeping","2021: 5-291  ·  Forms - SUTA Quarterly Report (RT6)","2017: 5-294"],"lock":1},{"id":"1-68","exam":1,"num":68,"stem":"A purchase order form will help you control __________.","options":["Inventory sales","Your payment terms","Actual inventory in a LIFO system","Unauthorized purchases"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"116"}],"exp":"Purchase orders require approval before buying, so they help control **unauthorized purchases**.","ref":["Builder's Guide to Accounting  ·  116  ·  Purchase order"]},{"id":"1-69","exam":1,"num":69,"stem":"Interpretations, corrections, and changes of the Bidding Documents shall be made by __________.","options":["Addendum","The Architect","Change Order","The Owner"],"answer":0,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"3.2.3"}],"exp":"A701 §3.2.3: interpretations, corrections and changes to the bidding documents are made only by **Addendum**. A Change Order changes the contract after it is signed.","tip":"Before the contract = Addendum. After = Change Order.","ref":["AIA Document A701, 2018  ·  3.2.3  ·  TOC: Bidding documents"]},{"id":"1-70","exam":1,"num":70,"stem":"Each continuing education provider shall retain all records relating to a licensee's completion of continuing education courses for at least __________ years after completion of a course.","options":["2","3","4","5"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2178(2)"}],"exp":"§455.2178: continuing education providers keep records of each licensee's course completion for at least **4 years**.","ref":["Florida Statute 455  ·  §455.2178(2)  ·  TOC: Continuing education provider"],"lock":1},{"id":"1-71","exam":1,"num":71,"stem":"If the Contractor does not pay the Subcontractor through no fault of the Subcontractor, within seven days of the time payment should be made as provided on their Agreement, the Subcontractor may, upon __________ additional days written notice to the Contractor, stop the Work of the Subcontract.","options":["14","7","5","3"],"answer":1,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"4.8"}],"exp":"A401 §4.8: if the Contractor doesn't pay the Sub within 7 days of the due date, through no fault of the Sub, the Sub may stop work after **7 more days' written notice**.","tip":"7 + 7.","ref":["AIA Document A401, 2017  ·  4.8  ·  Subcontractor"],"lock":1},{"id":"1-72","exam":1,"num":72,"stem":"The purpose of Supplementary Record of Occupational Injuries and Illnesses (OHSA No. 301) is to ___________.","options":["Provide additional information about the employer listed in the log","Report the safety measures taken to prevent future accidents","Summarize the information that has been recorded in the log","Provide additional information on each case that has been recorded in the log"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"7-11"},{"book":"FCM","eds":["2017"],"loc":"7-11"}],"exp":"The OSHA 301 (Injury and Illness Incident Report) **gives more detail on each case recorded on the 300 log**. The 300A is the annual summary.","ref":["Florida Contractors Manual  ·  2025 & 2021: 7-11  ·  TOC: The Supplementary Record of","Occupational Injuries and Illnesses","(OSHA No. 301)","2017: 7-11  ·  OSHA - 301 Form"]},{"id":"1-73","exam":1,"num":73,"stem":"Periodic progress reports on the Work shall be provided by the __________ to the __________ as mutually agreed.","options":["Contractor, Owner","Contractor, Architect","Subcontractor, Owner","Subcontractor, Contractor"],"answer":3,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"4.2.4"}],"exp":"A401 §4.2.4: the **Subcontractor** gives periodic progress reports to the **Contractor**. The sub's contract is with the contractor, not the owner.","ref":["AIA Document A401, 2017  ·  4.2.4  ·  Subcontractor"]},{"id":"1-74","exam":1,"num":74,"stem":"For the purpose of required Workers Compensation coverage, __________ is NOT exempt from being considered a construction job.","options":["Landscaping for existing buildings","Fencing for existing building","Swimming pool repairs at an existing building","Well drilling on land not containing any other existing structures"],"answer":3,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"6-6"}],"exp":"Per the manual's workers' comp definitions, landscaping, fencing and pool repair at existing buildings are excluded from \"construction.\" **Well drilling on land with no existing structures** still counts as a construction job.","ref":["Florida Contractors Manual  ·  6-6  ·  Workers Compensation - Exemption"]},{"id":"1-75","exam":1,"num":75,"stem":"__________ is (are) considered to be a variable expense.","options":["Postage","Rent","Depreciation","Collections"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"147"}],"exp":"A variable expense changes with sales volume. **Collections** costs vary. Rent and depreciation are fixed.","ref":["Builder's Guide to Accounting  ·  147  ·  Expenses - variables"]},{"id":"1-76","exam":1,"num":76,"stem":"The Bidder shall furnish Performance Bonds and Payment Bonds covering __________.","options":["The faithful performance of the contract and payments of all obligations arising thereunder","The full amount of the total cost of the job including change orders","The cost of the contract and attorney fees to enforce the contract if they do not perform","All jobs with costs over $250,000"],"answer":0,"topic":"ins","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"7.1.1"}],"exp":"A701 §7.1.1: the bidder furnishes Performance and Payment Bonds covering **faithful performance of the contract and payment of all obligations under it**.","ref":["AIA Document A701, 2018  ·  7.1.1  ·  TOC: Performance & Payment Bond"]},{"id":"1-77","exam":1,"num":77,"stem":"__________ insurance covers the structure being constructed and may be extended to cover materials while in transit or at temporary storage facilities.","options":["Umbrella","Inland marine","Fidelity","Builders risk"],"answer":3,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-7"}],"exp":"**Builder's risk** insurance covers the structure under construction and can be extended to materials in transit or in temporary storage.","ref":["Florida Contractors Manual  ·  4-7 (See Item #7)  ·  Insurance"]},{"id":"1-78","exam":1,"num":78,"stem":"If not exempt from local sales tax, the __________ will pay the sales tax.","options":["Manufacturer","State","Purchaser","Licensee"],"answer":2,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"3-64"},{"book":"FCM","eds":["2017"],"loc":"3-65"}],"exp":"Sales tax is paid by the **purchaser** (the end consumer) unless exempt. The seller only collects it and sends it to the state.","ref":["Florida Contractors Manual  ·  2025 & 2021: 3-64  ·  Taxes - State Sales Tax","2017: 3-65  ·  Taxes - Local Sales"]},{"id":"1-79","exam":1,"num":79,"stem":"A loan for $150,000 is made at a 9% interest rate. If it is paid back after 6 months. __________ in interest will be paid.","options":["$15,000","$13,500","$6,750","$10,125"],"answer":2,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-74"}],"exp":"Simple interest = principal × rate × time = $150,000 × 0.09 × (6 ÷ 12) = **$6,750**.","calc":1,"ref":["Florida Contractors Manual  ·  3-74  ·  Loans - Types of","$150,000 x .09 (9%) x 6 months/12 months in a year = $6,750"],"lock":1},{"id":"1-80","exam":1,"num":80,"stem":"The volume of business that must be maintained in order to avoid a loss is the ___________.","options":["Percentage of sales","Net worth","Available cash","Breakeven point"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"179"}],"exp":"The **breakeven point** is the sales volume where revenue exactly covers costs. Below it you lose money.","ref":["Builder's Guide to Accounting  ·  179  ·  Break-even point"]},{"id":"1-81","exam":1,"num":81,"stem":"If a contractor becomes liable for the payment of compensation to the employees of a subcontractor who has failed to secure such payment in violation of §440., the contractor shall be entitled to recover from the subcontractor __________.","options":["All benefits paid","All benefits paid or payable plus interest","150% of all benefits paid","Nothing"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"6-85","stat":"440.10(1)(d)1"},{"book":"FCM","eds":["2021"],"loc":"6-78","stat":"440.10(1)(d)1"},{"book":"FCM","eds":["2017"],"loc":"6-92","stat":"440.10(1)(d)1"}],"exp":"§440.10(1)(d): a contractor who has to pay comp to an uninsured subcontractor's employees may recover **all benefits paid or payable, plus interest**, from that subcontractor.","ref":["Florida Contractors Manual  ·  2025: 6-85:  ·  TOC: Liability for Compensation","§440.10(1)(d)1","2021: 6-78: §440.10(1)(d)1","2017: 6-92: §440.10(1)(d)1"]},{"id":"1-82","exam":1,"num":82,"stem":"Under the Equal Pay Act, if the violation is willful, a court or jury may award up to __________ in back pay wages.","options":["Three years","Two years","Two years, not to exceed $5,000","Two years, plus interest"],"answer":0,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-39"}],"exp":"Equal Pay Act: back pay normally covers 2 years, or **3 years** if the violation was willful.","ref":["Florida Contractors Manual  ·  5-39  ·  Acts - Equal Pay"]},{"id":"1-83","exam":1,"num":83,"stem":"The Contractor shall not contract with a proposed person or entity to whom __________ has made reasonable or timely objection.","options":["Only the Architect","Only the Owner","The Architect or Owner","The Architect or Engineer"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"5.2.2"}],"exp":"A201 §5.2.2: the Contractor may not use a proposed subcontractor or supplier that the **Owner or Architect** has reasonably and timely objected to.","ref":["AIA Document A201, 2017  ·  5.2.2  ·  Subcontractors"]},{"id":"1-84","exam":1,"num":84,"stem":"__________ may NOT be depreciated.","options":["A tractor","A building","Equipment","Land"],"answer":3,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"162"}],"exp":"**Land** is never depreciated because it doesn't wear out. Buildings, tractors and equipment are.","ref":["Builder's Guide to Accounting  ·  162  ·  Depreciation"]},{"id":"1-85","exam":1,"num":85,"stem":"A bidder to whom award of a Contract is under consideration may request in writing, __________ days prior to the expiration of the time for withdrawal of Bids, that the Owner furnish to the Bidder reasonable evidence that financial arrangements have been made to fulfill the Owner's obligations under the Contract.","options":["Three","Seven","Ten","Fourteen"],"answer":3,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"6.2"}],"exp":"A701 §6.2: a bidder under consideration may ask in writing, **14 days** before the bid withdrawal period ends, for proof of the owner's financing. The owner then has 7 days to provide it.","tip":"Bidder asks at 14 days. Owner answers in 7.","ref":["AIA Document A701, 2018  ·  6.2  ·  TOC: Post-Bid Information"]},{"id":"1-86","exam":1,"num":86,"stem":"Contractor's claims for the cost of services or materials provided due to the Subcontractor's failure to execute the Work shall require __________ days written notice prior to the Contractor's providing services or materials.","options":["2","3","5 working","7"],"answer":3,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"3.4.2"}],"exp":"A401: before the Contractor supplies services or materials because the Sub failed to perform, and back-charges for them, the Contractor must give **7 days' written notice**.","ref":["AIA Document A401, 2017  ·  3.4.2 (1)  ·  TOC: Contractor"],"lock":1},{"id":"1-87","exam":1,"num":87,"stem":"A secondary qualifier is never responsible for __________.","options":["Obtaining permits","Safety on the jobsite","Financial matters having to do with his/her jobsite","Quality of the work done on his/her jobsite"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-24"},{"book":"FCM","eds":["2025"],"loc":"2-101","stat":"489.1195(2)(e)"},{"book":"FCM","eds":["2021"],"loc":"2-22"},{"book":"FCM","eds":["2021"],"loc":"2-78","stat":"489.1195(2)(e)"},{"book":"FCM","eds":["2017"],"loc":"2-21","stat":"489.1195(2)(e)"},{"book":"FCM","eds":["2017"],"loc":"2-89","stat":"489.1195(2)(e)"}],"exp":"§489.1195: the **primary** qualifying agent is responsible for financial matters. A secondary qualifier is responsible only for supervising field work (permits, safety, quality) and **never for financial matters**.","ref":["Florida Contractors Manual  ·  2025: 2-24, 2-101:  ·  Qualifying Agent","§489.1195(2)(e)","2021: 2-22, 2-78:","§489.1195(2)(e)","2017: 2-21, 2-89: §489.1195(2)(e)"]},{"id":"1-88","exam":1,"num":88,"stem":"__________ will NOT be allowed to be included in the requested amount of a construction change directive.","options":["Labor","Rental cost of hand tools","Rental cost of machinery","Supplies"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"7.3.4"}],"exp":"A201 §7.3.4: CCD and change order costs may include labor, materials, supplies and rental of machinery and equipment, **but not hand tools**.","tip":"Hand tools are never in a change.","ref":["AIA Document A201, 2017  ·  7.3.4  ·  Construction Change Directives"]},{"id":"1-89","exam":1,"num":89,"stem":"A Contractor shall submit to the Architect his or her application for payment __________ days prior to the date established in a contract for progress payments.","options":["3","5","7","10"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"9.3.1"}],"exp":"A201 §9.3.1: the Contractor submits its Application for Payment to the **Architect** at least **10 days** before the payment date.","tip":"Pay app: 10 days, to the Architect.","ref":["AIA Document A201, 2017  ·  9.3.1  ·  Applications for Payment"],"lock":1},{"id":"1-90","exam":1,"num":90,"stem":"__________ is a method of improving cash flow.","options":["Maintaining a high inventory","Taking advantage of discounts","Converting all cash sales to accounts receivable","Paying off liabilities"],"answer":1,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"262"}],"exp":"**Taking discounts** (such as 2/10 net 30) lowers costs and improves cash flow. High inventory and converting cash sales to receivables tie up cash.","ref":["Builder's Guide to Accounting  ·  262  ·  Cashflow - Controlling"],"dupes":["3-2"]},{"id":"1-91","exam":1,"num":91,"stem":"A Subcontractor has a \"Standard Form of Agreement Between Contractor and Subcontractor\" with the prime Contractor on a project. The ONLY way the Subcontractor can assign work on the Subcontract is with the written __________.","options":["Consent of the Owner or Architect","Consent of the Contractor","Notification to the Owner or Architect","Notification to the Contractor"],"answer":1,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"7.4.2"}],"exp":"A401 §7.4.2: the Subcontractor may not assign the subcontract without the **Contractor's written consent**.","ref":["AIA Document A401, 2017  ·  7.4.2  ·  TOC: Termination, suspension or assignment of the subcontract"],"dupes":["3-3"]},{"id":"1-92","exam":1,"num":92,"stem":"__________ are eligible for Small Business Administration loans.","options":["All building contractors in the United States","Only company presidents","Applicants who cannot obtain a loan from local banks","Applicants who are recommended by a local bank"],"answer":2,"topic":"org","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"318"},{"book":"BGA","eds":null,"loc":"319"}],"exp":"SBA loans are for **applicants who can't get reasonable credit from local banks** or other conventional lenders.","ref":["Builder's Guide to Accounting  ·  318, 319  ·  Small Business Administration Loans"]},{"id":"1-93","exam":1,"num":93,"stem":"A Notice of Commencement can be extended past one year __________.","options":["If it is written into the Notice of Commencement","If the job proceeds past one year","When there is an architectural change order","Never"],"answer":0,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-83","stat":"713.13(1)(c)"},{"book":"FCM","eds":["2021"],"loc":"9-78","stat":"713.13(1)(c)"},{"book":"FCM","eds":["2017"],"loc":"9-88","stat":"713.13(1)(c)"}],"exp":"§713.13(1)(c): a Notice of Commencement expires **1 year after recording unless the notice itself states a different expiration date**.","ref":["Florida Contractors Manual  ·  2025: 9-83:  ·  Notices - Notice of Commencement","§713.13(1)(c)","2021: 9-78:","§713.13(1)(c)","2017: 9-88:","§713.13(1)(c)"],"dupes":["3-5"]},{"id":"1-94","exam":1,"num":94,"stem":"Which of the following will the bidder not represent when he or she submits a bid?","options":["That the provision for liquidated damages will be waived","Has visited the site and is familiar with local conditions under which the work is to be performed","Has read and understands the bidding documents","That the bid will be based upon materials and equipment required in the bid documents"],"answer":0,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"2.1"}],"exp":"A701 §2.1: by bidding, the bidder represents that it read the bidding documents, visited the site, and based the bid on the specified materials. It **never represents that liquidated damages will be waived**.","ref":["AIA Document A701, 2018  ·  2.1  ·  TOC: Bidders Representation"]},{"id":"1-95","exam":1,"num":95,"stem":"A Contractor receives payment from the Owner of a construction project. The Contractor shall pay the Subcontractor each progress payment within __________.","options":["3 working days","3 days (including Saturday and Sunday)","5 working days","7 working days"],"answer":3,"topic":"aia","books":["A401","A201"],"cites":[{"book":"A401","eds":null,"loc":"11.1.3"},{"book":"A201","eds":null,"loc":"9.6.2"}],"exp":"A401 §11.1.3 (with A201 §9.6.2): the Contractor pays each Subcontractor within **7 working days** of receiving payment from the Owner.","ref":["AIA Document A401, 2017  ·  11.1.3  ·  TOC: Payments","AIA Document A201, 2017  ·  9.6.2"],"dupes":["3-7"]},{"id":"1-96","exam":1,"num":96,"stem":"When a piece of equipment is sold, it is necessary to book the transaction separate from regular sales because __________.","options":["It is treated as a variable expense","It receives different tax treatment","The transaction is not taxable","The gains or losses must be used to adjust gross profits"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"170"}],"exp":"Selling equipment can produce a capital gain or loss and depreciation recapture. Because it **receives different tax treatment**, it's recorded separately from regular sales.","ref":["Builder's Guide to Accounting  ·  170  ·  Equipment - sales"],"dupes":["3-9"]},{"id":"1-97","exam":1,"num":97,"stem":"A certificate holder or registrant must inform the Board, by mail, within __________ calendar days, of changes in any information required to be stated on the application for qualification of a business organization.","options":["30","45","60","90"],"answer":1,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-173","stat":"61G4-15.007(2)"},{"book":"FCM","eds":["2021"],"loc":"2-133","stat":"61G4-15.007(2)"},{"book":"FCM","eds":["2017"],"loc":"2-159","stat":"61G4-15.007(2)"}],"exp":"61G4-15.007(2): changes to any information required on the business organization's qualification application must be reported within **45 calendar days**.","ref":["Florida Contractors Manual  ·  2025: 2-173:  ·  Licensing - Notices of Changes","61G4-15.007(2)","2021: 2-133:","61G4-15.007(2)","2017: 2-159:  ·  Licensing - Change in Information","61G4-15.007(2)"],"lock":1},{"id":"1-98","exam":1,"num":98,"stem":"__________ is (are) examples of an accrual entry.","options":["Depreciation and amortization entries","Entries to record payroll taxes","Entries to record automatic loan payments","Entries to record purchase of material stored at the jobsite"],"answer":3,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"237"}],"exp":"Per the Builder's Guide, recording **material purchased and stored at the jobsite** (not yet installed) is an accrual entry.","ref":["Builder's Guide to Accounting  ·  237  ·  Accruals"]},{"id":"1-99","exam":1,"num":99,"stem":"To establish an hourly cost for a piece of equipment, the contractor needs to consider all the following except the __________.","options":["Estimated life of the equipment","Cost of the equipment, less salvage value","Replacement cost of the equipment","Estimated average hours of use"],"answer":2,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"159"},{"book":"BGA","eds":null,"loc":"160"}],"exp":"Hourly equipment cost uses cost less salvage, estimated life, and average hours of use. **Replacement cost** is not part of the calculation.","ref":["Builders Guide to Accounting  ·  159, 160  ·  Equipment - Cost assignment"],"dupes":["3-16"]},{"id":"1-100","exam":1,"num":100,"stem":"Failure of a certificate holder or registrant to apply for renewal of an active certificate at the time of biennial renewal shall cause the certificate to become __________.","options":["Temporarily suspended","Permanently suspended","Voluntarily inactive","Delinquent"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-95","stat":"489.116(4)"},{"book":"FCM","eds":["2021"],"loc":"2-74","stat":"489.116(4)"},{"book":"FCM","eds":["2017"],"loc":"2-84","stat":"489.116(4)"}],"exp":"§489.116(4): if a certificate holder doesn't apply to renew an active certificate at the biennial renewal, the certificate becomes **delinquent**.","ref":["Florida Contractors Manual  ·  2025: 2-95:  ·  Licensing - Renewal","§489.116(4)","2021: 2-74:","§489.116(4)","2017: 2-84:","§489.116(4)"],"dupes":["3-17"]},{"id":"1-101","exam":1,"num":101,"stem":"The quarterly Federal Tax Form 941 summarizes tax liability for the employer which includes __________.","options":["Liability insurance","Federal income taxes withheld","Workers compensation insurance","Federal unemployment insurance tax"],"answer":1,"topic":"tax","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"137"},{"book":"BGA","eds":null,"loc":"138"}],"exp":"Form 941 (quarterly) reports **federal income tax withheld**, plus Social Security and Medicare taxes. FUTA goes on Form 940. Workers' comp isn't a federal tax.","tip":"941 = withholding + FICA. 940 = FUTA.","ref":["Builder's Guide to Accounting  ·  137, 138  ·  Forms, Tax - 941"],"dupes":["3-27"]},{"id":"1-102","exam":1,"num":102,"stem":"The __________ summarizes the existing conditions of a business.","options":["Balance sheet","Statement of cash flows","Income statement","Statement of retained earnings"],"answer":0,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"247"},{"book":"FCM","eds":null,"loc":"3-105"}],"exp":"The **balance sheet** is a snapshot of a business's existing condition (assets, liabilities, net worth) on one date. The income statement covers a period of time.","ref":["Builder's Guide to Accounting  ·  247  ·  Financial Statements","Florida Contractors Manual  ·  3-105  ·  Chapter 3 - Definitions"],"dupes":["3-34"]},{"id":"1-103","exam":1,"num":103,"stem":"Having received the list of subcontractors, the architect immediately objects to the use of Allstate Plumbing Company. The general contractor then proposes and uses Atlas Plumbing Company at a higher cost of $5,000. The general contractor is entitled to __________.","options":["Nothing","A time extension only","$5,000 plus a proven time extension","Re-negotiate the contract with the owner"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"5.2.3"}],"exp":"A201 §5.2.3: when the Owner or Architect rejects a reasonably capable proposed sub, the contract sum and time are adjusted for the difference. The GC gets the **$5,000 plus any proven time extension**.","ref":["AIA Document A201, 2017  ·  5.2.3  ·  Subcontractors"]},{"id":"1-104","exam":1,"num":104,"stem":"The term \"lapping\" refers to __________ taken from the business by moving outstanding balances from one customer account to another.","options":["Cash","Equity","Liabilities","Receivables"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"181"}],"exp":"Lapping is fraud: **cash** is stolen and hidden by applying later customers' payments to earlier customers' balances.","ref":["Builder's Guide to Accounting  ·  181  ·  Optional TAB: Lapping"]},{"id":"1-105","exam":1,"num":105,"stem":"__________ is required to file a construction Claim of Lien.","options":["Permission from the owner","A court order","A direct contract with the owner","The claim must be recorded with the clerk of the court"],"answer":3,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-80","stat":"713.08(5)"},{"book":"FCM","eds":["2021"],"loc":"9-76","stat":"713.08(5)"},{"book":"FCM","eds":["2017"],"loc":"9-84","stat":"713.08(5)"}],"exp":"§713.08(5): a claim of lien must be **recorded with the clerk of the circuit court**. It doesn't need owner permission or a court order, and sub-tier lienors don't need a direct contract with the owner.","ref":["Florida Contractors Manual  ·  2025: 9-80:  ·  Lien - Claim of Lien","§713.08(5)","2021: 9-76:","§713.08(5)","2017: 9-84:","§713.08(5)"],"dupes":["3-40"]},{"id":"1-106","exam":1,"num":106,"stem":"__________ ratios compare accounts on the balance sheet to accounts on the income statement.","options":["Quick assets","Combined","Income account","Current"],"answer":1,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"270"}],"exp":"**Combined ratios** compare a balance sheet account to an income statement account, for example real turnover (cost of sales ÷ inventory) or return on net worth.","ref":["Builder's Guide to Accounting  ·  270  ·  Financial Ratios"],"dupes":["3-41"]},{"id":"1-107","exam":1,"num":107,"stem":"The Florida's Workers' Compensation Act is applicable to an employer in the construction industry who employs __________ or more full or part time employees.","options":["1","2","3","10"],"answer":0,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"6-5"},{"book":"FCM","eds":["2025","2021"],"loc":"5-54"},{"book":"FCM","eds":["2017"],"loc":"6-5"},{"book":"FCM","eds":["2017"],"loc":"5-54"}],"exp":"In the **construction industry**, Florida workers' comp applies to employers with **1 or more** employees. Non-construction employers need 4 or more.","tip":"Construction = 1. Non-construction = 4.","ref":["Florida Contractors Manual  ·  2025 & 2021: 6-5  ·  Workers Compensation- when","& 5-54  ·  needed","2017: 6-5, 5-54  ·  Acts: Workers Compensation"],"lock":1},{"id":"1-108","exam":1,"num":108,"stem":"__________ is a type of cost basis inventory valuation method which uses the current market value of material as it is used.","options":["Specific cost","First in-first out","Last in-first out","Cost-plus"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"120"}],"exp":"**LIFO (last in, first out)** charges the most recent costs to jobs first, so material used is valued close to current market price.","ref":["Builder's Guide to Accounting  ·  120  ·  Inventory"],"dupes":["3-43"]},{"id":"1-109","exam":1,"num":109,"stem":"__________ is NOT used when calculating goods sold to average inventory ratio.","options":["Labor","Materials purchased","All other direct costs","Total monthly averages"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"121"}],"exp":"The goods sold to average inventory ratio uses cost of goods sold (labor, materials, other direct costs) and average inventory. **\"Total monthly averages\"** isn't part of it.","ref":["Builder's Guide to Accounting  ·  121  ·  Inventory"],"dupes":["3-44"]},{"id":"1-110","exam":1,"num":110,"stem":"__________ does NOT require a written notice in order to file a claim for additional cost.","options":["A minor change in the work","Work performed because of a concealed condition","Damages caused by the architect","Work performed because of an emergency endangering the owner's property"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"15.1.5"}],"exp":"A201 §15.1.5 and §10.4: in an **emergency endangering persons or property**, the Contractor acts first, so written notice isn't required before claiming the extra cost.","ref":["AIA Document A201, 2017  ·  Section 15.1.5  ·  Claims for additional costs"],"dupes":["3-51"]},{"id":"1-111","exam":1,"num":111,"stem":"All of the following are generally included in an invoice except __________.","options":["A description of materials","The sales price of the materials","The terms of the invoice","The balance of the customer's account"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"44"}],"exp":"An invoice covers one sale: description, price and terms. **The customer's account balance** goes on a statement, not an invoice.","ref":["Builder's Guide to Accounting  ·  44, Figure 3-6  ·  Invoice - Illustrated"]},{"id":"1-112","exam":1,"num":112,"stem":"Current liabilities include the portion of long-term debt for equipment purchases that is payable within __________ days.","options":["30","90","180","365"],"answer":3,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"155"},{"book":"FCM","eds":null,"loc":"3-107"}],"exp":"Current liabilities are obligations due **within one year (365 days)**, including the current portion of long-term equipment debt.","ref":["Builder's Guide to Accounting  ·  155  ·  Current Liabilities","Florida Contractors Manual  ·  3-107  ·  Chapter 3 - Definitions"],"lock":1,"dupes":["3-54"]},{"id":"1-113","exam":1,"num":113,"stem":"Gross sales less direct costs equals __________.","options":["Gross profit","Net profit","Income from operations","Net sales"],"answer":0,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"248"}],"exp":"Gross sales − direct costs (cost of goods sold) = **gross profit**. Subtract overhead from gross profit to get net profit.","ref":["Builder's Guide to Accounting  ·  248  ·  Financial Statements"]},{"id":"1-114","exam":1,"num":114,"stem":"Assets minus liabilities equals __________.","options":["Net profit","Net worth","Gross sales","Gross profit"],"answer":1,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"247"}],"exp":"Assets − liabilities = **net worth** (owner's equity).","ref":["Builder's Guide to Accounting  ·  247  ·  Financial Statements"]},{"id":"1-115","exam":1,"num":115,"stem":"Upon initial signing of an agreement or contract with a homeowner, a contractor must deliver a written statement explaining the construction industry recovery fund. This action applies to all repairs, renovations, or construction over __________ in value.","options":["$500","$3,500","$2,500","$1,000"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-118","stat":"489.1425"},{"book":"FCM","eds":["2021"],"loc":"2-90","stat":"489.1425"},{"book":"FCM","eds":["2017"],"loc":"2-105","stat":"489.1425"}],"exp":"§489.1425: residential contracts **over $2,500** must include the written Florida Homeowners' Construction Recovery Fund notice.","ref":["Florida Contractors Manual  ·  2025: 2-118:  ·  Licensing -","§489.1425  ·  Homeowners Recovery Fund","2021: 2-90:  ·  Licensing -","§489.1425  ·  Homeowners Recovery Fund","2017: 2-105:  ·  Homeowners Recovery Fund","§489.1425  ·  payment"],"lock":1},{"id":"1-116","exam":1,"num":116,"stem":"An owner may terminate a Notice of Commencement by executing a Notice of Termination that contains all of the following except __________.","options":["Recording office document book and Page reference numbers and date of Notice of Commencement","Two copies of a Notice Direct Contract","Statement that lienors have been paid in full","Statement specifying that notice applies to all real property subject to Notice of Commencement"],"answer":1,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-85","stat":"713.132(1)"},{"book":"FCM","eds":["2021"],"loc":"9-79","stat":"713.132(1)"},{"book":"FCM","eds":["2017"],"loc":"9-91","stat":"713.132(1)"}],"exp":"§713.132(1): a Notice of Termination includes the NOC's recording information, a statement that all lienors have been paid in full, and that it applies to all property in the NOC. **Two copies of a \"notice direct contract\"** is not a requirement.","ref":["Florida Contractors Manual  ·  2025: 9-85:  ·  TOC - Notice of Termination","§713.132(1)","2021: 9-79:  ·  TOC - Notice of Termination","§713.132(1)","2017: 9-91:  ·  Notices - Notice of Termination","§713.132(1)"]},{"id":"1-117","exam":1,"num":117,"stem":"Short term schedules on construction projects are a detailed explanation of the next ___________.","options":["7 days","2 weeks","4 weeks","6 weeks"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"10-64"},{"book":"FCM","eds":["2017"],"loc":"10-64"}],"exp":"Short-term schedules give a detailed look at the **next 2 weeks** of work.","ref":["Florida Contractors Manual  ·  2025 & 2021: 10-64 TOC - Project Schedules - Short","Term Schedules","2017: 10-64  ·  Scheduling - Short Term"]},{"id":"1-118","exam":1,"num":118,"stem":"During the year, a firm used several independent contractors to perform various services. Each of these services involved payments in excess of $600 to the independent contractor performing the services. The independent contractors were not employees of the company. The company's responsibility for reporting the earnings of these contractors to the Internal Revenue Service (IRS) is that the company __________.","options":["Must immediately file a Form W-4 for these independent contractors","Must file Form 1099-NEC/1099-MISC to report total payments of $600 or more to these contractors","Must carry the contractors as employees and report their earnings along with the company's hourly or salaried personal","Has no responsibility. The independent contractors are responsible for reporting their earnings to the IRS."],"answer":1,"topic":"tax","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"138"},{"book":"FCM","eds":["2025"],"loc":"3-140"},{"book":"FCM","eds":["2021"],"loc":"3-158"},{"book":"FCM","eds":["2021"],"loc":"3-156"},{"book":"FCM","eds":["2017"],"loc":"3-152"}],"exp":"Payments of $600 or more to a non-employee in a year are reported on **Form 1099-NEC** (or 1099-MISC). W-4 is an employee withholding form. Federal law raised this threshold for payments made in 2026 and later, but the exam references use **$600**.","ref":["Builder's Guide to Accounting  ·  138  ·  Optional TAB: Independent","Florida Contractors Manual  ·  2025: 3-140  ·  Contractors","2021: 3-158 (2nd printing / 2021 IRS Circ. E)","2021: 3-156 (1st printing / 2016 IRS Circ. E)","2017: 3-152 (2016 IRS Circ. E)"]},{"id":"1-119","exam":1,"num":119,"stem":"When preparing financial statements, accruals are used to record __________.","options":["Lump sum payments","Income earned but not yet received","Cash transactions","Prepayments on a future contract"],"answer":1,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"106"},{"book":"BGA","eds":null,"loc":"107"},{"book":"FCM","eds":null,"loc":"3-105"}],"exp":"Accruals record **income earned but not yet received** (and expenses incurred but not yet paid) in the period they belong to.","ref":["Builder's Guide to Accounting  ·  106, 107","Florida Contractors Manual  ·  3-105  ·  Chapter 3 - Definitions"],"dupes":["3-74"]},{"id":"1-120","exam":1,"num":120,"stem":"Any contractor who collects a deposit of more than 10% of the contract price for any repairs, renovations, or construction to residential real property must apply for a permit within __________ days of payment.","options":["7","10","30","45"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-102","stat":"489.126(2)(a)1."},{"book":"FCM","eds":["2021"],"loc":"2-79","stat":"489.126(2)(a)1."},{"book":"FCM","eds":["2017"],"loc":"2-90","stat":"489.126(2)(a)"}],"exp":"§489.126: a contractor who takes a deposit of more than 10% on a residential job must apply for permits within **30 days** and start work within 90 days after the permit is issued.","tip":"More than 10% deposit → permit in 30 days → start in 90.","ref":["Florida Contractors Manual  ·  2025: 2-102:  ·  Licensing - Money Received","§489.126(2)(a)1.","2021: 2-79:","§489.126(2)(a)1.","2017: 2-90:","§489.126(2)(a)"],"lock":1},{"id":"1-121","exam":1,"num":121,"stem":"In which of the following situations would the percentage of completion method not be recommended?","options":["Jobs longer than two years in duration","Firms that require periodic, progressive recognition of profit from their jobs","Construction jobs producing revenue greater than $10 million","Jobs costing $1,000 - $5,000 which take approximately one week to complete"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"25"}],"exp":"Percentage of completion is meant for long, large jobs. A **$1,000–$5,000 job that takes about a week** is simpler to account for with the completed contract method.","ref":["Builder's Guide to Accounting  ·  25  ·  Percentage of completion accounting"]},{"id":"1-122","exam":1,"num":122,"stem":"One of the most practical and useful cash controls available is __________.","options":["A daily cash summary","A quarterly cash summary","A secure petty cash box","Keeping petty cash receipts"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"180"}],"exp":"A **daily cash summary** is one of the most practical cash controls: each day's receipts and disbursements get reconciled right away.","ref":["Builder's Guide to Accounting  ·  180  ·  Cash control"]},{"id":"1-123","exam":1,"num":123,"stem":"All the following are procedures included in the budget process except __________.","options":["Analyzing the results","Consulting with your accountant","Preparing the budget","Taking action to control expenses"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"144"}],"exp":"The budget process: prepare the budget, analyze results, and take action to control expenses. **Consulting your accountant** isn't one of the steps.","ref":["Builder's Guide to Accounting  ·  144  ·  Budget - analysis"],"dupes":["3-83"]},{"id":"1-124","exam":1,"num":124,"stem":"The best way to control equipment costs is good __________.","options":["Maintenance","Scheduling","Financing","Reports"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"228"}],"exp":"Per the Builder's Guide, good **scheduling** is the best way to control equipment costs, because it keeps equipment working instead of sitting idle.","ref":["Builder's Guide to Accounting  ·  228  ·  Equipment - estimating"],"dupes":["3-86"]},{"id":"1-125","exam":1,"num":125,"stem":"In order to establish an hourly cost for a bulldozer for job allocations, the __________ would NOT apply.","options":["Cost of equipment less salvage value","Operating costs involving gas, oil, and accessories","Repairing and maintenance costs","Unpredictable job site conditions"],"answer":3,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"159"},{"book":"BGA","eds":null,"loc":"160"}],"exp":"Hourly equipment cost uses cost less salvage, operating costs (fuel, oil), and repair and maintenance. **Unpredictable job site conditions** can't be built into a rate.","ref":["Builder's Guide to Accounting  ·  159, 160  ·  Equipment - cost summary"],"dupes":["3-87"]},{"id":"2-1","exam":2,"num":1,"stem":"Using straight line depreciation, the annual allowable depreciation for a tractor trailer worth $23,000 with an estimated useful life of ten years and anticipated salvage value of $2,000 is ___________.","options":["$2,100","$2,300","$1,800","$2,500"],"answer":0,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"163"}],"exp":"Straight line: (cost − salvage) ÷ useful life = ($23,000 − $2,000) ÷ 10 = $21,000 ÷ 10 = **$2,100** a year.","calc":1,"ref":["Builders Guide to Accounting  ·  163 (cost of asset−salvage value)","= annual depreciation expense useful life of asset","$23,000 - $2,000 = $21,000","$21,000 ÷ 10 = $2,100"],"lock":1},{"id":"2-2","exam":2,"num":2,"stem":"__________ is true of joint ventures.","options":["They are generally created for a single business transaction","Generally, they must adhere to a written joint venture agreement","Both A and B","None of the above"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-10"},{"book":"FCM","eds":["2021"],"loc":"1-10"},{"book":"FCM","eds":["2021"],"loc":"1-11"},{"book":"FCM","eds":["2017"],"loc":"1-12"}],"exp":"Joint ventures are usually formed for a **single project or transaction** and are generally governed by a **written joint venture agreement**. Both statements are true.","ref":["Florida Contractors Manual  ·  2025: 1-10","2021: 1-10, 1-11","2017: 1-12"],"lock":1},{"id":"2-3","exam":2,"num":3,"stem":"___________, a type of financial and business record, are NOT required to be maintained by a licensed contractor for the preceding three years.","options":["Telephone records","Employee timecards","Letters of complaints","Minutes of corporate meetings"],"answer":1,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-18","stat":"489.124(1)"},{"book":"FCM","eds":["2025"],"loc":"2-102","stat":"489.124(1)"},{"book":"FCM","eds":["2021"],"loc":"2-22","stat":"489.124(1)"},{"book":"FCM","eds":["2021"],"loc":"2-78","stat":"489.124(1)"},{"book":"FCM","eds":["2021"],"loc":"2-79","stat":"489.124(1)"},{"book":"FCM","eds":["2017"],"loc":"2-20","stat":"489.124(1)"},{"book":"FCM","eds":["2017"],"loc":"2-90","stat":"489.124(1)"}],"exp":"Per the manual's list of financial and business records under §489.124, **employee timecards** are not among the records a contractor must keep for 3 years. Timecards fall under the 2-year \"soft record\" rule.","ref":["Florida Contractors Manual  ·  2025: 2-18, 2-102, 489.124(1)","2021: 2-22, 2-78, 2-79, 489.124(1)","2017: 2-20, 2-90, 489.124(1)"]},{"id":"2-4","exam":2,"num":4,"stem":"After receiving a citation from the Board, a licensee has __________ days to dispute the citation before it becomes a final order.","options":["15","60","30","10"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.224(1)"}],"exp":"§455.224: a licensee has **30 days** after receiving a citation to dispute it. If they don't, it becomes a final order.","ref":["Florida Statute 455  ·  455.224(1)"],"lock":1},{"id":"2-5","exam":2,"num":5,"stem":"When a contractor performs obligations after receiving additional clarification that he requested from the architect for perceived needs for additional costs, when is the contractor liable for damages resulting from the work, he performed which is consistent with errors or omissions in the contract documents?","options":["The contractor would not be liable","In all instances as the contractor should have refused to do the work if he felt the documents included errors or omissions","Only if the work performed proved to be inconsistent with local building codes","Only if the work was performed by subcontractors working for the contractor"],"answer":0,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"3.2.4"}],"exp":"A201 §3.2.4: if the Contractor asked for clarification and then followed the Architect's response, **the Contractor is not liable** for damage caused by errors or omissions in the contract documents.","ref":["AIA Document A201, 2017  ·  3.2.4 Index: Claims and Disputes"]},{"id":"2-6","exam":2,"num":6,"stem":"Form 940 used to report _____________.","options":["FUTA Taxable Wages to the IRS","Wages for Federal Unemployed Trainees","Wages for Workers Compensation rate calculations","None of the above"],"answer":0,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-26"},{"book":"FCM","eds":["2025"],"loc":"3-48"},{"book":"FCM","eds":["2025"],"loc":"3-176"},{"book":"FCM","eds":["2021"],"loc":"1-26"},{"book":"FCM","eds":["2021"],"loc":"3-48"},{"book":"FCM","eds":["2021"],"loc":"3-191"},{"book":"FCM","eds":["2017"],"loc":"1-23"},{"book":"FCM","eds":["2017"],"loc":"3-48"},{"book":"FCM","eds":["2017"],"loc":"3-182"}],"exp":"Form **940** is the employer's annual return that reports **FUTA** (federal unemployment) taxable wages and tax to the IRS.","tip":"940 = FUTA, filed annually. 941 = withholding and FICA, filed quarterly.","ref":["Florida Contractors Manual  ·  2025: 1-26, 3-48, 3-176 (2025 IRS Circ. E)","2021: 1-26, 3-48, 3-191 (2021 IRS Circ. E)","2017: 1-23, 3-48, 3-182 (2017 IRS Circ. E)"],"lock":1},{"id":"2-7","exam":2,"num":7,"stem":"According to child labor laws, a seventeen-year-old can work no more than ___________ during the school session.","options":["40 hours per month","30 hours per week","10 hours in any one day","20 hours per week"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-32"}],"exp":"16- and 17-year-olds may work up to **30 hours a week** while school is in session.","ref":["Florida Contractors Manual  ·  5-32"]},{"id":"2-8","exam":2,"num":8,"stem":"__________ are properties of a Balance Sheet.","options":["Assets, liabilities, net worth","Profit, loss, net worth","Assets, debts, receivables","Income, collections, overhead"],"answer":0,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"17"}],"exp":"A balance sheet has three parts: **assets, liabilities and net worth** (equity). Profit and income belong on the income statement.","ref":["Builders Guide to Accounting  ·  17"]},{"id":"2-9","exam":2,"num":9,"stem":"A reserve of bad debt is __________.","options":["A reduction in your current assets","A general ledger entry that reflects a budgeted reserve for bad debts","A loss of cash on hand","Both A and B"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"68"}],"exp":"A bad debt reserve (allowance for doubtful accounts) **reduces current assets** (it offsets receivables) and is **a general ledger entry for a budgeted reserve**. Both are true.","ref":["Builders Guide to Accounting  ·  68"],"lock":1},{"id":"2-10","exam":2,"num":10,"stem":"It is the contractor's responsibility should he discover concealed or unknown conditions subsurface or otherwise to _____________.","options":["Provide notice to the Owner within 10 days of discovery of the conditions","Provide notice to the Architect and Owner within 10 days of discovery of the conditions","Provide notice to the Architect and Owner within 14 days of discovery of the conditions","Advise the building inspector within 3 days of perceived unsafe conditions"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"3.7.4"}],"exp":"A201 §3.7.4: when concealed or unknown conditions are found, the Contractor notifies **both the Owner and the Architect** before disturbing them, and no later than **14 days** after first observing them.","tip":"Concealed conditions = 14 days. Claims = 21 days.","ref":["AIA Document A201, 2017  ·  3.7.4"]},{"id":"2-11","exam":2,"num":11,"stem":"__________ is a way cash can be stolen by taking sums from one customer account and applying it to another's and writing off the amount of cash taken as bad debt.","options":["Falsifying sales records","Falsifying discounts","Lapping","Client transfer processing"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"181"}],"exp":"**Lapping** is stealing cash from one customer's payment and covering it with later payments from other customers. The shortfall is eventually written off as bad debt.","ref":["Builders Guide to Accounting  ·  181"]},{"id":"2-12","exam":2,"num":12,"stem":"What is the maximum number of times a licensee may go through the mediation process pertaining to complaints made against him without Board approval?","options":["The mediation process can only be used once every five years","No more than three times","There is no limit to the number of times mediation can by employed","The mediation process can only be used once every ten years"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2235(4)"}],"exp":"§455.2235(4): a licensee may go through mediation **no more than 3 times** without Board approval.","ref":["Florida Statute 455  ·  455.2235(4)"]},{"id":"2-13","exam":2,"num":13,"stem":"What guaranty does a contractor make through the issuance of a surety bond?","options":["He will complete the project as per the contract documents","He will hold the architect harmless for delays","He will assign any benefits awarded under the bond to his subcontractors","He will reimburse the surety company if he fails to perform according to contract"],"answer":3,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-12"}],"exp":"A surety bond is not insurance for the contractor. By signing the indemnity agreement, the contractor promises to **reimburse the surety** for anything the surety pays out because the contractor failed to perform.","ref":["Florida Contractors Manual  ·  4-12"]},{"id":"2-14","exam":2,"num":14,"stem":"Which of the following describes a Payroll Register?","options":["It is the same as a check register but includes details related to payroll checks","It is a system used to record only salaried workers wages","It is used to transfer check amounts to the General Ledger","It is the best way to control payroll costs"],"answer":0,"topic":"tax","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"130"}],"exp":"A **payroll register** is like a check register with payroll detail added (gross pay, deductions, net pay for each check).","ref":["Builders Guide to Accounting  ·  130"]},{"id":"2-15","exam":2,"num":15,"stem":"The minimum levels of coverage of public liability and personal damage insurance that state contractor licensees must carry is ____________.","options":["That they are the same for all trades and General Contractors","$500,000 liability and $100,000 property damage","$100,000 liability and $25,000 property damage for all trades other than General and Building Contractors and Electrical or Alarm contractors","No minimum requirements just suggested coverages"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-16","stat":"61G4-15.003"},{"book":"FCM","eds":["2025"],"loc":"2-172","stat":"61G4-15.003"},{"book":"FCM","eds":["2021"],"loc":"2-16","stat":"61G4-15.003"},{"book":"FCM","eds":["2021"],"loc":"2-131","stat":"61G4-15.003"},{"book":"FCM","eds":["2017"],"loc":"2-19","stat":"61G4-15.003"},{"book":"FCM","eds":["2017"],"loc":"2-157","stat":"61G4-15.003"}],"exp":"61G4-15.003: all trades **except general, building and residential contractors** need **$100,000 liability and $25,000 property damage**. GC, building and residential need $300,000 and $50,000. (Electrical and alarm contractors are licensed under a different board.)","ref":["Florida Contractors Manual  ·  2025: 2-16, 2-172, 61G4-15.003","2021: 2-16, 2-131, 61G4-15.003","2017: 2-19, 2-157, 61G4-15.003"]},{"id":"2-16","exam":2,"num":16,"stem":"A(an) __________ asset is goodwill.","options":["Intangible","Current","Fixed","Contingent"],"answer":0,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"253"}],"exp":"Goodwill is an **intangible asset**: it has value but no physical form, like patents and trademarks.","ref":["Builders Guide to Accounting  ·  253"]},{"id":"2-17","exam":2,"num":17,"stem":"__________ expenses are considered direct costs rather than variable overhead expenses.","options":["Labor","Union welfare","Equipment rental","Small tools"],"answer":0,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"141"}],"exp":"**Labor** on the job is a direct cost charged to that job. Union welfare, equipment rental and small tools are treated as variable overhead in this context.","ref":["Builders Guide to Accounting  ·  141"]},{"id":"2-18","exam":2,"num":18,"stem":"What information will a bank require to approve financing to a business?","options":["How much money is needed","How long will the money be needed","How will the loan be repaid","All of the above"],"answer":3,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-73"}],"exp":"A lender wants to know **how much you need, how long you need it, and how you'll repay it**. That's all of the above.","ref":["Florida Contractors Manual  ·  3-73"],"lock":1},{"id":"2-19","exam":2,"num":19,"stem":"Which of the following is not true regarding the ownership of drawings, specifications and other instruments of service?","options":["The architect and their consultants are deemed to be the authors","The owner retains ownership as they paid to have the documents prepared","Suppliers shall not own or claim a copyright interest on any of these documents","The architect retains ownership of these documents"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"1.5"}],"exp":"A201 §1.5: the Architect and its consultants are the authors and owners of the drawings and specifications and keep the copyrights. **The Owner does NOT own them just because it paid for them**, so that's the statement that's not true.","ref":["AIA Document A201, 2017  ·  1.5"]},{"id":"2-20","exam":2,"num":20,"stem":"At time of renewal, an applicant submitting proof of completed classroom continuing education, must provide proof of a minimum of __________ actual time of classroom instruction.","options":["14 hours","11 hours and 40 minutes","11 hours","50 minutes"],"answer":0,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-93","stat":"489.115(4)(b)1."},{"book":"FCM","eds":["2021"],"loc":"2-73","stat":"489.115(4)(b)1."},{"book":"FCM","eds":["2017"],"loc":"2-82","stat":"489.115(4)(b)1."}],"exp":"§489.115(4)(b): contractors must complete **14 hours** of continuing education per biennial cycle. The exam counts \"hours\" as 50-minute contact hours.","ref":["Florida Contractors Manual  ·  2025: 2-93, 489.115(4)(b)1.","2021: 2-73, 489.115(4)(b)1.","2017: 2-82, 489.115(4)(b)1."]},{"id":"2-21","exam":2,"num":21,"stem":"Why should all sales on account be accrued?","options":["This method is more accurate than any other method","Sales should not be accrued","Sales are a variable asset and therefore an accrued posting","No cash changes hands so therefore it is an accrued item"],"answer":3,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"239"}],"exp":"Sales on account are accrued because **no cash has changed hands** yet. The revenue is earned and recorded as a receivable.","ref":["Builders Guide to Accounting  ·  239"]},{"id":"2-22","exam":2,"num":22,"stem":"What two accounting tools are the most efficient way to monthly track accounts payable?","options":["Check registers for both current month and previous month billings","Profit & Loss and Balance Sheet","Two separate checking accounts","Account Payable and Account Aging registers"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"108"}],"exp":"Per the Builder's Guide, the most efficient monthly tool for tracking accounts payable is **check registers for both the current month and the previous month's billings**.","ref":["Builders Guide to Accounting  ·  108"]},{"id":"2-23","exam":2,"num":23,"stem":"The owner has __________ days to provide a bidder to a contract proof that the owner has made financial arrangements to fulfill their obligations under the contact.","options":["5","7","10","3"],"answer":1,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"6.2"}],"exp":"A701 §6.2: once a bidder asks for proof of financing, the Owner has **7 days** to provide it. The bidder must ask at least 14 days before the bid withdrawal period ends.","ref":["AIA Document A701, 2018  ·  6.2"],"lock":1},{"id":"2-24","exam":2,"num":24,"stem":"A construction firm should seek professional services from, a(an) _________ when developing a budget, cash-flow forecasts or employee benefits packages.","options":["Certified Public Bookkeeper","Accountant","Certified Public Accountant","Attorney"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-9"}],"exp":"For budgets, cash-flow forecasts and employee benefit packages, the manual recommends a **Certified Public Accountant (CPA)**.","ref":["Florida Contractors Manual  ·  3-9"]},{"id":"2-25","exam":2,"num":25,"stem":"The maximum number of days after filing any mediation proceeding involving a contractor that a dispute may be stayed is __________.","options":["60","60 unless the court orders a longer period","45 days","30 days unless agreed to by both parties"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"15.3.2"}],"exp":"A201 §15.3.2: once mediation is filed, related proceedings may be stayed for **60 days, unless a court orders a longer period** (or the parties agree to one).","ref":["AIA Document A201, 2017  ·  15.3.2"]},{"id":"2-26","exam":2,"num":26,"stem":"Which of the following is not correct about Project Schedules?","options":["They should be informally reviewed and updated every 30 days","They should be jointly prepared with a material and equipment schedule","They should include enough detail to allow adequate project control","The schedule progress should be posted at least weekly"],"answer":0,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-63"}],"exp":"Schedules should be updated continuously and progress posted at least weekly. **\"Informally reviewed every 30 days\" is not correct**.","ref":["Florida Contractors Manual  ·  10-63"]},{"id":"2-27","exam":2,"num":27,"stem":"A __________ ratio best illustrates the overall health of a business.","options":["Capital to Current Liabilities","Debt to Asset Ratio","Working Capital to Funded Debt","Current Ratio"],"answer":3,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"268"}],"exp":"Per the Builder's Guide, the **current ratio** is the single best indicator of a business's overall financial health.","ref":["Builders Guide to Accounting  ·  268"]},{"id":"2-28","exam":2,"num":28,"stem":"Which of the following are not ways to prevent bad debt in the form of open collectables?","options":["Ask for credit references from new clients","Do not take on any new clients until you can collect all current outstanding debts","Do not extend credit unless a credit application is on file","Call customers to ask them to commit to a date to pay their outstanding sums"],"answer":1,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"55"}],"exp":"Credit references, credit applications and getting customers to commit to a payment date all prevent bad debt. **Refusing all new clients until every debt is collected** isn't a prevention method. It would just stop the business.","ref":["Builders Guide to Accounting  ·  55"]},{"id":"2-29","exam":2,"num":29,"stem":"Which of the following is not considered a Fixed Overhead Expense?","options":["Salaried employee working at the corporate office","Small tools","Payroll taxes for office personnel","Printing of letterhead and envelopes"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"143"}],"exp":"**Small tools** are a variable overhead expense because they're consumed with work volume. Office salaries, office payroll taxes and letterhead printing are fixed overhead.","ref":["Builders Guide to Accounting  ·  143"]},{"id":"2-30","exam":2,"num":30,"stem":"What does an Aging List accomplish?","options":["It indicates the percentage of receivables that are current","It indicates the percentage of receivables that are uncollected","It is used to control the collections of accounts receivables","All of the above"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"46"}],"exp":"An aging list shows the percentage of receivables that are current and the percentage that are past due, and it's used to manage collections. **All of the above**.","ref":["Builders Guide to Accounting  ·  46"],"lock":1},{"id":"2-31","exam":2,"num":31,"stem":"___________ costs are freight charges on material shipped to a job by the supplier.","options":["Direct","Incidental","Indirect","Overhead"],"answer":0,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"115"}],"exp":"Freight charged by the supplier to ship material to a job is a **direct cost** of that job, just like the material.","ref":["Builders Guide to Accounting  ·  115"]},{"id":"2-32","exam":2,"num":32,"stem":"Which of the following is an allowable rule regarding approved continuing education hours?","options":["16 hours of continuing education are required at the time of renewal","60 minutes constitutes each hour of required continuing education","Up to a maximum of 50% of the continuing education may be fulfilled through pro bono services to the indigent or underserved populations","Continuing education can be performed in the classroom or via interactive distance learning"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"2-17"},{"book":"FCM","eds":["2017"],"loc":"2-19"}],"exp":"CE may be taken **in a classroom or through interactive distance learning**. The other choices are wrong: contractors need 14 hours (not 16), and a CE \"hour\" is 50 minutes (not 60).","ref":["Florida Contractors Manual  ·  2025 & 2021: 2-17","2017: 2-19"]},{"id":"2-33","exam":2,"num":33,"stem":"When is an employer liable for the payment of state re-employment tax?","options":["When he has had at least one employee for at least one day of work","When he has paid at least $1,000 in wages and has had at least one employee for a minimum of ten weeks","When he has paid at least $1,500 in wages and has had at least one employee for a minimum of twenty weeks","When they have laid off at least one employee in a quarter"],"answer":2,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-52"},{"book":"FCM","eds":["2025"],"loc":"5-258"},{"book":"FCM","eds":["2021"],"loc":"5-52"},{"book":"FCM","eds":["2021"],"loc":"5-282"},{"book":"FCM","eds":["2017"],"loc":"5-52"},{"book":"FCM","eds":["2017"],"loc":"5-284"}],"exp":"An employer owes Florida reemployment (unemployment) tax after paying **$1,500 or more in wages in a calendar quarter** or employing at least one person in each of **20 weeks** in a calendar year.","tip":"$1,500 in a quarter or 20 weeks.","ref":["Florida Contractors Manual  ·  2025: 5-52, 5-258","2021: 5-52, 5-282","2017: 5-52, 5-284"]},{"id":"2-34","exam":2,"num":34,"stem":"Which of the following would be the most desirable current ratio?","options":["3 to 1","1 to 1","2 to 1","4 to 1"],"answer":3,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"268"}],"exp":"The current ratio measures liquidity, and the higher it is, the safer. Of these choices, **4 to 1** is the most desirable. (2 to 1 is the usual minimum target.)","ref":["Builders Guide to Accounting  ·  268"],"lock":1},{"id":"2-35","exam":2,"num":35,"stem":"Which of the following is not true regarding Form 940, Employers Annual Unemployment Tax Return?","options":["It is used to report and pay federal unemployment tax","It is used to report and pay state unemployment tax on an annual basis","It is not required if you have no employees","The amount of tax paid is based on the number of employees and wages"],"answer":1,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-26"},{"book":"FCM","eds":["2025"],"loc":"3-177"},{"book":"FCM","eds":["2021"],"loc":"1-26"},{"book":"FCM","eds":["2021"],"loc":"3-192"},{"book":"FCM","eds":["2017"],"loc":"1-23"},{"book":"FCM","eds":["2017"],"loc":"3-183"}],"exp":"Form 940 is **federal** unemployment tax only. State reemployment tax is reported quarterly on the Florida RT-6, so \"reports state unemployment tax annually\" is the false statement.","ref":["Florida Contractors Manual  ·  2025: 1-26 & 3-177 (2025 IRS Circ. E)","2021: 1-26 & 3-192 (2021 IRS Circ. E)","2017: 1-23 & 3-183 (2016 IRS Circ. E)"]},{"id":"2-36","exam":2,"num":36,"stem":"A contractor must pay the subcontractor after ____________ days the contractor is paid by the owner.","options":["10","7","5","14"],"answer":1,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"11.1.3"}],"exp":"A401 §11.1.3: the Contractor pays the Subcontractor within **7 days** of receiving payment from the Owner.","ref":["AIA Document A401, 2017  ·  11.1.3"],"lock":1},{"id":"2-37","exam":2,"num":37,"stem":"In what instance is form OSHA 301 required?","options":["Any time an injury or illness is reported on OSHA 300","Only if an injury resulting in death occurs","Only if an injury is considered of lesser severity","No such OSHA form exists"],"answer":0,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-11"}],"exp":"An OSHA **301** report must be completed for **every** injury or illness recorded on the 300 log, within 7 calendar days.","ref":["Florida Contractors Manual  ·  7-11"]},{"id":"2-38","exam":2,"num":38,"stem":"Which of the following approaches is associated with Network Analysis?","options":["Critical Path Analysis (CPA)","Critical Path Method (CPM)","Project Evaluations and Review Technique (PERT)","All above are approaches associated with Network Analysis"],"answer":3,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-57"}],"exp":"Network analysis includes the **Critical Path Method (CPM), Critical Path Analysis and PERT**. All of the above.","ref":["Florida Contractors Manual  ·  10-57"],"lock":1},{"id":"2-39","exam":2,"num":39,"stem":"Privity in lien law means __________.","options":["The names of all parties to a contract are to remain private and confidential","The relationship between two or more parties to a contract","All parties to a contract that have lien rights","The requirement to mediate in the case of a contract dispute"],"answer":1,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-22"},{"book":"FCM","eds":["2017"],"loc":"9-21"}],"exp":"**Privity** is a direct contractual relationship between parties. Lienors not in privity with the owner (subs, suppliers) must serve a Notice to Owner.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-22","2017: 9-21"]},{"id":"2-40","exam":2,"num":40,"stem":"__________ are the two methods of allowable depreciation.","options":["Straight line and Curved line","Declining Balance and Increasing Value","Increasing Balance and Curved line","Straight line and Declining balance"],"answer":3,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"163"}],"exp":"The two allowable depreciation methods in the reference text are **straight line and declining balance**.","ref":["Builders Guide to Accounting  ·  163"]},{"id":"2-41","exam":2,"num":41,"stem":"A condition giving rise to a dispute occurs on May 1st and is discovered by the contractor on May 5th, the contractor must initiate the claim by __________.","options":["May 21","May 22","May 26","May 27"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"15.1.3"}],"exp":"A201 §15.1.3: claims must be started within **21 days** of the event or of when the claimant first recognizes the condition, **whichever is later**. Discovered May 5, so May 5 + 21 = **May 26**.","tip":"21 days from the later of the event or discovery.","calc":1,"ref":["AIA Document A201, 2017  ·  15.1.3"]},{"id":"2-42","exam":2,"num":42,"stem":"The ___________ accounting method recognizes income most exactly.","options":["Percentage - of - Completion","Completed - Contract","Capitalized Cost Method","Earned Income"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"25"}],"exp":"The **completed contract** method recognizes income most exactly because profit is booked only when the job is done and the actual numbers are known. Percentage of completion relies on estimates.","ref":["Builders Guide to Accounting  ·  25"]},{"id":"2-43","exam":2,"num":43,"stem":"What is one of the rules that may be provided regarding approved continuing education hours?","options":["16 hours of continuing education are required at the time of renewal","60 minutes constitutes each hour of required continuing education","Continuing education is required to be completed every three years","Continuing education can be performed in the classroom or via interactive distance learning"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"2-17"},{"book":"FCM","eds":["2017"],"loc":"2-19"}],"exp":"CE may be completed **in a classroom or through interactive distance learning**. The cycle is biennial (every 2 years), the requirement is 14 hours, and an hour means 50 minutes.","ref":["Florida Contractors Manual  ·  2025 & 2021: 2-17","2017: 2-19"]},{"id":"2-44","exam":2,"num":44,"stem":"The __________ method allows a business to take advantage of discounts offered by their suppliers for early payment of invoices.","options":["Prepayment ledger","Quantity discounts","Open invoice method","Discount invoice accounting method"],"answer":2,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-47"}],"exp":"The **open invoice method** keeps unpaid invoices on file by due date so you can pay in time to take early-payment discounts.","ref":["Florida Contractors Manual  ·  3-47"]},{"id":"2-45","exam":2,"num":45,"stem":"Contractors must maintain complete financial, sales and business records __________.","options":["For the immediately preceding five years","For the immediately preceding ten years","For the immediately preceding seven years","For the immediately preceding three years"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-18"},{"book":"FCM","eds":["2021"],"loc":"2-17"},{"book":"FCM","eds":["2017"],"loc":"2-20"}],"exp":"§489.124: contractors keep complete financial, sales and business records for the **immediately preceding 3 years**.","ref":["Florida Contractors Manual  ·  2025: 2-18","2021: 2-17","2017: 2-20"]},{"id":"2-46","exam":2,"num":46,"stem":"Which of the following is true when a temporary certificate of registration is allowed for an organization who lost its qualifying agent?","options":["The organization may proceed with contracts for incomplete work projects","There is no provision for a temporary certificate of registration, and all must work must cease until a new qualifying agent is approved","The organization may proceed with both new and incomplete contracts","None of the above are true"],"answer":0,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-23","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2025"],"loc":"2-99","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2021"],"loc":"2-22","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2021"],"loc":"2-76","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2017"],"loc":"2-20","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2017"],"loc":"2-87","stat":"489.119(3)(a)"}],"exp":"§489.119(3)(a): when a business loses its qualifier, DBPR may issue a temporary nonrenewable certificate so it can **finish incomplete contracts only**. It can't take new work until a new qualifier is approved, and the business has 60 days to replace the qualifier.","ref":["Florida Contractors Manual  ·  2025: 2-23, 2-99, 489.119(3)(a)","2021: 2-22, 2-76, 489.119(3)(a)","2017: 2-20, 2-87, 489.119(3)(a)"],"lock":1},{"id":"2-47","exam":2,"num":47,"stem":"At least _________ days before the end of a licensure cycle, the department shall forward a licensure renewal notification to an active or inactive licensee at the licensee's last known address of record or email address provided to the department.","options":["60","30","90","120"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.273(1)"}],"exp":"§455.273: DBPR sends the renewal notice at least **90 days** before the licensure cycle ends.","ref":["Florida Statute 455  ·  455.273(1)"],"lock":1},{"id":"2-48","exam":2,"num":48,"stem":"Which of the following are not considered taxable wages and are not included when calculating unemployment benefits paid by an employer?","options":["Wages paid to employees working at a convention","Excess employee discounts","Cash value of automobiles for personal use","Bonuses based on performance"],"answer":0,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-261"},{"book":"FCM","eds":["2025"],"loc":"5-266"},{"book":"FCM","eds":["2021"],"loc":"5-284"},{"book":"FCM","eds":["2021"],"loc":"5-289"},{"book":"FCM","eds":["2017"],"loc":"5-279"},{"book":"FCM","eds":["2017"],"loc":"5-292"}],"exp":"Per the reemployment tax material in the manual, **wages paid to employees working at a convention** are not taxable wages for unemployment purposes. Discounts, personal use of a company car and bonuses are taxable.","ref":["Florida Contractors Manual  ·  2025: 5-261, 5-266","2021: 5-284, 5-289","2017: 5-279, 5-292"]},{"id":"2-49","exam":2,"num":49,"stem":"What is the distinction between a work-related injury and an illness?","options":["An injury requires immediate medical attention","An illness does not require entry on OSHA logs","They are considered the same for the purpose of OSHA reporting","Illnesses do not result from instantaneous events"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-20"}],"exp":"An injury comes from a single instantaneous event (a cut, a fall). An **illness does not come from an instantaneous event**. It develops from exposure, like hearing loss or a respiratory condition.","ref":["Florida Contractors Manual  ·  7-20"]},{"id":"2-50","exam":2,"num":50,"stem":"____________ methods are used for inventory control.","options":["First in, first out","First in, discount last","Last in, first out","Both A & C"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"120"}],"exp":"The two inventory control methods are **FIFO (first in, first out) and LIFO (last in, first out)**.","ref":["Builders Guide to Accounting  ·  Pg. 120"],"lock":1},{"id":"2-51","exam":2,"num":51,"stem":"___________ is used to report and pay monthly sales tax collected.","options":["DR 15-CS Sales and Use Tax Report","DR-405 Tangible Personal Property Tax Report","ST 10- TX Sales Tax Report","Corporate Quarterly Sales Tax Report"],"answer":0,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-27"},{"book":"FCM","eds":["2017"],"loc":"1-23"}],"exp":"Florida sales tax collected is reported and paid on the **DR-15 Sales and Use Tax Return**. DR-405 is the tangible personal property tax return.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-27","2017: 1-23"]},{"id":"2-52","exam":2,"num":52,"stem":"Compounded interest is __________.","options":["Computed monthly and added to the principal","Computed annually and added to the principal","Computed monthly and subtracted from the principal","Computed monthly and credited towards the principal"],"answer":0,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-74"}],"exp":"Compound interest is **calculated each period (e.g. monthly) and added to the principal**, so later interest is charged on earlier interest too.","ref":["Florida Contractors Manual  ·  3-74"]},{"id":"2-53","exam":2,"num":53,"stem":"Which of the following is not true regarding an Employer-Multi-unit Report?","options":["It is required if an employer conducts business in more than one location in Florida","It is filed on a quarterly basis","It is mailed separately from the Employers Quarterly Report","It is mailed with the Employer's Quarterly Report"],"answer":3,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-267"},{"book":"FCM","eds":["2021"],"loc":"5-290"},{"book":"FCM","eds":["2017"],"loc":"5-292"}],"exp":"The Multiple Worksite Report is required for multiple Florida locations and is filed quarterly, but it's **mailed separately** from the Employer's Quarterly Report (RT-6). \"Mailed with\" is the false statement.","ref":["Florida Contractors Manual  ·  2025: 5-267","2021: 5-290","2017: 5-292"]},{"id":"2-54","exam":2,"num":54,"stem":"When should a sling angle be kept at greater than 45 degrees?","options":["Only when lifting a 1000 pound or greater load","Only when using multiple slings to lift a load","Only when sling legs are at an angle of 60\" vertical","Whenever possible"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-90"}],"exp":"Sling angles below 45° greatly increase the stress on the sling legs. Keep the angle **above 45° whenever possible**.","ref":["Florida Contractors Manual  ·  7-90"]},{"id":"2-55","exam":2,"num":55,"stem":"__________ are typically not included in shop drawings.","options":["Plans","Manufacturer suggested pricing","Elevations","Diagrams"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"1.1.5"}],"exp":"Shop drawings show how the contractor will build or fabricate part of the work (drawings, diagrams, elevations, schedules). They **never include pricing**.","ref":["AIA Document A201, 2017  ·  1.1.5"]},{"id":"2-56","exam":2,"num":56,"stem":"The cost related to change orders includes all the following except __________.","options":["Rental cost of machinery","Cost of field office personnel","Cost to rent hand tools","All the costs above may be included in a change order"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"7.3.4"}],"exp":"A201 §7.3.4: change costs may include rental of machinery and equipment and field office personnel, **but not hand tools**.","ref":["AIA Document A201, 2017  ·  7.3.4"],"lock":1},{"id":"2-57","exam":2,"num":57,"stem":"The bidder by making a bid represents all the following except ____________.","options":["The bidder has visited the site","The bidder has read and understands all the contract documents","The bid includes materials he believes will result in a lower build cost","The bidder is familiar with local conditions"],"answer":2,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"2.1.1"},{"book":"A701","eds":null,"loc":"2.1.4"}],"exp":"A701 §2.1: the bidder represents that it visited the site, knows local conditions, read the documents, and based the bid on the **specified** materials. Substituting materials it thinks would be cheaper isn't one of the representations.","ref":["AIA Document A701, 2018  ·  2.1.1-2.1.4"]},{"id":"2-58","exam":2,"num":58,"stem":"__________ are the two ratios most significant in analyzing overhead.","options":["Variables Overhead Expense to Sales and Variable Overhead to Receivables","Fixed Overhead to Sales and Variable Overhead to Profit","Variable Overhead Expense to Sales and Fixed Overhead to Sales","Variable Overhead to Fixed Overhead and Fixed Overhead Receivables"],"answer":2,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"147"},{"book":"BGA","eds":null,"loc":"243"}],"exp":"Overhead is analyzed with two ratios: **variable overhead to sales and fixed overhead to sales**.","ref":["Builders Guide to Accounting  ·  147, 243"]},{"id":"2-59","exam":2,"num":59,"stem":"What is the difference between the Accrual and Cash accounting methods?","options":["Only the cash method includes accounts receivables","The cash method is more accurate","The cash method only records transactions when money changes hands","These are the same methods referred to by either name"],"answer":2,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"32"}],"exp":"The **cash method** records transactions only **when money changes hands**. The accrual method records revenue when earned and expenses when incurred.","ref":["Builders Guide to Accounting  ·  32"]},{"id":"2-60","exam":2,"num":60,"stem":"The board, by rule, may establish delinquency fees for late renewal not to exceed ____.","options":["$25","$50","$100","the applicable renewal fee for renewal applications made after the expiration date of the certificate or registration"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-85","stat":"489.109(c)"},{"book":"FCM","eds":["2021"],"loc":"2-67","stat":"489.109(c)"},{"book":"FCM","eds":["2017"],"loc":"2-75","stat":"489.109(c)"}],"exp":"§489.109: delinquency fees for late renewal can't exceed **the renewal fee** for renewals made after the certificate expires.","ref":["Florida Contractors Manual  ·  2025: 2-85, 489.109(c)","2021: 2-67, 489.109(c)","2017: 2-75, 489.109(c)"]},{"id":"2-61","exam":2,"num":61,"stem":"The purpose of the Management Privatization Act is to __________.","options":["Establish a system for the protection of employee's private information","Provide a corporate veil of protections for corporate managers","Outsource management activities to private organizations","Create a model for contracting with nonprofit organizations"],"answer":3,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.32(2)"}],"exp":"§455.32, the Management Privatization Act, **creates a model for DBPR to contract with nonprofit organizations** to handle administrative, investigative and exam services.","ref":["Florida Statute 455  ·  455.32(2)"]},{"id":"2-62","exam":2,"num":62,"stem":"A __________ insurance form provides coverage for theft of property insurance.","options":["Special form","Broad form","Loss form","Theft rider form"],"answer":0,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-6"}],"exp":"A **Special Form** (all-risk) property policy covers theft. Basic and broad forms only cover named perils.","ref":["Florida Contractors Manual  ·  4-6"]},{"id":"2-63","exam":2,"num":63,"stem":"The duties of making sure results do not differ from those originally planned is an example of a ______________responsibility of the business manager.","options":["directing","controlling","assigning","standardizing"],"answer":1,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-20"},{"book":"FCM","eds":["2017"],"loc":"1-10"}],"exp":"Making sure actual results don't drift from what was planned is the **controlling** function of management. Planning, organizing and directing are the other functions.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-20","2017: 1-10"]},{"id":"2-64","exam":2,"num":64,"stem":"At what rate will an employer be billed for an outstanding re-employment tax obligation and after what time period of delinquency?","options":["5.65 % at 30 days late","5.40 % after one year late","6.25% after 90 days late","5% after one year late"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-273"},{"book":"FCM","eds":["2021"],"loc":"5-294"},{"book":"FCM","eds":["2017"],"loc":"5-297"}],"exp":"Per the manual's reemployment tax section, an employer delinquent **for more than one year** is billed at **5.40%**, the maximum rate.","ref":["Florida Contractors Manual  ·  2025: 5-273","2021: 5-294","2017: 5-297"]},{"id":"2-65","exam":2,"num":65,"stem":"Employers must display OSHA posters __________.","options":["In the employee breakroom","At the location where employees report to work","In plain view of OSHA inspectors","At each location if multiple locations exist"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-6"}],"exp":"OSHA posters must be displayed **at each location** where employees report, so multiple locations need multiple posters.","ref":["Florida Contractors Manual  ·  7-6"]},{"id":"2-66","exam":2,"num":66,"stem":"The purpose of preparing an Income Statement is __________.","options":["To borrow construction funds or secure personal credit","To divide information into various categories to prepare the inventory flow statement","To show revenues, expenses, and net income for a particular period of time","To predict debts over a specific time period"],"answer":2,"topic":"acct","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-108"}],"exp":"The income statement shows **revenues, expenses and net income for a period of time**. The balance sheet is a point-in-time snapshot.","ref":["Florida Contractors Manual  ·  3-108"]},{"id":"2-67","exam":2,"num":67,"stem":"What information do you not need to calculate the unit cost of equipment per hour?","options":["Repair and maintenance cost","OSHA productivity standards","Estimated life of equipment","Nonproductive hours of operation"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"159-160"}],"exp":"Hourly equipment cost uses repair and maintenance cost, estimated life, and productive and non-productive hours. **OSHA productivity standards** have nothing to do with it.","ref":["Builders Guide to Accounting  ·  159-160"]},{"id":"2-68","exam":2,"num":68,"stem":"When a customer account is uncollectable how do you reflect the recorded income?","options":["No action is required until the customer files bankruptcy","File a lien and take them to court","Rebook the income as a special transaction","Reverse the income previously recorded"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"63"}],"exp":"When an account can't be collected, **reverse the income** you previously recorded by writing it off as bad debt.","ref":["Builders Guide to Accounting  ·  63"]},{"id":"2-69","exam":2,"num":69,"stem":"What must an owner do if a change of ownership occurs for an entity with a Fictitious Name?","options":["Advise the Department of Professional Regulations within 30 days of change","Establish a new Fictious Name within 45 days","Record a cancelation and registration of the name within 30 days of change","Advise the Department of Professional Regulations within 10 days of change"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-14"},{"book":"FCM","eds":["2017"],"loc":"1-15"}],"exp":"If ownership of a fictitious-name business changes, **cancel the old registration and register the name again within 30 days**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-14","2017: 1-15"]},{"id":"2-70","exam":2,"num":70,"stem":"An applicant must have at least __________ years' experience for a limited license.","options":["Ten","Five","Twenty","Fifteen"],"answer":0,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.214(2)"}],"exp":"A limited license under §455.214 requires at least **10 years** of licensure.","ref":["Florida Statute 455  ·  455.214(2)"]},{"id":"2-71","exam":2,"num":71,"stem":"Which of the following is not true regarding the requirement to notify the Board?","options":["Notification of address change must be made within 15 days","Notification of address change must be made within 30 days","Notification of termination of affiliation of a qualifying agent with a business organization within 30 days","Notification of any changes required on the application for qualification of a business organization within 45 days"],"answer":0,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-173","stat":"61G4-15.007"},{"book":"FCM","eds":["2021"],"loc":"2-133","stat":"61G4-15.007"},{"book":"FCM","eds":["2017"],"loc":"2-159","stat":"61G4-15.007"}],"exp":"Per the answer key (61G4-15.007), **\"address change within 15 days\" is the statement that is NOT true**. The rule's notification deadlines quoted in the manual are 30 days and 45 days.","ref":["Florida Contractors Manual  ·  2025: 2-173, 61G4-15.007","2021: 2-133, 61G4-15.007","2017: 2-159, 61G4-15.007"]},{"id":"2-72","exam":2,"num":72,"stem":"When using Declining Balance depreciation what is depreciated on a 200 percent declining balance with a remaining balance of an average of four years?","options":["Light trucks","Machinery and equipment and small tools","Computers and office equipment","Residential property"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"166"}],"exp":"Per the Builder's Guide, the 200% declining balance class with an average 4-year remaining life covers **machinery, equipment and small tools**.","ref":["Builders Guide to Accounting  ·  166"]},{"id":"2-73","exam":2,"num":73,"stem":"When a contractor performs three categories of work how many qualifying agents are required?","options":["Only one qualifying agent is required per business","Three, one for each category of work","Two, one for the core business and one for the total of work categories","Four, one for the core business and one for each of the work categories"],"answer":1,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-23","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2025"],"loc":"2-99","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2021"],"loc":"2-22","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2021"],"loc":"2-76","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2017"],"loc":"2-20","stat":"489.119(3)(a)"},{"book":"FCM","eds":["2017"],"loc":"2-87","stat":"489.119(3)(a)"}],"exp":"Per the manual's reading of §489.119, a business performing work in three license categories needs **a qualifying agent for each category, so three**.","ref":["Florida Contractors Manual  ·  2025: 2-23, 2-99, 489.119(3)(a)","2021: 2-22, 2-76, 489.119(3)(a)","2017: 2-20, 2-87, 489.119(3)(a)"]},{"id":"2-74","exam":2,"num":74,"stem":"The purpose of the subsidiary ledger is to __________.","options":["Track all subsidized income sources","Keep the main ledger uncluttered and provide useful information","Track expenses that are billed","Track back ordered inventory"],"answer":1,"topic":"acct","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-45"}],"exp":"Subsidiary ledgers (accounts receivable, accounts payable, job cost) hold the detail so the **general ledger stays uncluttered** but the information is still available.","ref":["Florida Contractors Manual  ·  3-45"]},{"id":"2-75","exam":2,"num":75,"stem":"When selling an item to a company that is not tax exempt for $200 and the sales tax rate is 7% what will be reflected on the journal?","options":["Two separate credit entries, one of $200 and the other for $14.00","One credit entry of $214.00","One credit entry of $200 and one debit entry of $14.00","Two separate debit entries of $200 and $14.00"],"answer":0,"topic":"acct","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-64"}],"exp":"A $200 taxable sale at 7%: debit cash or accounts receivable $214. Then **two credits: Sales $200 and Sales Tax Payable $14**. The tax is a liability you owe the state, not revenue.","ref":["Florida Contractors Manual  ·  3-64"]},{"id":"2-76","exam":2,"num":76,"stem":"Which of the following are eligible for limited licenses?","options":["Limited licenses may be granted to out of state contractors after a hurricane","There is no provision for the issuance of limited licenses","Limited licenses may only be obtained by specialty contractors","Limited licenses may be granted to retired professionals in good standing to serve the indigent and underserved"],"answer":3,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.214(1)"}],"exp":"§455.214: limited licenses go to **retired professionals in good standing who will serve indigent and underserved** populations.","ref":["Florida Statute 455  ·  455.214(1)"]},{"id":"2-77","exam":2,"num":77,"stem":"If a contractor makes a false statement of insurance coverage, and this is his third offense, the minimum punishment is ________________________.","options":["$2,500 fine","$2,500 fine and/or probation or suspension","$5,000 fine","$5,000 fine and/or probation or suspension"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-205","stat":"61G4-17.001(k)2."},{"book":"FCM","eds":["2021"],"loc":"2-160","stat":"61G4-17.001(k)2."},{"book":"FCM","eds":["2017"],"loc":"2-186","stat":"61G4-17.001(k)2."},{"book":"FCM","eds":["2017"],"loc":"2-187","stat":"61G4-17.001(k)2."}],"exp":"61G4-17.001: a **third** offense of falsely stating insurance coverage carries a minimum penalty of a **$5,000 fine and/or probation or suspension**.","ref":["Florida Contractors Manual  ·  2025: 2-205, 61G4-17.001(k)2.","2021: 2-160, 61G4-17.001(k)2.","2017: 2-186, 2-187, 61G4-17.001(k)2."]},{"id":"2-78","exam":2,"num":78,"stem":"When the Department designates mediation for a licensee, how many days following resolution of the complaint by the complainant and the licensee must the mediator be advised of the resolution?","options":["14 days after contact by the mediator","21 days after contact by the mediator","30 days after contact by the mediator","60 days after contact by the mediator"],"answer":0,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2235(2)"}],"exp":"§455.2235(2): when a complaint is resolved through DBPR-designated mediation, the parties must tell the mediator within **14 days** after the mediator contacts them.","ref":["Florida Statute 455  ·  455.2235(2)"]},{"id":"2-79","exam":2,"num":79,"stem":"Proper inventory control planning can do which of the following?","options":["Increase accounts receivables","Increase volume of work","Allow multiple jobs of different scope","Eliminate unneeded working capital expenditures"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"119"}],"exp":"Good inventory control planning **eliminates unneeded working capital spending**, so cash isn't tied up in stock.","ref":["Builders Guide to Accounting  ·  119"]},{"id":"2-80","exam":2,"num":80,"stem":"Which of the following is not true concerning a S Corporation?","options":["They have multiple classes of stock","20% or more of revenue must be domestically generated","Only estates or individual can be shareholders","It must be a domestic entity"],"answer":0,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-11"},{"book":"FCM","eds":["2025"],"loc":"1-12"},{"book":"FCM","eds":["2021"],"loc":"1-12"},{"book":"FCM","eds":["2017"],"loc":"1-13"}],"exp":"An S corporation can have **only one class of stock**, so \"multiple classes of stock\" is false. It must also be domestic and have limited, eligible shareholders.","ref":["Florida Contractors Manual  ·  2025: 1-11, 1-12","2021: 1-12","2017: 1-13"]},{"id":"2-81","exam":2,"num":81,"stem":"For what period must examination scores for each applicant be maintained by the Department?","options":["No less than three years immediately following the examination","No less than two years immediately following the examination","No less than one year immediately following the examination","No less than five years immediately following the examination"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.217(4)"}],"exp":"§455.217(4): DBPR keeps each applicant's exam scores for at least **2 years** after the exam.","ref":["Florida Statute 455  ·  455.217(4)"]},{"id":"2-82","exam":2,"num":82,"stem":"___________ is the purpose of the accrual accounting method.","options":["To record revenue when earned","To record expense when incurred","To track the timely payment of accounts receivables","Both A and B"],"answer":3,"topic":"acct","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-17"}],"exp":"The accrual method **records revenue when earned and expenses when incurred**, whether or not cash has moved. Both A and B.","ref":["Florida Contractors Manual  ·  3-17"],"lock":1},{"id":"2-83","exam":2,"num":83,"stem":"Who assumes responsibility for the accuracy of the shop drawings and samples once submitted by the contractor to the architect for review?","options":["The architect","Review by the architect does not release the contractor from the responsibility","Both the contractor and architect since they have both reviewed the submissions","The owner as well as his contractor and architect since they all have reviewed the submissions"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"4.2.7"}],"exp":"A201 §4.2.7: the Architect's review of shop drawings and samples **doesn't relieve the Contractor** of responsibility for their accuracy.","ref":["AIA Document A201, 2017  ·  4.2.7"]},{"id":"2-84","exam":2,"num":84,"stem":"__________ are all types of assets.","options":["Fixed, current and tangible","Fixed, intangible and current","Fixed, variable, tangible","Fixed, variable and current"],"answer":1,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"252-253"}],"exp":"The asset types are **fixed, intangible and current**. \"Variable\" describes expenses, not assets.","ref":["Builders Guide to Accounting  ·  252-253"]},{"id":"2-85","exam":2,"num":85,"stem":"__________ is the act of setting up a piece of equipment on your general ledger.","options":["Establishing the depreciation schedule","Establishing the amortization schedule","Converting a long-term asset to a current asset","Capitalizing the expense"],"answer":3,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"155"}],"exp":"**Capitalizing the expense** means putting equipment on the books as a fixed asset instead of expensing it, and then depreciating it.","ref":["Builders Guide to Accounting  ·  155"]},{"id":"2-86","exam":2,"num":86,"stem":"__________ overhead costs vary related to sales volume.","options":["Commission","Advertising","Phone Service","Utilities"],"answer":0,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"141"}],"exp":"**Commissions** go up and down with sales volume. Advertising, phone and utilities are relatively fixed.","ref":["Builders Guide to Accounting  ·  141"]},{"id":"2-87","exam":2,"num":87,"stem":"Which of the following are advantages of Corporations?","options":["They are closely regulated","Stockholders are not exempt from liability","They are taxed only once","Fringe benefits are tax deducible"],"answer":3,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-11"},{"book":"FCM","eds":["2017"],"loc":"1-13"}],"exp":"A corporate advantage: **fringe benefits are tax-deductible** to the corporation. Heavy regulation and double taxation are disadvantages, and stockholders do have limited liability.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-11","2017: 1-13"]},{"id":"2-88","exam":2,"num":88,"stem":"In what time period must the Department issue a citation after the filing of a complaint against a licensee?","options":["Thirty days","Two months","One year","Six months"],"answer":3,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.224(4)"}],"exp":"§455.224(4): a citation must be issued within **6 months** after the complaint is filed.","ref":["Florida Statute 455  ·  455.224(4)"]},{"id":"2-89","exam":2,"num":89,"stem":"What can a high inventory ratio indicate about your business?","options":["You practice First In, First Out inventory controls","Your inventory is too low and could adversely affect sales","Your average inventory is too high","You inventory levels are higher than those of your competitors"],"answer":1,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"121"}],"exp":"A high inventory turnover ratio means inventory is moving fast and may be **too low**, so you could run short and lose sales.","tip":"High ratio = low inventory.","ref":["Builders Guide to Accounting  ·  121"]},{"id":"2-90","exam":2,"num":90,"stem":"Which of the following accounting methods is used to allocate costs and expenses incurred to a project to determine if the budget is met?","options":["Project cost method","Accrual method","Cost accounting","Cash flow analysis method"],"answer":2,"topic":"job","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-65"},{"book":"FCM","eds":null,"loc":"3-106"}],"exp":"**Cost accounting** assigns costs and expenses to each project so you can compare actual costs with the budget.","ref":["Florida Contractors Manual  ·  3-65, 3-106"]},{"id":"2-91","exam":2,"num":91,"stem":"Who prepares and signs all change orders?","options":["Only the architect is required to prepare and sign change orders","The architect prepares and the owner signs off on the change","The architect prepares and signs and then the owner and contractor sign","The contractor prepares and the owner and architect sign"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"7.2.1"}],"exp":"A201 §7.2.1: the **Architect prepares and signs the change order, then the Owner and Contractor sign** it.","ref":["AIA Document A201, 2017  ·  7.2.1"]},{"id":"2-92","exam":2,"num":92,"stem":"Which of the following steps are included in the preparation of a company's payroll?","options":["Determining each employees' gross earnings","Determining each employee's deductions","Calculating the employer's associated payroll expenses","All the above"],"answer":3,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-47"},{"book":"FCM","eds":null,"loc":"3-48"}],"exp":"Payroll preparation includes figuring each employee's gross pay, each employee's deductions, and the employer's own payroll expenses. **All of the above**.","ref":["Florida Contractors Manual  ·  3-47, 3-48"],"lock":1},{"id":"2-93","exam":2,"num":93,"stem":"When is it a good idea to remove a fully depreciated asset from your book?","options":["At the end of its economic life","When you can afford to buy additional but not replacement equipment","Only when the equipment is sold, abandoned or traded","When you have exhausted all tax credits"],"answer":2,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"170"}],"exp":"Keep a fully depreciated asset on the books **until it's sold, abandoned or traded**.","ref":["Builders Guide to Accounting  ·  170"]},{"id":"2-94","exam":2,"num":94,"stem":"The Department can __________ with the $5.00 fee that is included in the current licensee fee.","options":["Educate the public regarding unlicensed activity","Transfer the funds to the State of Florida's general budget account","Subsidize the application fee for applicants from the indigent community","Reimburse the public when damaged by unlicensed workers"],"answer":0,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2281"}],"exp":"§455.2281: the $5 unlicensed activity fee pays for **educating the public about unlicensed activity** and for enforcement against it.","ref":["Florida Statute 455  ·  455.2281"]},{"id":"2-95","exam":2,"num":95,"stem":"Which of the following is true about depreciation?","options":["It only applies to property that appreciates in value","You cannot depreciate intangible property","You may change the method by which you calculate depreciation with your Accountant's written explanation to the IRS","Obsolescence is of no consequence when determining how to depreciate assets"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"162"}],"exp":"Per the Builder's Guide, **intangible property can't be depreciated** (it is amortized instead). Changing depreciation methods requires IRS approval.","ref":["Builders Guide to Accounting  ·  162"]},{"id":"2-96","exam":2,"num":96,"stem":"How many days prior to the date established for payment shall the contractor submit a request for payment and to whom?","options":["14 days submitting to the owner for payment","14 days submitting to the architect","10 days submitting to the owner for payment","10 days submitting to the architect for payment"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"9.3.1"}],"exp":"A201 §9.3.1: submit the Application for Payment **10 days** before the payment date, **to the Architect**.","ref":["AIA Document A201, 2017  ·  9.3.1"]},{"id":"2-97","exam":2,"num":97,"stem":"Which of the following are reasons to maintain employee timecards?","options":["Employees can use them to file their taxes with the IRS","Can be used in unemployment disputes","They can be used to calculate annual bonus amounts","The IRS requires they be kept for 5 years"],"answer":1,"topic":"tax","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"127"}],"exp":"Timecards prove hours worked, so they're useful evidence in **unemployment claims and disputes**.","ref":["Builders Guide to Accounting  ·  127"]},{"id":"2-98","exam":2,"num":98,"stem":"How long is a Fictious Name valid for and when do they expire?","options":["3 years and expire on December 31st of the third year","5 years and expire on December 31st of the fifth year","10 years and expire on the anniversary date of filing","They never expire nor need renewing if the entity remains active"],"answer":1,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-15"},{"book":"FCM","eds":["2021"],"loc":"1-15"},{"book":"FCM","eds":["2017"],"loc":"1-14"}],"exp":"A fictitious name registration is valid **5 years and expires December 31 of the fifth year**.","ref":["Florida Contractors Manual  ·  2025: 1-15","2021: 1-15","2017: 1-14"]},{"id":"2-99","exam":2,"num":99,"stem":"Which one of the following is not accomplished through good inventory controls?","options":["Reduces the need for storage","Reduces taxes and insurance and other costs","Reduces exposure of materials to theft","Reduces the need to backorder inventory"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"121"}],"exp":"Good inventory control reduces storage, carrying costs (taxes, insurance) and theft exposure. **Reducing the need to backorder is not** one of its results.","ref":["Builders Guide to Accounting  ·  121"]},{"id":"2-100","exam":2,"num":100,"stem":"The current ratio is calculated by __________.","options":["Adding cash and accounts receivable and dividing by liabilities","Dividing current liabilities by current assets","Dividing current assets by current liabilities","Comparing the total loan debt to current income"],"answer":2,"topic":"ratio","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-89"}],"exp":"Current ratio = **current assets ÷ current liabilities**.","ref":["Florida Contractors Manual  ·  3-89"]},{"id":"2-101","exam":2,"num":101,"stem":"The __________ lists all checks cashed and who cashed them.","options":["Cash Register","Check Ledger","Check Register","Subsidiary Ledger"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"101"}],"exp":"The **check register** lists every check written, who it was paid to and the amount.","ref":["Builders Guide to Accounting  ·  101"]},{"id":"2-102","exam":2,"num":102,"stem":"__________ are the minimum levels of coverage of public liability and property damage insurance General Contractors must carry.","options":["$100,000 liability and $25,000 property damage","$500,000 liability and $100,000 property damage","$300,000 liability and $50,000 property damage","$150,000 liability and $50,000 property damages"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-16","stat":"61G4-15.003"},{"book":"FCM","eds":["2025"],"loc":"2-172","stat":"61G4-15.003"},{"book":"FCM","eds":["2021"],"loc":"2-16","stat":"61G4-15.003"},{"book":"FCM","eds":["2021"],"loc":"2-131","stat":"61G4-15.003"},{"book":"FCM","eds":["2017"],"loc":"2-19","stat":"61G4-15.003"},{"book":"FCM","eds":["2017"],"loc":"2-157","stat":"61G4-15.003"}],"exp":"61G4-15.003: general, building and residential contractors need **$300,000 public liability and $50,000 property damage** coverage.","ref":["Florida Contractors Manual  ·  2025: 2-16, 2-172, 61G4-15.003","2021: 2-16, 2-131, 61G4-15.003","2017: 2-19, 2-157, 61G4-15.003"]},{"id":"2-103","exam":2,"num":103,"stem":"OSHA records are to be located __________ when employees are not associated with a fixed establishment.","options":["At the nearest fixed location","At field offices or mobile base operation locations","At the corporate office","Where the employees report to work each day"],"answer":1,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-15"}],"exp":"When employees don't work at a fixed establishment, keep OSHA records **at the field office or mobile base of operations**.","ref":["Florida Contractors Manual  ·  7-15"]},{"id":"2-104","exam":2,"num":104,"stem":"Which of the following are not required recordable injuries?","options":["Injuries requiring first aid treatment only","Removing foreign items from the eye with tweezers","Use of prescription medications","Application of bandages by medical personnel"],"answer":0,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-22"},{"book":"FCM","eds":null,"loc":"7-23"},{"book":"FCM","eds":null,"loc":"7-24"}],"exp":"**First-aid-only** injuries aren't recordable (bandages, tweezer removal of objects from the eye, non-prescription medicine at non-prescription strength). Prescription medication makes a case recordable.","ref":["Florida Contractors Manual  ·  7-22, 7-23, 7-24"]},{"id":"2-105","exam":2,"num":105,"stem":"Which of the following are not the owner's responsibility to pay?","options":["Easements","Use or occupancy of permanent structures","Permits and fees assigned to the contractor under the contract documents","Permanent changes to existing facilities"],"answer":2,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"2.3"}],"exp":"A201 §2.3: the Owner pays for easements, zoning approvals, permanent structures and permanent changes to facilities. **Permits and fees the contract assigns to the Contractor** are the Contractor's cost.","ref":["AIA Document A201, 2017  ·  2.3"]},{"id":"2-106","exam":2,"num":106,"stem":"To whom and on what schedule shall bonds related to a bid be delivered by the bidder?","options":["To the architect no later than three days after contract execution","To the architect no later than five days after contract execution","To the owner no later than five days after contract execution","To the owner no later than three days after contract execution"],"answer":3,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"7.2"}],"exp":"A701 §7.2: bonds go **to the Owner within 3 days** after the contract is executed.","ref":["AIA Document A701, 2018  ·  7.2"]},{"id":"2-107","exam":2,"num":107,"stem":"What is an example of an incentive discount offered to customers to pay open invoices?","options":["2% - 10- days, net 30","Never offer a discount and insist your customers pay the full price","10% off on all orders over $1,000","None of the above"],"answer":0,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"59"}],"exp":"**\"2% 10, net 30\"** is the classic incentive discount for paying open invoices early.","ref":["Builders Guide to Accounting  ·  59"],"lock":1},{"id":"2-108","exam":2,"num":108,"stem":"What penalty is imposed for failure or refusal of an employer or carrier to report any form or notice associated with a death as required by Chapter 440, Workers Compensation Laws?","options":["Fine not to exceed $1000","Fine not to exceed $1500","Fine not to exceed $500","Fine not to exceed $500 for the first failure and not to exceed $2000 for each subsequent failure"],"answer":2,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"6-121","stat":"440.185(8)"},{"book":"FCM","eds":["2021"],"loc":"6-113","stat":"440.185(8)"},{"book":"FCM","eds":["2017"],"loc":"6-165","stat":"440.185(8)"}],"exp":"§440.185(8): an employer or carrier that fails to file required workers' comp reports or notices can be fined **up to $500 for each failure**.","ref":["Florida Contractors Manual  ·  2025: 6-121. 440.185(8)","2021: 6-113, 440.185(8)","2017: 6-165, 440.185(8)"]},{"id":"2-109","exam":2,"num":109,"stem":"When preparing an estimate, __________ would be included as a fixed overhead expense.","options":["Equipment costs","Corporate office personnel payroll costs","Direct labor and payroll taxes","Material costs"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"142"},{"book":"BGA","eds":null,"loc":"143"},{"book":"BGA","eds":null,"loc":"227"}],"exp":"**Corporate office personnel payroll** is a fixed overhead expense. Equipment, direct labor and materials are job costs.","ref":["Builders Guide to Accounting  ·  142, 143 & 227"]},{"id":"2-110","exam":2,"num":110,"stem":"__________ is/are not components of a safety program.","options":["A policy statement regarding safety","Safety Rules","Workers' Compensation Guidelines","Employee Orientation program"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-36"},{"book":"FCM","eds":null,"loc":"7-37"},{"book":"FCM","eds":null,"loc":"7-38"},{"book":"FCM","eds":null,"loc":"7-39"}],"exp":"A safety program includes a safety policy statement, safety rules and employee orientation. **Workers' comp guidelines** aren't part of it.","ref":["Florida Contractors Manual  ·  7-36, 7-37, 7-38, 7-39"]},{"id":"2-111","exam":2,"num":111,"stem":"Which of the following is not true regarding posting a Notice of Commencement?","options":["When a loan exists, it is the contractor's responsibly to post the notice","It may be posted no sooner than 90 days prior to the start of work at the site","The owner is obligated to post a copy at the site","The posted notice always needs to remain on site"],"answer":0,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-12"},{"book":"FCM","eds":["2017"],"loc":"9-11"}],"exp":"The **Owner**, not the contractor, records the Notice of Commencement and posts a copy at the job site. \"When a loan exists, the contractor posts it\" is the false statement.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-12","2017: 9-11"]},{"id":"2-112","exam":2,"num":112,"stem":"__________ must be kept separate from other assets when calculating depreciation.","options":["Land","Office Furniture and Equipment","Truck and Autos","On site equipment"],"answer":0,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"162"}],"exp":"**Land** isn't depreciable, so it must be kept separate from depreciable assets such as buildings.","ref":["Builders Guide to Accounting  ·  162"]},{"id":"2-113","exam":2,"num":113,"stem":"Under what circumstance may a foreign trained professional be allowed to take the examination for construction licensing?","options":["If the applicant immigrated to the US for political reasons","If the applicant successfully completed an approved course prior to 1990","If the applicant immigrated to the US for political reason from a county located in the Western Hemisphere lacking diplomatic relations with the US","There is no special circumstance under which an applicant may take the exam and they must adhere to the same rules as all other applicants"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.218(a)"}],"exp":"§455.218: a foreign-trained professional may sit for the exam if they **immigrated for political reasons from a Western Hemisphere country that lacks diplomatic relations with the U.S.**","ref":["Florida Statute 455  ·  455.218(a)"]},{"id":"2-114","exam":2,"num":114,"stem":"When should you provide an incentive discount to customers based on receivables?","options":["When they can refer you other business","When you want to increase sales","When you want them to pay their open invoice quickly","When they have an \"A\" credit rating"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"59"}],"exp":"Incentive discounts on receivables are offered **to get customers to pay open invoices quickly**.","ref":["Builders Guide to Accounting,  ·  59"]},{"id":"2-115","exam":2,"num":115,"stem":"When a subcontractor defaults on work in accordance with agreement with a contractor which of the following are allowable remedies for the contractor?","options":["The contactor may correct the default if the subcontractor has failed to do so within 10 days after the subcontractor received notice from the contractor","Architect may hire a new subcontractor if the subcontractor has failed to correct the default within 5 days after receipt of notice from the contractor","Contactor may correct the default if the subcontractor has failed to do so within 5 days after the subcontractor received notice from the contractor","Architect may hire a new subcontractor if the subcontractor has failed to correct the default within 10 days after receipt of notice from the contractor"],"answer":2,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"3.5"}],"exp":"A401 §3.5: if the Sub defaults and doesn't start correcting within **5 days** of the Contractor's notice, the **Contractor** may correct the work and charge the Sub. The architect plays no role in the subcontract.","tip":"A401 contractor vs. sub = 5 days. A201 owner vs. contractor = 10 days.","ref":["AIA Document A401, 2017  ·  3.5"]},{"id":"2-116","exam":2,"num":116,"stem":"The total maximum allowable penalty for an employer who committed a willful or repeated violation of OSHA regulations and failed to comply with OSHA mandated posting requirements is __________.","options":["$136,942","$148,431","$149,413","$177,454"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-31"}],"exp":"The answer depends on your manual's edition. **2025 FCM:** willful or repeated $161,323 + posting $16,131 = **$177,454**. 2021: $134,937 + $13,494 = $148,431. 2017: $124,471 + $12,471 = $136,942. Use the penalty table in the edition you'll bring to the exam.","calc":1,"ref":["Florida Contractors Manual  ·  7-31","There are two different answers depending which edition of the book you have:","2025: Per the text, the OSHA civil penalties are as followed:","Willful or Repeated Violation - $161,323","Posting Requirements - $16,131","$161,323 + $16,131 = $177,454","[B] 2021: Per the text, the OSHA civil penalties are as followed:","Willful or Repeated Violation - $134,937","Posting Requirements - $13,494","$134,937 + $13,494 = $148,431","[A] 2017: Per the text, the OSHA civil penalties are as followed:","Willful or Repeated Violation - $124,471","Posting Requirements - $12,471","$124,471 + $12,471 = $136,942"],"lock":1,"edAns":{"2025":3,"2021":1,"2017":0}},{"id":"2-117","exam":2,"num":117,"stem":"Which of the following should be considered when deciding on the man-hour range to use when creating an estimate?","options":["Weather conditions","Time allowed for project completion","Skill and experience of the craftsman","All the above"],"answer":3,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-30"}],"exp":"Man-hour ranges depend on weather, the time allowed for the project, and crew skill. **All of the above**.","ref":["Florida Contractors Manual  ·  10-30"],"lock":1},{"id":"2-118","exam":2,"num":118,"stem":"How many copies of the contract documents must the owner provide the contractor?","options":["Two signed originals and one copy","One signed original and one copy","One signed original and one copy","One"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"2.3.6"}],"exp":"A201 §2.3.6: the Owner furnishes **one copy** of the contract documents free of charge, for the Contractor to reproduce.","ref":["AIA Document A201, 2017  ·  2.3.6"]},{"id":"2-119","exam":2,"num":119,"stem":"The contractor will submit a certificate for payments within __________ days after the work is complete.","options":["7","10","3","None of the above"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"9.4.1"}],"exp":"A201 §9.4.1: the *Architect*, not the contractor, issues the Certificate for Payment, within 7 days of receiving the application. So **none of the above**.","ref":["AIA Document A201, 2017  ·  9.4.1"],"lock":1},{"id":"2-120","exam":2,"num":120,"stem":"Where and for what period must OSHA 300/300A and any supplementary reports be maintained by the employer?","options":["Retained in the corporate headquarters office for 5 calendar years following the end of the year to which they relate","Retained in the corporate headquarters office for 3 calendar years following the end of the year to which they relate","Retained in each establishment for 5 calendar years following the end of the year to which they relate","Retained in each establishment for 3 calendar years following the end of the year to which they relate"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-16"}],"exp":"OSHA 300, 300A and 301 records are kept **at each establishment for 5 years** after the end of the year they cover.","ref":["Florida Contractors Manual  ·  7-16"]},{"id":"2-121","exam":2,"num":121,"stem":"Unless otherwise provided for in the contract documents, the contractor will pay for which of the following?","options":["It is the owner's responsibility to pay for all permits, not the contractor","Building permits, fees, inspections by the local building department","Only permits when issued in their name excluding work performed by contractors","Only building permits"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"3.7.1"}],"exp":"A201 §3.7.1: unless the contract says otherwise, the Contractor pays for **building permits, fees, licenses and government inspections**.","ref":["AIA Document A201, 2017  ·  3.7.1"]},{"id":"2-122","exam":2,"num":122,"stem":"Which of the following does not affect the productivity rate of equipment?","options":["Experience of the operator","Overruns of Equipment","Climate and weather conditions","Permissible speeds"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-27"},{"book":"FCM","eds":null,"loc":"10-28"}],"exp":"Equipment productivity depends on operator experience, climate and weather, and permissible speeds. **\"Overruns of equipment\"** isn't a productivity factor.","ref":["Florida Contractors Manual  ·  10-27 & 10-28"]},{"id":"2-123","exam":2,"num":123,"stem":"Which of the following is not true regarding filing a Notice to Owner?","options":["Must be filed before commencing or no later than 45 days after completing work","Must be filed before the owner's disbursement of final payment","Must be filed before commencing or no later than 45 days after commencing work","Must be filed regardless of the method of payment by the owner"],"answer":0,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-75"},{"book":"FCM","eds":["2021"],"loc":"9-72","stat":"713.06(2)(a)"},{"book":"FCM","eds":["2017"],"loc":"9-76","stat":"713.06(2)(a)"}],"exp":"§713.06(2)(a): a Notice to Owner is served before work starts, or **within 45 days of starting** work, not within 45 days of *completing* it. \"After completing\" is the false statement.","tip":"NTO = 45 days from first furnishing.","ref":["Florida Contractors Manual  ·  2025: 9-75","2021: 9-72, 713.06(2)(a)","2017: 9-76 , 713.06(2)(a)"]},{"id":"2-124","exam":2,"num":124,"stem":"Which of the following must the contractor make available at the site?","options":["Change orders, product data and samples","Change orders, product data, samples and proof of liability coverage","Contract documents and proof of liability coverage","None of the above, these are the responsibility of the architect to make available"],"answer":0,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"3.11"}],"exp":"A201 §3.11: the Contractor keeps at the site the drawings, specifications, addenda, **change orders**, approved shop drawings, **product data and samples**.","ref":["AIA Document A201, 2017  ·  3.11"],"lock":1},{"id":"2-125","exam":2,"num":125,"stem":"Real turnover is an example of a __________ ratio.","options":["Combined","Current","Accrual","Balanced"],"answer":0,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"270-271"}],"exp":"Real turnover (cost of sales ÷ inventory) mixes an income statement figure with a balance sheet figure, so it's a **combined** ratio.","ref":["Builders Guide to Accounting  ·  270-271"]},{"id":"3-1","exam":3,"num":1,"stem":"How many days prior to the date established in a contract for progress payments shall a contractor submit to the architect application for payment?","options":["3","5","7","10"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"9.3.1"}],"exp":"A201 §9.3.1: the Application for Payment goes to the Architect at least **10 days** before the payment date.","ref":["AIA Document A201, 2017  ·  9.3.1"],"lock":1},{"id":"3-2","exam":3,"num":2,"stem":"Which is a method of improving cash flow?","options":["Maintaining a high inventory","Taking advantage of discounts","Converting all cash sales to accounts receivable","Paying off liabilities"],"answer":1,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"262"}],"exp":"**Taking advantage of discounts** improves cash flow. High inventory and turning cash sales into receivables tie cash up.","ref":["Builder's Guide to Accounting  ·  262"],"dupes":["1-90"]},{"id":"3-3","exam":3,"num":3,"stem":"A subcontractor has a \"Standard Form of Agreement Between Contractor and Subcontractor\" with the prime contractor on a project. The ONLY way the subcontractor can assign work on the subcontract is with written __________.","options":["Consent of the owner or architect","Consent of the contractor","Notification to the owner or architect","Notification to the contractor"],"answer":1,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"7.4.2"}],"exp":"A401 §7.4.2: the Sub may assign the subcontract only with the **Contractor's written consent**.","ref":["AIA Document A401, 2017  ·  7.4.2"],"dupes":["1-91"]},{"id":"3-4","exam":3,"num":4,"stem":"Who is eligible for Small Business Association loans?","options":["All building contractors in the Unites States","Only company presidents","Applicants who cannot obtain a loan from local banks","Applicants who are recommended by a local bank"],"answer":2,"topic":"org","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"318-319"}],"exp":"SBA loans are for **applicants who can't get a loan from local banks** on reasonable terms.","ref":["Builder's Guide to Accounting  ·  318-319"]},{"id":"3-5","exam":3,"num":5,"stem":"When can a Notice of Commencement be extended past one year?","options":["If it is written into the Notice of Commencement","If the job proceeds past one year","When there is an architectural change order","Never"],"answer":0,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-83","stat":"713.13(1)(c)"},{"book":"FCM","eds":["2021"],"loc":"9-78","stat":"713.13(1)(c)"},{"book":"FCM","eds":["2017"],"loc":"9-88","stat":"713.13(1)(c)"}],"exp":"§713.13(1)(c): an NOC expires after 1 year **unless the notice states a different expiration date**.","ref":["Florida Contractors Manual  ·  2025: 9-83: 713.13(1)(c)","2021: 9-78: 713.13(1)(c)","2017: 9-88: 713.13(1)(c)"],"dupes":["1-93"]},{"id":"3-6","exam":3,"num":6,"stem":"The bidder making a bid represents that he or she __________.","options":["Is familiar with local conditions under which the work is to be performed","Is making a bid contingent on standard codes and conditions","Will adjust accordingly if the bid is accepted if an addendum is made","Will provide specifications for all materials"],"answer":0,"topic":"aia","books":["A701"],"cites":[{"book":"A701","eds":null,"loc":"2.1.4"}],"exp":"A701 §2.1: by bidding, the bidder represents that it **is familiar with the local conditions** where the work will be done (and visited the site and read the documents).","ref":["AIA Document A701, 2018  ·  2.1.4"]},{"id":"3-7","exam":3,"num":7,"stem":"A contractor receives payment from the owner of a construction project. The contractor shall pay the subcontractor each progress payment within __________.","options":["3 working days","3 days (including Saturday and Sunday)","5 working days","7 working days"],"answer":3,"topic":"aia","books":["A401"],"cites":[{"book":"A401","eds":null,"loc":"11.3"}],"exp":"A401 §11.3 and A201 §9.6.2: pay the Sub within **7 working days** of receiving the Owner's payment.","ref":["AIA Document A401, 2017  ·  11.3"],"dupes":["1-95"]},{"id":"3-8","exam":3,"num":8,"stem":"Which is NOT a delay factor when determining production efficiency percentages?","options":["Accessibility of site","Financial incentives","Poorly trained personnel","Weather conditions"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-30"},{"book":"FCM","eds":null,"loc":"10-31"}],"exp":"Site access, poorly trained personnel and weather all slow production. **Financial incentives** aren't a delay factor (they usually raise productivity).","ref":["Florida Contractors Manual  ·  10-30, 10-31"]},{"id":"3-9","exam":3,"num":9,"stem":"When a piece of equipment is sold, why is it necessary to book the transaction separate from regular sales?","options":["It is treated as a variable expense","It receives different tax treatment","The transaction is not taxable","Gains or losses must be used to adjust gross profits"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"170"}],"exp":"Equipment sales **receive different tax treatment** (gain or loss, depreciation recapture), so they're recorded separately from regular sales.","ref":["Builder's Guide to Accounting  ·  170"],"dupes":["1-96"]},{"id":"3-10","exam":3,"num":10,"stem":"According to Fair Labor Standards Act, which will eliminate the contractor's liability for paying overtime pay?","options":["An agreement that only 8 hours per day or 40 hours per week will be counted as working time","An outside salesperson who works on straight commission and qualifies as exempt status","An announcement by an employer that overtime work will only be paid for if authorized in advance","An announcement by an employer that no overtime work will be permitted"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-17"}],"exp":"Only a real FLSA exemption, such as an **exempt outside salesperson on straight commission**, removes the overtime obligation. If overtime is worked, it must be paid, whatever the employer has announced.","ref":["Florida Contractors Manual  ·  5-17"]},{"id":"3-11","exam":3,"num":11,"stem":"Which is an advantage of leasing?","options":["Lowers overall cash flows more than purchasing","Reduced front-end cash outlays","Generates depreciation for tax purposes","Cheaper than owning in the long run"],"answer":1,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-93"}],"exp":"The main advantage of leasing is **lower up-front cash outlay**. Owning usually costs less over the long run, and only owned equipment generates depreciation.","ref":["Florida Contractors Manual  ·  3-93"]},{"id":"3-12","exam":3,"num":12,"stem":"A change of a business address must be mailed to the Department of Business and Professional Regulation within how many days of the change?","options":["30","45","60","90"],"answer":1,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-31"},{"book":"FCM","eds":["2021"],"loc":"2-29"},{"book":"FCM","eds":["2017"],"loc":"2-22"}],"exp":"A change of business address (part of the business organization's qualification information) must be reported to DBPR within **45 days** (61G4-15.007).","ref":["Florida Contractors Manual  ·  2025: 2-31","2021: 2-29","2017: 2-22"],"lock":1},{"id":"3-13","exam":3,"num":13,"stem":"All chains being used as a sling, should be inspected once a __________ by a competent inspector.","options":["Day","Week","Month","Year"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-89"}],"exp":"Per the manual (FCM 7-89), chains used as slings should get a thorough inspection by a competent inspector once a **month**, in addition to the daily pre-use check.","ref":["Florida Contractors Manual  ·  7-89"]},{"id":"3-14","exam":3,"num":14,"stem":"Which of the following is NOT a prohibited agreement under the Florida's Right to Work Law?","options":["Union shop agreements","Agency shop agreements","Federal enclaves' agreements","Maintenance of membership agreements"],"answer":2,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-14"},{"book":"FCM","eds":null,"loc":"5-15"}],"exp":"Florida's Right to Work law prohibits union shop, agency shop and maintenance-of-membership agreements. **Federal enclaves** (federal property) aren't covered by state law, so agreements there aren't prohibited.","ref":["Florida Contractors Manual  ·  5-14, 5-15"]},{"id":"3-15","exam":3,"num":15,"stem":"Which of the following is an example of an accrual entry?","options":["Depreciation and amortization entries","Entries to record payroll taxes","Entries to record automatic loan payments","Entries to record purchase of material stored at a jobsite"],"answer":3,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"237"}],"exp":"Per the Builder's Guide, **recording material purchased and stored at the jobsite** is an accrual entry.","ref":["Builder's Guide to Accounting  ·  237"]},{"id":"3-16","exam":3,"num":16,"stem":"To establish an hourly cost for a piece of equipment the contractor needs to consider all the following except __________.","options":["Estimated life of the equipment","Cost of the equipment, less salvage value","Replacement cost of the equipment","Estimated average hours of use"],"answer":2,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"159-160"}],"exp":"Hourly equipment cost uses estimated life, cost less salvage and average hours of use. **Replacement cost** isn't included.","ref":["Builder's Guide to Accounting  ·  159 - 160"],"dupes":["1-99"]},{"id":"3-17","exam":3,"num":17,"stem":"Failure of a certificate holder or registrant to apply for renewal of an active certificate at the time of biennial renewal shall cause the certificate to become __________.","options":["Suspended","Permanently suspended","Voluntarily inactive","Delinquent"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-95","stat":"489.116(4)"},{"book":"FCM","eds":["2021"],"loc":"2-74","stat":"489.116(4)"},{"book":"FCM","eds":["2017"],"loc":"2-84","stat":"489.116(4)"}],"exp":"§489.116(4): failing to renew an active certificate at biennial renewal makes it **delinquent**.","ref":["Florida Contractors Manual  ·  2025: 2-95: 489.116(4)","2021: 2-74: 489.116(4)","2017: 2-84: 489.116(4)"],"dupes":["1-100"]},{"id":"3-18","exam":3,"num":18,"stem":"Which of the following best describes the accrual method of accounting?","options":["Transactions are recorded when cash is received or paid","No receivables or payables are recorded on the balance sheet","Revenues are recognized when earned even though no cash has been received","Payables are recorded before receivables are received"],"answer":2,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"11"},{"book":"BGA","eds":null,"loc":"237"},{"book":"FCM","eds":null,"loc":"3-105"}],"exp":"Under the accrual method, **revenue is recognized when earned, even if no cash has been received** (and expenses when incurred).","ref":["Builder's Guide to Accounting  ·  11 or 237","Florida Contractors Manual  ·  3-105"]},{"id":"3-19","exam":3,"num":19,"stem":"Which of the following is not a depreciation method?","options":["Declining balance depreciation","Accumulated cost depreciation","Sum of the years' digits depreciation","Straight line depreciation"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"163"}],"exp":"Straight line, declining balance and sum-of-the-years' digits are real methods. **\"Accumulated cost depreciation\" doesn't exist**. (Accumulated *depreciation* is an account, not a method.)","ref":["Builder's Guide to Accounting  ·  163","Note: there is no such thing as accumulated cost depreciation","Sum-of-the-years depreciation is one of the methods still being used under the old rules"]},{"id":"3-20","exam":3,"num":20,"stem":"Claims arising from damages that resulted from a contractor's work that already has been finished would be covered by a __________.","options":["Completion bond","Completed operations liability policy","Builder's risk insurance policy","Manufacturer's and contractor's liability policy"],"answer":1,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-9"}],"exp":"**Completed operations** liability coverage handles claims for damage caused by work that's already finished.","ref":["Florida Contractors Manual  ·  4-9"]},{"id":"3-21","exam":3,"num":21,"stem":"What is the purpose of the Lien Law payment bond?","options":["To exempt the contractor from construction liens","To exempt the subcontractor from construction liens","To protect the owner's property from construction liens","To allow easy payments to subcontractors"],"answer":2,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-47"},{"book":"FCM","eds":["2025","2021"],"loc":"9-57"},{"book":"FCM","eds":["2017"],"loc":"9-46"},{"book":"FCM","eds":["2017"],"loc":"9-56"}],"exp":"§713.23: a lien law payment bond **protects the owner's property from construction liens**. Lienors claim against the bond instead of the property.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-47, 9-57","2017: 9-46, 9-56"]},{"id":"3-22","exam":3,"num":22,"stem":"Under the Civil Rights Act of 1964 (Title VII) the Americans with Disabilities Act and the Rehabilitation Act of 1973, the maximum compensatory and punitive damages a plaintiff may recover from an employer of 95 people is __________.","options":["$24,000","$50,000","$100,000","$250,000"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-35"}],"exp":"Combined compensatory and punitive damage caps under Title VII and the ADA: 15–100 employees **$50,000**; 101–200 $100,000; 201–500 $200,000; more than 500 $300,000. An employer of 95 falls in the first tier.","ref":["Florida Contractors Manual  ·  5-35"],"lock":1},{"id":"3-23","exam":3,"num":23,"stem":"A contractor's worker's compensation premiums can be reduced by any of the following, except ________________.","options":["Participating in a co-insurance program","Joining an insurance pool","Participating in a deductible program","Requiring the employee to pay part of the premium"],"answer":3,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"6-7"},{"book":"FCM","eds":null,"loc":"6-8"},{"book":"FCM","eds":null,"loc":"6-9"}],"exp":"**Making employees pay part of the workers' comp premium is illegal** in Florida. Co-insurance, pools and deductible programs are legitimate ways to lower premiums.","ref":["Florida Contractors Manual  ·  6-7, 6-8 & 6-9"]},{"id":"3-24","exam":3,"num":24,"stem":"Under the Florida Civil Rights Act of 1992, (Chapter 760, FL. Statue) back pay liability is limited to __________ months prior to filing of complaint unless willful violation is found.","options":["6","18","24","36"],"answer":2,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-36"}],"exp":"Under the Florida Civil Rights Act (Ch. 760), back pay is limited to **24 months (2 years)** before the complaint was filed, unless the violation was willful.","ref":["Florida Contractors Manual  ·  5-36"],"lock":1},{"id":"3-25","exam":3,"num":25,"stem":"An employer with 100 employees is cited by OSHA for a high severity, greater probability violation. The employer has had one other citation in the last 3 years. Using ONLY the information given, what would be the proposed penalty for this violation? (Select the closet answer)","options":["$5,000","$8,730","$10,795","$12,905"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"7-32"},{"book":"FCM","eds":["2025"],"loc":"7-33"},{"book":"FCM","eds":["2021"],"loc":"7-32","alt":"C"},{"book":"FCM","eds":["2021"],"loc":"7-33","alt":"C"},{"book":"FCM","eds":["2017"],"loc":"7-32","alt":"B"},{"book":"FCM","eds":["2017"],"loc":"7-33","alt":"B"}],"exp":"The answer depends on your manual's edition. **2025 FCM:** high severity, greater probability = $16,131 base; 51–100 employees = 20% reduction; no 10% history reduction (prior citation within 3 years). $16,131 × 0.80 = **$12,905**. 2021: $13,494 × 0.80 = $10,795. 2017: $12,471 × 0.70 = $8,730.","tip":"Base penalty × (1 − size reduction). The history reduction only applies with no citations in the last 3 years.","calc":1,"ref":["2025 Florida Contractors Manual:  ·  2025: 7-32 - 7-33 high severity, greater probability = base penalty of $16,131 adjustment factor = -20% for 51 to 100 workers","Note: there is no 10% reduction for good past history because there was one other violation in the last 3 years.","Solution: $16,131 x .80 (100% - 20%) = $12,904.80 proposed penalty","[C] 2021 Florida Contractors Manual:  ·  2021: 7-32 - 7-33 high severity, greater probability = base penalty of $13,494 adjustment factor = -20% for 51 to 100 workers","Note: there is no 10% reduction for good past history because there was one other violation in the last 3 years.","Solution: $13,494 x .80 (100% - 20%) = $10,795.20 proposed penalty","[B] 2017 Florida Contractors Manual:  ·  2017: 7-32 - 7-33 high severity, greater probability = base penalty of $12,471 adjustment factor = -30% for 26 to 100 workers","Note: there is no 10% reduction for good past history because there was one other violation in the last 3 years.","Solution: $12,471 x .70 (100% - 30%) = $8,729.70 proposed penalty"],"lock":1,"edAns":{"2025":3,"2021":2,"2017":1}},{"id":"3-26","exam":3,"num":26,"stem":"How long after the subcontractor's final furnishing of labor, services or material for a job does the subcontractor have to record a valid Claim of Lien?","options":["45 days","60 days","90 days","One year"],"answer":2,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-28"},{"book":"FCM","eds":["2017"],"loc":"9-27"}],"exp":"§713.08(5): a claim of lien must be recorded within **90 days after the final furnishing** of labor, services or materials.","tip":"NTO 45 days from first furnishing. Lien 90 days from last.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-28","2017: 9-27"]},{"id":"3-27","exam":3,"num":27,"stem":"The quarterly Federal Tax Form 941 summarizes tax liability for the employer and includes __________.","options":["Liability insurance","Federal income taxes withheld","Workers compensation insurance","Federal unemployment insurance tax"],"answer":1,"topic":"tax","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"137-138"},{"book":"FCM","eds":["2025","2021"],"loc":"1-26"},{"book":"FCM","eds":["2025","2021"],"loc":"3-48"},{"book":"FCM","eds":["2017"],"loc":"1-23"},{"book":"FCM","eds":["2017"],"loc":"3-48"}],"exp":"Form 941 includes **federal income tax withheld**, plus Social Security and Medicare.","ref":["Builder's Guide to Accounting  ·  137 - 138","Florida Contractors Manual  ·  2025 & 2021: 1-26, 3-48","2017: 1-23, 3-48"],"dupes":["1-101"]},{"id":"3-28","exam":3,"num":28,"stem":"A properly registered fictitious name is valid for __________ year(s).","options":["1","2","3","5"],"answer":3,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"1-14"},{"book":"FCM","eds":["2017"],"loc":"1-15"}],"exp":"A fictitious name is valid for **5 years**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 1-14","2017: 1- 15"],"lock":1},{"id":"3-29","exam":3,"num":29,"stem":"Which type of bond is a guarantee to the owner that the project will be completed according to the terms and conditions specified in the contract?","options":["Payment bond","Bid bond","Performance bond","Completion bond"],"answer":2,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-14"},{"book":"FCM","eds":null,"loc":"10-75"}],"exp":"A **performance bond** guarantees the owner that the project will be completed according to the contract. A payment bond guarantees subs and suppliers get paid. A bid bond guarantees the low bidder will sign.","ref":["Florida Contractors Manual  ·  4-14, 10-75"]},{"id":"3-30","exam":3,"num":30,"stem":"According to the Internal Revenue Service, employers must keep all employment tax records for at least how many years?","options":["2 years","4 years","5 years","7 years"],"answer":1,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"3-142"},{"book":"FCM","eds":["2021"],"loc":"3-160"},{"book":"FCM","eds":["2021"],"loc":"3-158"},{"book":"FCM","eds":["2017"],"loc":"3-154"}],"exp":"The IRS requires employment tax records to be kept at least **4 years**.","ref":["Florida Contractors Manual  ·  2025: 3-142 (2025 IRS Circ. E)","2021: 3-160 (2nd printing / 2021 IRS Circ. E)","2021: 3-158 (1st printing / 2016 IRS Circ. E)","2017: 3-154 (2016 IRS Circ. E)"],"lock":1},{"id":"3-31","exam":3,"num":31,"stem":"For purposes of unemployment compensation, misconduct connected with work does not include __________.","options":["Wrongful intent or evil design","Deliberate disregard of employee duties","Deliberate disregard of behavior standards","Isolated instances of negligence and poor judgment"],"answer":3,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-52"},{"book":"FCM","eds":["2025","2021"],"loc":"5-53"},{"book":"FCM","eds":["2017"],"loc":"5-52"}],"exp":"Unemployment law treats intentional wrongdoing and deliberate disregard of duties or standards as misconduct. **Isolated negligence or poor judgment is not misconduct**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-52, 5-53","2017: 5-52"]},{"id":"3-32","exam":3,"num":32,"stem":"Which of the following companies would be required to have Worker's Compensation Insurance?","options":["A company that is not in the construction business that leases 2 employees","A company in the construction business that hires employees","A corporation in the construction business with 2 employees who are both officers of the corporation and have certificates of election to be exempt","A corporation that is not in the construction business with 2 employees who are both officers of the corporation and have certificates of election to be exempt"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"6-5"}],"exp":"**A construction company with any employees** must carry workers' comp (1 or more employees). Corporate officers with valid exemptions don't count as employees.","ref":["Florida Contractors Manual  ·  6-5"]},{"id":"3-33","exam":3,"num":33,"stem":"A Notice to Owner from a non-privity lienor must be sent within __________ days after the first furnishing of labor or materials.","options":["30","45","72","90"],"answer":1,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"9-22"},{"book":"FCM","eds":["2017"],"loc":"9-21"}],"exp":"A non-privity lienor (a sub or supplier with no direct contract with the owner) must serve the Notice to Owner within **45 days** of first furnishing.","ref":["Florida Contractors Manual  ·  2025 & 2021: 9-22","2017: 9-21"],"lock":1},{"id":"3-34","exam":3,"num":34,"stem":"What financial information summarizes the existing conditions of a business?","options":["The balance sheet","The cash flow statement","The income statement","The statement of retained earnings"],"answer":0,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"247"}],"exp":"The **balance sheet** summarizes the existing condition of a business on a specific date.","ref":["Builder's Guide to Accounting  ·  247"],"dupes":["1-102"]},{"id":"3-35","exam":3,"num":35,"stem":"On a multi-contractor job which of the following is true regarding the posting of OSHA posters?","options":["Poster must be posted on all job site where employees can see them","Each contractor on the project must display their own posters","Only the contractor deemed project manage must post the posters","A & B above"],"answer":3,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-6"}],"exp":"On a multi-contractor job, posters must be where employees can see them, and **each contractor posts its own**. A and B are both true.","ref":["Florida Contractors Manual  ·  7-6"],"lock":1},{"id":"3-36","exam":3,"num":36,"stem":"When progress billings bring in more income than costs incurred during the early stages of a contract the contractor is using __________.","options":["A draw system","A pre-qualified payment method","Front end loading","The critical path method"],"answer":2,"topic":"job","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-108"},{"book":"FCM","eds":null,"loc":"10-74"},{"book":"FCM","eds":null,"loc":"10-75"}],"exp":"**Front-end loading** puts extra value in early pay items so early billings exceed costs incurred, which improves the contractor's early cash flow.","ref":["Florida Contractors Manual  ·  3-108, 10-74, 10-75"]},{"id":"3-37","exam":3,"num":37,"stem":"When preparing a bid, the contractor notes that the specifications require one type of equipment, but the plans show a different type. The contractor should __________.","options":["Bid based on using the least expensive of the two","Follow the plans","Submit a request for information","Substitute comparable equipment"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-6"}],"exp":"When the specifications and plans conflict, **submit a Request for Information (RFI)**. Don't guess, and don't substitute.","ref":["Florida Contractors Manual  ·  10-6"]},{"id":"3-38","exam":3,"num":38,"stem":"The OSHA citation must be prominently displayed at or near the place of alleged violation for __________ day (s), or until it is corrected, whichever is later, to warn employees of dangers that may exist there.","options":["One","Two","Three","Five"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-31"}],"exp":"An OSHA citation is posted at or near the violation for **3 working days or until the violation is corrected, whichever is later**.","ref":["Florida Contractors Manual  ·  7-31"]},{"id":"3-39","exam":3,"num":39,"stem":"A member, during active duty and for a period of __________ year (s) after discharge from active duty, engaged in his or her licensed profession or occupation in the private sector for profit in this state must complete all license renewal provisions except remitting the license renewal fee, which shall be waived by the department.","options":["1","2","3","4"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.02"}],"exp":"§455.02: during active duty and for **2 years** after discharge, a service member practicing a licensed profession in Florida completes the renewal requirements but has the renewal fee waived.","ref":["Florida Statute 455  ·  455.02"],"lock":1},{"id":"3-40","exam":3,"num":40,"stem":"What is required to file a construction claim of lien?","options":["Permission from the owner","A court order","A direct contract with the owner","The claim must be recorded with the clerk of the court"],"answer":3,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-80","stat":"713.08(5)"},{"book":"FCM","eds":["2021"],"loc":"9-76","stat":"713.08(5)"},{"book":"FCM","eds":["2017"],"loc":"9-84","stat":"713.08(5)"}],"exp":"A construction claim of lien must be **recorded with the clerk of the court** in the county where the property is located.","ref":["Florida Contractors Manual  ·  2025: 9-80: 713.08(5)","2021: 9-76: 713.08(5)","2017: 9-84: 713.08(5)"],"dupes":["1-105"]},{"id":"3-41","exam":3,"num":41,"stem":"What ratios compare accounts on the balance sheet to accounts on the income statement?","options":["Quick assets","Combined","Income","Current"],"answer":1,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"270"}],"exp":"**Combined ratios** compare balance sheet accounts with income statement accounts.","ref":["Builder's Guide to Accounting  ·  270"],"dupes":["1-106"]},{"id":"3-42","exam":3,"num":42,"stem":"Which is a requirement for an employee to recover under a compulsory State Workers' Compensation Statute?","options":["The injury must occur while the employee is engaged in interstate commerce","The injury must arise out of and in the course of employment","The injury must arise out of the negligence of the employer or fellow employee","The injured employee must be a permanent full-time employee"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"6-27"},{"book":"FCM","eds":["2021","2017"],"loc":"6-26"}],"exp":"To recover under workers' comp, the injury must **arise out of and in the course of employment**. It's no-fault, so the employer's negligence doesn't matter.","ref":["Florida Contractors Manual  ·  2025: 6-27","2021 & 2017:6-26"]},{"id":"3-43","exam":3,"num":43,"stem":"What type of cost basis inventory valuation method uses the current market value of material as used?","options":["Specific cost","First in-first out","Last in-first out","Cost-plus inflation"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"120"}],"exp":"**LIFO** charges the latest costs, close to current market value, to material as it is used.","ref":["Builder's Guide to Accounting  ·  120"],"dupes":["1-108"]},{"id":"3-44","exam":3,"num":44,"stem":"Which is not used when calculating goods sold to average inventory ratio?","options":["Labor","Materials purchased","All other direct costs","Total monthly averages"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"121"}],"exp":"**\"Total monthly averages\"** isn't used in the goods sold to average inventory ratio. COGS includes labor, materials and other direct costs.","ref":["Builder's Guide to Accounting  ·  121"],"dupes":["1-109"]},{"id":"3-45","exam":3,"num":45,"stem":"The Drug-Free Workplace Act of 1988 __________.","options":["Does not require drug testing","Always applies to subcontractors","Applies to contractors in foreign countries","Applies only to contractors with more than 50 workers"],"answer":0,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"5-50"},{"book":"FCM","eds":["2017"],"loc":"5-49"}],"exp":"The Drug-Free Workplace Act of 1988 requires covered federal contractors and grantees to keep a drug-free workplace policy, but it **does not require drug testing**.","ref":["Florida Contractors Manual  ·  2025 & 2021: 5-50","2017: 5-49"]},{"id":"3-46","exam":3,"num":46,"stem":"Which of the following can be added to a Builder's Risk policy by means of an extended coverage endorsement?","options":["Vandalism coverage","Malpractice coverage","Materials in transit","Catastrophic flood coverage"],"answer":2,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-7"}],"exp":"An extended coverage endorsement on a builder's risk policy can add **materials in transit** (and storage away from the site).","ref":["Florida Contractors Manual  ·  4-7"]},{"id":"3-47","exam":3,"num":47,"stem":"Which bond requires a low bidding contractor who fails to enter into a contract to pay a penalty equal to the amount of the bid?","options":["Performance bond","Forfeiture obligation","Difference in bid","Payment"],"answer":1,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"4-13"}],"exp":"A bid bond can be written as a **forfeiture obligation**: if the low bidder won't sign, the full penal amount is forfeited. The other form, \"difference in bid,\" pays only the gap to the next bidder.","ref":["Florida Contractors Manual  ·  4-13"]},{"id":"3-48","exam":3,"num":48,"stem":"The Statute of limitations requires that an action for breach of an unwritten contract must be brought within a maximum of __________ years.","options":["2","4","5","7"],"answer":1,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"8-23"}],"exp":"Florida statute of limitations: **4 years** for an unwritten (oral) contract and 5 years for a written contract.","tip":"Oral = 4, written = 5.","ref":["Florida Contractors Manual  ·  8-23"],"lock":1},{"id":"3-49","exam":3,"num":49,"stem":"Which of the following wages would not be subject to Federal Unemployment tax paid by the employer?","options":["Wages paid to a Canadian who frequently enters the U.S. to work as a carpenter","Severance pay","Wages paid to a deceased worker's estate in the same calendar year as the date of the worker's death","Wages paid to the employer's spouse"],"answer":3,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-253"},{"book":"FCM","eds":["2025"],"loc":"5-266"},{"book":"FCM","eds":["2025"],"loc":"3-181"},{"book":"FCM","eds":["2021"],"loc":"5-277"},{"book":"FCM","eds":["2021"],"loc":"5-289"},{"book":"FCM","eds":["2021"],"loc":"5-290"},{"book":"FCM","eds":["2021"],"loc":"3-193"},{"book":"FCM","eds":["2021"],"loc":"3-188"},{"book":"FCM","eds":["2017"],"loc":"5-292"},{"book":"FCM","eds":["2017"],"loc":"3-184"}],"exp":"FUTA doesn't apply to family employment such as **wages paid to the employer's spouse** (by a sole proprietor). Severance pay and wages to foreign workers in the U.S. are generally subject to it.","ref":["Florida Contractors Manual  ·  2025: 5-253, 5-266, 3-181: (2025 IRS Circ. E)","2021: 5-277, 5-289, 5-290, 3-193 (2nd printing /","2021 IRS Circ. E)","2021: 5-277, 5-289, 5-290, 3-188 (1st printing /","2016 IRS Circ. E)","2017: 5-292, 3-184 (2016 IRS Circ. E)"]},{"id":"3-50","exam":3,"num":50,"stem":"How may a contractor required to carry Worker's Compensation insurance fulfill the law?","options":["Obtaining liability insurance at three times the coverage generally required","Seek individual self-insured status through the Department of Labor and Employment Security","Obtaining major medical insurance for all employees","Obtaining life insurance policies for all employees"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"6-9"}],"exp":"An employer can meet the workers' comp requirement by buying a policy or by **qualifying as an individual self-insurer** (approved by the state). Liability, health or life insurance doesn't count.","ref":["Florida Contractors Manual  ·  6-9"]},{"id":"3-51","exam":3,"num":51,"stem":"Under a contract which does NOT require written notice in order to file a claim for additional cost?","options":["Minor change in the work","Work performed because of a concealed condition","Damages caused by the architect","Work performed because of an emergency endangering the owner's property"],"answer":3,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"15.1.5"}],"exp":"A201 §15.1.5 and §10.4: work done because of an **emergency endangering the owner's property** doesn't require written notice before claiming additional cost.","ref":["AIA Document A201, 2017  ·  15.1.5"],"dupes":["1-110"]},{"id":"3-52","exam":3,"num":52,"stem":"A board member or former board member serving on a probable cause panel shall be compensated __________ for each day in attendance at an official meeting of the board and for each day of participation in any other business involving the board.","options":["$25","$50","$75","$100"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.207(4)"}],"exp":"§455.207(4): board members serving on a probable cause panel are paid **$50 a day** for each day of meetings or board business.","ref":["Florida Statute 455  ·  455.207(4)"],"lock":1},{"id":"3-53","exam":3,"num":53,"stem":"When is an oral contract valid?","options":["When an unlicensed contractor agrees to perform construction services","When the contract can be performed in less than one year","When the Statute of Limitations has expired","When the sale of goods is more than $500"],"answer":1,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"8-6"}],"exp":"Under the Statute of Frauds, contracts that **can be performed within one year** may be oral. Contracts that can't be performed within a year, and sales of goods of $500 or more, must be written.","ref":["Florida Contractors Manual  ·  8-6"]},{"id":"3-54","exam":3,"num":54,"stem":"Current liabilities include the portion of long-term debt for equipment purchases payable within __________ days.","options":["30","90","180","365"],"answer":3,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"155"}],"exp":"Current liabilities include the portion of long-term equipment debt due **within 365 days**.","ref":["Builder's Guide to Accounting  ·  155"],"lock":1,"dupes":["1-112"]},{"id":"3-55","exam":3,"num":55,"stem":"What activity must precede project scheduling?","options":["Development of a logic table","Final project design","Project planning","Shop drawings"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-58"}],"exp":"**Project planning** comes before scheduling. You decide *what* and *how* first, then *when*.","ref":["Florida Contractors Manual  ·  10-58"]},{"id":"3-56","exam":3,"num":56,"stem":"In reference to 42 U.S.C, the initials ADA are used to indicate __________.","options":["American Drug Association","American Diabetes Association","Association of Disabled Americans","Americans with Disabilities Act"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-12"},{"book":"FCM","eds":null,"loc":"5-41"}],"exp":"42 U.S.C. §12101 et seq. is the **Americans with Disabilities Act** (ADA).","ref":["Florida Contractors Manual  ·  5-12, 5-41"]},{"id":"3-57","exam":3,"num":57,"stem":"Chapter 489 of the Florida Statutes deals with licensing and regulating __________.","options":["All contractors and property owners","Bridge, tank and tower structures","Commercial buildings and bridges","Construction contracting, electrical and alarm systems contracting, and septic tank contracting"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"2-5"}],"exp":"Chapter 489 has three parts: **construction contracting (Part I), electrical and alarm system contracting (Part II), and septic tank contracting (Part III)**.","ref":["Florida Contractors Manual  ·  2-5"]},{"id":"3-58","exam":3,"num":58,"stem":"To procure long lead items, it is recommended that the items be __________.","options":["Identified and ordered early","Ordered when funds are available","Identified and ordered when needed","Ordered according to product availability"],"answer":0,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-24"}],"exp":"Long-lead items should be **identified and ordered early** so they don't hold up the schedule.","ref":["Florida Contractors Manual  ·  10-24"]},{"id":"3-59","exam":3,"num":59,"stem":"What does Sales less the Cost of Goods Sold equal?","options":["Gross profit","Net profit","Income from operations","Net sales"],"answer":0,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"248"},{"book":"FCM","eds":null,"loc":"3-108"}],"exp":"Sales − cost of goods sold = **gross profit**.","ref":["Builder's Guide to Accounting  ·  248","Florida Contractors Manual  ·  3-108"]},{"id":"3-60","exam":3,"num":60,"stem":"What is the sum of assets minus liabilities?","options":["Net profit","Net worth","Gross sales","Gross profit"],"answer":1,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"247"}],"exp":"Assets − liabilities = **net worth**.","ref":["Builder's Guide to Accounting  ·  247"]},{"id":"3-61","exam":3,"num":61,"stem":"The department is authorized to impose a fine of not more than __________ and assess reasonable investigative and legal costs for prosecution when it appears that any uncertified or unregistered person is associated with a contracting firm.","options":["$500","$1,500","$2,500","$5,000"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-114","stat":"489.132(3)"},{"book":"FCM","eds":["2021"],"loc":"2-88","stat":"489.132(3)"},{"book":"FCM","eds":["2017"],"loc":"2-101","stat":"489.132(3)"}],"exp":"§489.132(3): DBPR may fine up to **$5,000**, plus investigative and legal costs, when an uncertified or unregistered person is associated with a contracting firm.","ref":["Florida Contractors Manual  ·  2025: 2-114: 489.132(3)","2021: 2-88: 489.132(3)","2017: 2-101: 489.132(3)"],"lock":1},{"id":"3-62","exam":3,"num":62,"stem":"All employers are required to report accidents to the Area Office resulting in one or more fatalities within __________ hours of learning of the incident.","options":["8","14","24","30"],"answer":0,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-28"}],"exp":"Report a work-related **fatality** to OSHA within **8 hours**. Report an inpatient hospitalization, amputation or loss of an eye within 24 hours.","tip":"Death = 8 hours. Hospitalization, amputation or eye = 24 hours.","ref":["Florida Contractors Manual  ·  7-28"],"lock":1},{"id":"3-63","exam":3,"num":63,"stem":"All the following would be considered variable overhead expenses except __________.","options":["Payroll taxes on office salaries","Field office trailer rental","Worker's compensation insurance","Bad debts"],"answer":0,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"142-143"}],"exp":"**Payroll taxes on office salaries** are a fixed expense. Field office trailer rental, workers' comp and bad debts vary with work volume.","ref":["Builder's Guide to Accounting  ·  142 - 143","Payroll taxes on office salaries is a fixed expense"]},{"id":"3-64","exam":3,"num":64,"stem":"When the contract is made with a husband or wife who is not separated and living apart and the property is owned by the other or of both, the spouse who contracts shall be deemed to be the agent of the other unless such other shall, with __________ days after learning of such contract, give the contractor and record in the clerk's office, notice of his or her objection.","options":["5","7","10","14"],"answer":2,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-77","stat":"713.12"},{"book":"FCM","eds":["2021"],"loc":"9-77","stat":"713.12"},{"book":"FCM","eds":["2017"],"loc":"9-87","stat":"713.12"}],"exp":"§713.12: when one spouse contracts for work on property owned by the other or by both, the contracting spouse is the other's agent unless the other spouse **records an objection within 10 days** of learning of the contract.","ref":["Florida Contractors Manual  ·  2025: 9-77: 713.12","2021: 9-77: 713.12","2017: 9-87: 713.12"],"lock":1},{"id":"3-65","exam":3,"num":65,"stem":"OSHA regulations require that records be kept a minimum of how many years after an incident occurs?","options":["1 year from the end of the year in which the incident occurred","5 years from the end of the year in which the incident occurred","7 years from the end of the year in which the incident occurred","Indefinitely"],"answer":1,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-16"}],"exp":"OSHA injury and illness records are kept **5 years** after the end of the year the incident occurred.","ref":["Florida Contractors Manual  ·  7-16"]},{"id":"3-66","exam":3,"num":66,"stem":"Successful builders control their costs BEST at which time?","options":["At the end of each week","During each phase of the work","Immediately prior to approving invoices","In bi-weekly meetings with the owner present"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"189"}],"exp":"Costs are controlled best **during each phase of the work**, while there's still time to fix overruns.","ref":["Builder's Guide to Accounting  ·  189"]},{"id":"3-67","exam":3,"num":67,"stem":"A company's initial record of all its business transactions is known as a __________.","options":["Ledger","Journal","Balance sheet","Financial statement"],"answer":1,"topic":"acct","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-25"},{"book":"FCM","eds":null,"loc":"3-108"}],"exp":"The **journal** is the book of original entry: every transaction is recorded there first, then posted to the ledger.","tip":"Journal first, then ledger.","ref":["Florida Contractors Manual  ·  3-25, 3-108"]},{"id":"3-68","exam":3,"num":68,"stem":"An indicator of how well a company can meet its current obligations is the company's __________.","options":["Expense ratio","Debt to capitalization ratio","Current ratio","Income to net worth ratio"],"answer":2,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"269"}],"exp":"The **current ratio** shows how well a company can meet its current obligations.","ref":["Builder's Guide to Accounting  ·  269"]},{"id":"3-69","exam":3,"num":69,"stem":"Which of the following is not in accordance with requirements for an executive being granted an exemption from the Fair Labor Standards Act?","options":["Person whose primary duty if to manage a company subdivision","The person regularly directs 3 to 4 employees","The person receives a salary of $150 or more per week","The person regularly exercises discretionary power"],"answer":2,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-15"}],"exp":"**$150 a week** isn't the salary test for the executive exemption (the current federal standard is $684 a week). Managing a subdivision, directing 2 or more employees and using discretion are all real requirements.","ref":["Florida Contractors Manual  ·  5-15"]},{"id":"3-70","exam":3,"num":70,"stem":"Which of the following production factors would not be considered by the estimator when calculating equipment cost estimates?","options":["Climate","Experience of the operators","Highway or street speed limits","Original purchase price of the equipment"],"answer":3,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-27"}],"exp":"Production factors are climate, operator experience and speed limits. The **original purchase price** is a cost factor, not a production factor.","ref":["Florida Contractors Manual  ·  10-27"]},{"id":"3-71","exam":3,"num":71,"stem":"Master activities are a group of activities with no activity representing more than __________ of the project.","options":["10%","20%","25%","30%"],"answer":0,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-58"}],"exp":"In a schedule, master activities are grouped so that no single activity is more than **10%** of the project.","ref":["Florida Contractors Manual  ·  10-58"],"lock":1},{"id":"3-72","exam":3,"num":72,"stem":"Requests for translated examinations, except for those in Spanish, must be on file in the board office, or with the department when there is no board, at least __________ days (months) prior to the scheduled examination.","options":["6","14","21","45"],"answer":0,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.217(6)"}],"exp":"§455.217(6): requests for a translated exam (in a language other than Spanish) must be on file at least **6 months** before the exam. The question's \"days (months)\" means months.","ref":["Florida Statute 455  ·  455.217(6)"],"lock":1},{"id":"3-73","exam":3,"num":73,"stem":"The Florida Civil Rights Act of 1992, (Chapter 760, FL. Stat.), does not protect against discrimination for which of the following?","options":["Age","Religion","Alcoholism","Drug abuse"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-36"}],"exp":"The Florida Civil Rights Act protects age, religion and handicap (alcoholism can count as a handicap). **Current illegal drug abuse is not protected**.","ref":["Florida Contractors Manual  ·  5-36"]},{"id":"3-74","exam":3,"num":74,"stem":"When preparing financial statements, accruals are used to record __________.","options":["Lump sum payments","Income earned but not yet received","Cash transactions","Prepayments on a future contract"],"answer":1,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"106-107"},{"book":"FCM","eds":null,"loc":"3-105"}],"exp":"Accruals record **income earned but not yet received**: revenue when earned, expenses when incurred.","ref":["Builder's Guide to Accounting  ·  106 - 107","Under the accrual method of accounting, revenue is considered earned when services are rendered, and expenses are incurred when services are received.","Florida Contractors Manual  ·  3-105"],"dupes":["1-119"]},{"id":"3-75","exam":3,"num":75,"stem":"In order to comply with FDEP asbestos regulations, when demolishing commercial, industrial, publicly owned building, or residential structures with more than four dwelling units, notification must be sent to FDEP at least how many working days prior to beginning the demolition?","options":["7","10","14","20"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-97"}],"exp":"FDEP asbestos rule: notify at least **10 working days** before demolishing commercial, industrial or public buildings, or residential buildings with more than 4 units.","ref":["Florida Contractors Manual  ·  10-97"],"lock":1},{"id":"3-76","exam":3,"num":76,"stem":"According to Florida Unemployment Compensation Employer Handbook, tax rates are referred to as __________ ratings.","options":["Cost","Experience","Records","Required"],"answer":1,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-271"},{"book":"FCM","eds":["2021"],"loc":"5-293"},{"book":"FCM","eds":["2017"],"loc":"5-296"}],"exp":"Florida reemployment tax rates are **experience ratings**. Employers with fewer claims charged pay lower rates.","ref":["Florida Contractors Manual  ·  2025: 5-271","2021: 5-293","2017: 5-296"]},{"id":"3-77","exam":3,"num":77,"stem":"On which of the following items must Florida sales tax be paid by a prime contractor, if it is not included on the invoice?","options":["Invoice from a concrete supplier","Invoice from a temporary help agency","Invoice from a block mason for labor only","Invoice from a non-exempt subcontractor"],"answer":0,"topic":"tax","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-63"},{"book":"FCM","eds":null,"loc":"3-64"}],"exp":"Florida sales tax applies to **materials** (tangible goods), so the **concrete supplier's invoice** is taxable. Labor-only services and temporary help aren't. Labor is taxed only when an item is fabricated in a shop and sold.","ref":["Florida Contractors Manual  ·  3-63, 3-64","Answers B, C, & D are wrong because sales tax is only charged on materials. The only time that sales tax is computed on labor and material both is when the product is fabricated in a shop, such as a sheet metal shop, and then sold to the public."]},{"id":"3-78","exam":3,"num":78,"stem":"According to Florida Unemployment Compensation Employer Handbook, an unemployed worker __________.","options":["Cannot qualify for benefits","Qualifies for benefits only if paid minimum wage","Qualifies for benefits if employed for one quarter of the base period","Qualifies for benefits if employed for two quarters"],"answer":3,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-279"},{"book":"FCM","eds":["2021"],"loc":"5-299"},{"book":"FCM","eds":["2017"],"loc":"5-301"}],"exp":"An unemployed worker qualifies only if they were **paid wages in 2 or more quarters of the base period**.","ref":["Florida Contractors Manual  ·  2025: 5-279","2021: 5-299","2017: 5-301","Qualifies for benefits if he/she has been paid wages in 2 or more quarters in the base period.","1 quarter = 3 months, therefore 2 quarters = 6 months."]},{"id":"3-79","exam":3,"num":79,"stem":"The Civil Rights Act of 1866 applies __________.","options":["Only to public employees","Only to employees of the Federal Government","Only to minority employees","To all employees"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-37"}],"exp":"The Civil Rights Act of 1866 (42 U.S.C. §1981) applies to **all employers and all employees**, with no minimum employee count.","ref":["Florida Contractors Manual  ·  5-37"]},{"id":"3-80","exam":3,"num":80,"stem":"With respect to an applicant for a certificate, the initial application fee may not exceed __________.","options":["$100","$125","$135","$150"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-85","stat":"489.109(1)(a)"},{"book":"FCM","eds":["2021"],"loc":"2-67","stat":"489.109(1)(a)"},{"book":"FCM","eds":["2017"],"loc":"2-75","stat":"489.109(1)(a)"}],"exp":"§489.109(1)(a): the initial application fee for a certificate may not exceed **$150**.","ref":["Florida Contractors Manual  ·  2025: 2-85: 489.109(1)(a)","2021: 2-67: 489.109(1)(a)","2017: 2-75: 489.109(1)(a)"],"lock":1},{"id":"3-81","exam":3,"num":81,"stem":"Which jobs would not require use of the percentage of completion method?","options":["Jobs longer than two years in duration","Jobs by firms that require periodic, progressive recognition of profit from their jobs","Construction jobs producing annual revenue greater than $10 million","Jobs costing $1,000 - $5,000 which take approximately one week to complete"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"25"}],"exp":"Short, small jobs (**$1,000–$5,000, about a week**) don't need the percentage of completion method.","ref":["Builder's Guide to Accounting  ·  25"]},{"id":"3-82","exam":3,"num":82,"stem":"After a licensee's completion of a continuing education course, the information must be submitted to the department electronically no later than __________ calendar days.","options":["7","14","30","45"],"answer":2,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.2178(1)"}],"exp":"§455.2178(1): CE providers must submit course completions to DBPR electronically within **30 days**.","ref":["Florida Statute 455  ·  455.2178(1)"],"lock":1},{"id":"3-83","exam":3,"num":83,"stem":"All the following are procedures included in the budget process except __________.","options":["Analyzing the results","Consulting with your accountant","Preparing the budget","Acting to control expenses"],"answer":1,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"144"}],"exp":"The budget process is prepare, analyze results and act to control expenses. **Consulting your accountant** isn't a step.","ref":["Builder's Guide to Accounting  ·  144"],"dupes":["1-123"]},{"id":"3-84","exam":3,"num":84,"stem":"According to the Veteran's Re-employment Laws, military leave of absence must be granted to any permanent full time or permanent part-time employee who enlists or is drafted into active duty in the armed forces. Discharging an employee without cause, who has been rehired and is covered under the law, is prohibited for a period of __________ if the employee's military service period was less than 180 days and more than 30 days.","options":["6 months","1 year","1 year and 6 months","2 years"],"answer":1,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-45"}],"exp":"Per the manual's text on veterans' reemployment law (FCM 5-45), the answer is **1 year**. Note that current federal USERRA law protects a rehired employee who served 31 to 180 days for **180 days**, and one who served more than 180 days for 1 year. The exam is built on the manual, so answer from the book and double-check the wording on FCM 5-45.","ref":["Florida Contractors Manual  ·  5-45"]},{"id":"3-85","exam":3,"num":85,"stem":"When figuring overhead, which is a fixed expense?","options":["Small tools","Operating supplies","Equipment rental","Advertising"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"142"}],"exp":"Per the Builder's Guide, **advertising** is treated as a fixed overhead expense. Small tools, operating supplies and equipment rental vary with work volume.","ref":["Builder's Guide to Accounting  ·  142"]},{"id":"3-86","exam":3,"num":86,"stem":"The best way to control equipment costs is good __________.","options":["Maintenance","Scheduling","Financing","Reports"],"answer":1,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"228"}],"exp":"Good **scheduling** is the best way to control equipment costs.","ref":["Builder's Guide to Accounting  ·  228"],"dupes":["1-124"]},{"id":"3-87","exam":3,"num":87,"stem":"In order to establish an hourly cost for a bulldozer for job allocations, which of the following would NOT apply?","options":["Cost of equipment less salvage value","Operating costs involving gas, oil, and accessories","Repairing and maintenance costs","Unpredictable job site conditions"],"answer":3,"topic":"dep","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"159"},{"book":"BGA","eds":null,"loc":"160"}],"exp":"**Unpredictable job site conditions** can't be built into an hourly equipment rate.","ref":["Builder's Guide to Accounting  ·  159, 160"],"dupes":["1-125"]},{"id":"3-88","exam":3,"num":88,"stem":"Adjustment of the contract sum using a change order must be established based on __________.","options":["An agreement between the owner, contractor and architect","The unit prices as stated in the contract documents","Labor, material and equipment costs","The architect's recommendation"],"answer":0,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"7.2.1"}],"exp":"A201 §7.2.1: a change order's adjustment to the contract sum is set by **agreement among the Owner, Contractor and Architect**.","ref":["AIA Document A201, 2017  ·  7.2.1"]},{"id":"3-89","exam":3,"num":89,"stem":"When preparing a financial statement for a lender before applying for a loan, it is best to __________.","options":["Accumulate current assets to improve the cash position","Reduce current liabilities","Try to decrease the current ratio","Try to increase the volume of business"],"answer":1,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"174"}],"exp":"Before applying for a loan, **reduce current liabilities** to improve your current ratio and how strong your balance sheet looks.","ref":["Builder's Guide to Accounting  ·  174"]},{"id":"3-90","exam":3,"num":90,"stem":"Your contractor's license number must appear in or on all the following advertisements except __________.","options":["Free yellow Page listings","Coupons","Business proposals","Business cards"],"answer":0,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-165","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2021"],"loc":"2-124","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2017"],"loc":"2-149","stat":"61G4-12.011(3)"}],"exp":"61G4-12.011(3): the license number must appear in advertising, but **free Yellow Pages listings** (free directory listings) are exempt.","ref":["Florida Contractors Manual  ·  2025: 2-165: 61G4-12.011(3)","2021: 2-124: 61G4-12.011(3)","2017: 2-149: 61G4-12.011(3)"]},{"id":"3-91","exam":3,"num":91,"stem":"Every certified and registered contractor must complete a minimum of __________ hours of continuing education during every two-year license cycle.","options":["3","7","14","16"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025","2021"],"loc":"2-17"},{"book":"FCM","eds":["2017"],"loc":"2-19"}],"exp":"Contractors need **14 hours** of CE every 2-year cycle.","ref":["Florida Contractors Manual  ·  2025 & 2021: 2-17","2017: 2-19"],"lock":1},{"id":"3-92","exam":3,"num":92,"stem":"All current liabilities include equipment that is payable within __________ days.","options":["30","90","180","365"],"answer":3,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"253"},{"book":"FCM","eds":null,"loc":"3-107"}],"exp":"Current liabilities = payable within **365 days**.","ref":["Builder's Guide to Accounting  ·  253","Florida Contractors Manual  ·  3-107"],"lock":1},{"id":"3-93","exam":3,"num":93,"stem":"Which item below is not a fixed asset?","options":["Inventory","Land","Equipment","Trucks"],"answer":0,"topic":"acct","books":["BGA","FCM"],"cites":[{"book":"BGA","eds":null,"loc":"252"},{"book":"BGA","eds":null,"loc":"327"},{"book":"FCM","eds":null,"loc":"3-108"}],"exp":"**Inventory** is a current asset. Land, equipment and trucks are fixed (long-term) assets.","ref":["Builder's Guide to Accounting  ·  252 or 327","Florida Contractors Manual  ·  3-108 (Long-Term Assets) Fixed assets are also referred to as long-term assets."]},{"id":"3-94","exam":3,"num":94,"stem":"According to Florida Unemployment Compensation Employer Handbook, Cafeteria Payment plans are exempt if they are __________.","options":["For Federal employees","Not Federally subsidized","Not reported to the Internal Revenue Service","Reported to the Internal Revenue Service"],"answer":2,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"5-266"},{"book":"FCM","eds":["2021"],"loc":"5-290"},{"book":"FCM","eds":["2017"],"loc":"5-292"}],"exp":"Per the Reemployment Tax handbook, cafeteria plan payments are exempt from reemployment tax if they're **not reported to the IRS** as wages.","ref":["Florida Contractors Manual  ·  2025: 5-266","2021: 5-290","2017: 5-292"]},{"id":"3-95","exam":3,"num":95,"stem":"When using the inventory ratio method, a high ratio indicates __________.","options":["Average inventory","High inventory","High market average","Low inventory"],"answer":3,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"121"}],"exp":"A high inventory turnover ratio means **low inventory**.","ref":["Builder's Guide to Accounting  ·  121"]},{"id":"3-96","exam":3,"num":96,"stem":"An equipment schedule shows that 60 dump trucks will be required in September and 15 dump trucks during October and November. You have 30 dump trucks available. You should attempt to __________.","options":["Simply let the contract extend over the required completion time","Buy 30 new dump trucks","Revise the project schedule to distribute the dump trucks evenly over the months so that 30 dump trucks are required","Work 30 trucks overtime during September using a second or third shift"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-27"}],"exp":"Total truck-months needed = 60 + 15 + 15 = 90. Spread over 3 months, that's 30 a month, exactly the 30 trucks you have. **Revise the schedule to level the demand to 30 trucks**.","calc":1,"ref":["Florida Contractors Manual  ·  10-27","30 (Sept.) + 15 (Oct.) + 15 (Nov.) = 60/3 months = 30 trucks per month"]},{"id":"3-97","exam":3,"num":97,"stem":"An employee discloses an employer's violations of law, which may pose a danger to public, health, safety, or welfare. The employee is protected from retaliation by the __________.","options":["Employees Legal Defense Fund","Federal Employees Act","Graham Employees Act","Public Whistle-blowers Act"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-45"}],"exp":"Florida's **Whistle-blower's Act** protects employees who disclose violations of law that endanger public health, safety or welfare from retaliation.","ref":["Florida Contractors Manual  ·  5-45"]},{"id":"3-98","exam":3,"num":98,"stem":"The Florida Aids Statute (FS 760.50) prohibits AIDS/HIV discrimination, and provides that persons with AIDS, ARC or HIV have the same protection as other disabled persons. This law applies to __________.","options":["All employers","Employers with 2 or more employees","Employers with 6 or more employees","Employers with 15 or more employees"],"answer":0,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-44"}],"exp":"FS 760.50, Florida's AIDS/HIV discrimination law, applies to **all employers**, regardless of size.","ref":["Florida Contractors Manual  ·  5-44"]},{"id":"3-99","exam":3,"num":99,"stem":"Which activity is a construction job, as that term is used in the Worker's Compensation Statute?","options":["Roof replacement","A homeowner's building their own premises","Well drilling on land containing existing structures","Manufacturing of materials used in construction work"],"answer":0,"topic":"wc","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"6-6"}],"exp":"**Roof replacement** is construction work for workers' comp purposes. Homeowners building their own homes, manufacturing materials, and well drilling on land with existing structures are excluded.","ref":["Florida Contractors Manual  ·  6-6"]},{"id":"3-100","exam":3,"num":100,"stem":"If an owner makes payment to a contractor, without requiring waiver or release by a lienor who has filed a Notice to Owner, the payments are considered __________ payments.","options":["Improper","Refused","Unrecoverable","Non-essential"],"answer":0,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-75","stat":"713.06(2)(a)(c)"},{"book":"FCM","eds":["2021"],"loc":"9-72","stat":"713.06(2)(a)(c)"},{"book":"FCM","eds":["2017"],"loc":"9-76","stat":"713.06(2)(a)(c)"}],"exp":"§713.06: payments to the contractor without getting lien releases from lienors who served a Notice to Owner are **improper payments**. The owner may have to pay twice.","ref":["Florida Contractors Manual  ·  2025: 9-75: 713.06(2)(a)(c)","2021: 9-72: 713.06(2)(a)(c)","2017: 9-76: 713.06(2)(a)(c)"]},{"id":"3-101","exam":3,"num":101,"stem":"Given: A pick-up truck was originally purchased for $16,900.00. The accumulated depreciation of the pick-up truck shown on the books to date is $4,200.00. The pick-up truck was sold for $11,500.00. The resulting loss (or profit) from the sales of the pick-up truck that will be shown on the books is a __________.","options":["Loss of $1,200.00","Loss of $5,400.00","Profit of $5,600.00","Profit of $12,700.00"],"answer":0,"topic":"dep","books":["FCM","BGA"],"cites":[{"book":"FCM","eds":null,"loc":"3-34"},{"book":"BGA","eds":null,"loc":"162"}],"exp":"Book value = cost − accumulated depreciation = $16,900 − $4,200 = $12,700. Sold for $11,500, which is less than book value: **loss of $1,200**.","tip":"Sale price minus book value: positive is a gain, negative is a loss.","calc":1,"ref":["Florida Contractors Manual  ·  3-34","Builder's Guide to Accounting  ·  162"]},{"id":"3-102","exam":3,"num":102,"stem":"Any certified contractor who allows his/her certificate to be used by an uncertified person with the intent to evade the provisions of this law may be fined a maximum of __________.","options":["$1,000.00","$5,000.00","$7,500.00","$10,000.00"],"answer":3,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-202"},{"book":"FCM","eds":["2021"],"loc":"2-158"},{"book":"FCM","eds":["2017"],"loc":"2-184"}],"exp":"Letting an uncertified person use your certificate to evade the law can bring the maximum administrative fine of **$10,000**.","ref":["Florida Contractors Manual  ·  2025: 2-202","2021: 2-158","2017: 2-184"],"lock":1},{"id":"3-103","exam":3,"num":103,"stem":"If a corporation meets all the requirements specified by the Internal Revenue Service and elect to be taxed as a partnership rather than a corporation, the company is referred to as a (an) __________.","options":["Limited partnership","Employee stock Ownership Corporation","S Corporation","Joint Venture"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-11"},{"book":"FCM","eds":["2021"],"loc":"1-11"},{"book":"FCM","eds":["2021"],"loc":"1-12"},{"book":"FCM","eds":["2017"],"loc":"1-13"}],"exp":"A corporation that meets IRS requirements and elects to be taxed like a partnership (pass-through) is an **S Corporation**.","ref":["Florida Contractors Manual  ·  2025: 1-11","2021: 1-11, 1-12","2017: 1-13"]},{"id":"3-104","exam":3,"num":104,"stem":"According to the Florida Construction Industry Licensing Law, each certified contractor shall display in all advertising medium used by the contractor his/her __________ number.","options":["Employer Identification","Insurance Policy","Certification","State Sales Tax"],"answer":2,"topic":"lic","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"2-31","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2025"],"loc":"2-165","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2021"],"loc":"2-29","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2021"],"loc":"2-124","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2017"],"loc":"2-22","stat":"61G4-12.011(3)"},{"book":"FCM","eds":["2017"],"loc":"2-149","stat":"61G4-12.011(3)"}],"exp":"61G4-12.011: every certified contractor's advertising must show the **certificate (or registration) number**.","ref":["Florida Contractors Manual  ·  2025: 2-31, 2-165: 61G4-12.011(3)","2021: 2-29, 2-124: 61G4-12.011(3)","2017: 2-22, 2-149: 61G4-12.011(3)"]},{"id":"3-105","exam":3,"num":105,"stem":"Service of a Notice to Owner or a preliminary Notice to Contractor is effective as of the date of mail if the Notice is mailed within __________ days after the date the lienor first furnishes labor, services, or materials.","options":["10","20","30","40"],"answer":3,"topic":"lien","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"9-92","stat":"713.18(2)(b)"},{"book":"FCM","eds":["2021"],"loc":"9-84","stat":"713.18(2)(b)"},{"book":"FCM","eds":["2017"],"loc":"9-101","stat":"713.18(2)(b)"}],"exp":"§713.18: a Notice to Owner or preliminary notice to contractor is effective on the mailing date if mailed within **40 days** of first furnishing. It must still be served within 45 days.","ref":["Florida Contractors Manual  ·  2025: 9-92: 713.18(2)(b)","2021: 9-84: 713.18(2)(b)","2017: 9-101: 713.18(2)(b)"],"lock":1},{"id":"3-106","exam":3,"num":106,"stem":"Given: A contractor hires a day laborer at a rate of $35.00 for one day's work. The contractor uses the laborer for six days in one workweek. The laborer average 8-1/2 hours of work per day. The laborer is entitled to __________. Select the closest answer.","options":["A gross pay of $199.45 for the six days of work","A gross pay of $210.00 for the six days of work","A gross pay of $232.66 for the six days of work","A gross pay of $409.63 for the six days of work"],"answer":3,"topic":"labor","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"5-21"}],"exp":"The day rate gives $210 for 51 hours = $4.12/hr, which is below the $7.25 minimum wage. So pay at minimum wage: 40 hrs × $7.25 = $290, plus overtime of 11 hrs × $7.25 × 1.5 = $119.63. Total **$409.63**.","tip":"Check the regular rate against minimum wage before figuring overtime.","calc":1,"ref":["Florida Contractor's Manual  ·  5-21","Total pay for 6 days x $35.00 = $210.00","Total hours worked 6 days x 8.5 hours = 51 hours","Employee's regular rate of pay - $210.00","$210.00 ÷ 51 hours = $4.12 per hour","Note: Federal minimum wage of $7.25 applies","Regular Pay = 40 hours x $7.25 = $290.00","Overtime = 11 hours x $7.25 x 1.5 = $119.63","Total pay = $290.00 + $119.63 = $409.63"]},{"id":"3-107","exam":3,"num":107,"stem":"Which of the following is considered a type of accrual?","options":["Cash or other payments received","Billings mailed out, but not yet paid","Anticipated profit from uncompleted work","Estimated cost of work not yet completed"],"answer":1,"topic":"acct","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"11"},{"book":"BGA","eds":null,"loc":"237"}],"exp":"**Billings mailed but not yet paid** (accounts receivable) are an accrual. The revenue is earned, but the cash hasn't come in.","ref":["Builder's Guide to Accounting  ·  11 or 237"]},{"id":"3-108","exam":3,"num":108,"stem":"The ratios used to judge the cash position of a company are called __________.","options":["Balance Ratios","Accruals","Combination Ratios","Liquidity Tests"],"answer":3,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"174"}],"exp":"Ratios that judge cash position are **liquidity tests** (current ratio, quick ratio).","ref":["Builder's Guide to Accounting  ·  174"]},{"id":"3-109","exam":3,"num":109,"stem":"A company has estimated net income of $1,200,000.00. In order to achieve a margin of profit of 37%, the company's sales should be __________.","options":["$2,702,000.00","$2,444,000.00","$1,444,000.00","$3,243,243.00"],"answer":3,"topic":"ratio","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"272"}],"exp":"Profit margin = net income ÷ sales, so sales = net income ÷ margin = $1,200,000 ÷ 0.37 = **$3,243,243**.","calc":1,"ref":["Builder's Guide to Accounting  ·  272","Net Income/Sales = Margin of profit","$1,200,000 / x = 37% = $3,243,243"],"lock":1},{"id":"3-110","exam":3,"num":110,"stem":"What is the term for the effective annual interest charged on the principal borrowed?","options":["Discount","Rate","Loan","Finance charge"],"answer":1,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-73"}],"exp":"The effective annual interest charged on the principal borrowed is the **rate**.","ref":["Florida Contractors Manual  ·  3-73"]},{"id":"3-111","exam":3,"num":111,"stem":"According to the Florida \"Statute of Frauds\", the following contracts must be in writing to be enforceable except __________.","options":["A lease of real property for less than 1 year","A contract for the sale of real property","A contract that cannot be performed in less than one year","An agreement to submit disputes to arbitration"],"answer":0,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"8-7"}],"exp":"Florida's Statute of Frauds requires writing for real estate sales, contracts that can't be done within a year, and arbitration agreements. **A lease of real property for less than 1 year** can be oral.","ref":["Florida Contractors Manual  ·  8-7"]},{"id":"3-112","exam":3,"num":112,"stem":"The break-even point __________.","options":["Distinguishes between the various yields of the different jobs and job types","Can help the contractor decide what kinds of work he or she needs to reach a volume goal","Encourages growth","Indicates the minimum sales you need to break even"],"answer":3,"topic":"job","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"179"}],"exp":"The breakeven point **shows the minimum sales you need to break even** (no profit, no loss).","ref":["Builder's Guide to Accounting  ·  179"]},{"id":"3-113","exam":3,"num":113,"stem":"When a business is structured as a joint venture __________.","options":["An oral agreement between the parties is recommended","There must be a formal partnership agreement","Its activity is generally limited to a single transaction","Venture members have limited personal liability"],"answer":2,"topic":"org","books":["FCM"],"cites":[{"book":"FCM","eds":["2025"],"loc":"1-10"},{"book":"FCM","eds":["2021"],"loc":"1-10"},{"book":"FCM","eds":["2021"],"loc":"1-11"},{"book":"FCM","eds":["2017"],"loc":"1-12"},{"book":"FCM","eds":["2017"],"loc":"1-13"}],"exp":"A joint venture's activity is generally **limited to a single transaction or project**.","ref":["Florida Contractors Manual  ·  2025: 1-10","2021: 1-10, 1-11","2017: 1-12, 1-13"]},{"id":"3-114","exam":3,"num":114,"stem":"A bid bond guarantees that when the contract is awarded, the bidder will __________.","options":["Submit a breakdown of the bid together with a list of subcontractors","Enter the contract at the bid price","Submit copies of all bid documents for the owner's review","Submit a statement of the contractor's qualifications and past performance"],"answer":1,"topic":"ins","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-105"},{"book":"FCM","eds":null,"loc":"4-13"},{"book":"FCM","eds":null,"loc":"10-73"}],"exp":"A bid bond guarantees the bidder will **enter into the contract at the bid price** (and provide the required bonds).","ref":["Florida Contractors Manual  ·  3-105, 4-13, 10-73"]},{"id":"3-115","exam":3,"num":115,"stem":"Which one of the following is an incentive to pay an invoice early or when due?","options":["Credit","Rebate","Discount","Additional contracts"],"answer":2,"topic":"cash","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"59"}],"exp":"A **discount** for prompt payment is the incentive to pay early or on time.","ref":["Builder's Guide to Accounting  ·  59"]},{"id":"3-116","exam":3,"num":116,"stem":"All the following are examples of types of offers in construction contracts except __________.","options":["Bids","Purchase orders","Proposals","Negotiations"],"answer":3,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"8-5"}],"exp":"Bids, purchase orders and proposals are all offers. **Negotiations** are discussions, not offers.","ref":["Florida Contractors Manual  ·  8-5"]},{"id":"3-117","exam":3,"num":117,"stem":"A concrete subcontractor is asked to provide a cost estimate to extend a concrete foundation from 60' x 80' to 80' x 100'. The contractor determines that the 60' x 80' foundation cost $4,500 and that the additional work would cost $1.25/sq. ft. extra. This method of estimating is called the __________.","options":["Approximate estimated method","Detailed survey method","Square footage method","Unit price method"],"answer":2,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-12"}],"exp":"Pricing the extra work by area ($1.25 per added square foot) is the **square footage method**.","ref":["Florida Contractors Manual  ·  10-12"]},{"id":"3-118","exam":3,"num":118,"stem":"CSI Master Format divides the specifications into how many specific divisions?","options":["15","50","18","40"],"answer":1,"topic":"est","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-7"}],"exp":"CSI MasterFormat (2004 and later) has **50 divisions** (00–49). The old format had 16.","ref":["Florida Contractors Manual  ·  10-7"],"lock":1},{"id":"3-119","exam":3,"num":119,"stem":"Which is the best method to check an estimate in order to eliminate as many errors as possible?","options":["Have another estimator take the original estimate and recheck the figures and computations","Compare the original estimate with an estimate from a similar project","Perform the estimating process a second time and compare it with the initial estimate","Have another estimator make an independent estimate and compare it to the original estimate"],"answer":1,"topic":"est","books":["BGA"],"cites":[{"book":"BGA","eds":null,"loc":"11"},{"book":"BGA","eds":null,"loc":"225"}],"exp":"Per the Builder's Guide (p. 225), the recommended check is to **compare the estimate with one from a similar project**.","ref":["Builder's Guide to Accounting  ·  11 or 225"]},{"id":"3-120","exam":3,"num":120,"stem":"The maximum penalty for knowingly making false statements, representations, or certification in any application, record, report, plan or other document filed as part of the OSHA requirements is a fine and term of imprisonment of not more than __________.","options":["$1,000 and 60 days","$5,000 and 6 months","$10,000 and 6 months","$100,000 and 1 year"],"answer":2,"topic":"osha","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"7-17"}],"exp":"Knowingly making false statements in OSHA records or reports: up to **$10,000 and 6 months in jail**.","ref":["Florida Contractors Manual  ·  7-17"]},{"id":"3-121","exam":3,"num":121,"stem":"What is the MAJOR difference between the various types of negotiated contracts, such as lump-sum, cost-plus or guaranteed maximum price?","options":["The relationship between the owner and the contractor","The relationship between the architect and the contractor","The provision regarding liability of the contractor","The provision regarding compensation of the contractor"],"answer":3,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"10-35"}],"exp":"Lump-sum, cost-plus and GMP contracts differ mainly in **how the contractor is paid** (compensation).","ref":["Florida Contractors Manual  ·  10-35"]},{"id":"3-122","exam":3,"num":122,"stem":"Some types of cost-plus contracts could be ___________________.","options":["Cost plus interest and cost-plus allowances","Cost plus fixed fee and cost-plus percentage of reimbursable costs","Cost plus inflation and cost-plus markup","Cost plus damages and cost-plus profit"],"answer":1,"topic":"law","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-79"}],"exp":"Cost-plus contracts include **cost plus a fixed fee and cost plus a percentage of reimbursable costs**.","ref":["Florida Contractors Manual  ·  3-79"]},{"id":"3-123","exam":3,"num":123,"stem":"The complaint and all information obtained pursuant to the investigation by the department are confidential until __________ days after probable cause has been found to exist by the probable cause panel or by the department.","options":["5","10","15","20"],"answer":1,"topic":"dbpr","books":["FS455"],"cites":[{"book":"FS455","eds":null,"loc":"455.225(10)"}],"exp":"§455.225(10): the complaint and investigation records stay confidential until **10 days** after probable cause is found.","ref":["Florida Statute 455  ·  455.225(10)"],"lock":1},{"id":"3-124","exam":3,"num":124,"stem":"A (An) ____________ loan accrues interest until maturity and is paid in one payment which covers the principal and interest at the maturity date of the loan.","options":["Project","Term","Interest","Subordinated loan"],"answer":1,"topic":"cash","books":["FCM"],"cites":[{"book":"FCM","eds":null,"loc":"3-73"}],"exp":"Per the manual, a **term loan** accrues interest until maturity and is repaid in one payment of principal and interest on the maturity date.","ref":["Florida Contractors Manual  ·  3-73"]},{"id":"3-125","exam":3,"num":125,"stem":"A claim for a contract adjustment, because of concealed conditions, must be made within __________.","options":["Ten days after the first observance of the condition","Fourteen days after the first observance of the condition","Ten days after the date the architect has seen the condition","Twenty-one days after the architect has given notice of the decision"],"answer":1,"topic":"aia","books":["A201"],"cites":[{"book":"A201","eds":null,"loc":"3.7.4"}],"exp":"A201 §3.7.4: claims for concealed conditions must be made within **14 days** of first observing the condition.","ref":["AIA Document A201, 2017  ·  3.7.4"]}];
